// ============================================
// NAVIGATION
// ============================================
function activateSection(tab) {
  const btn = document.querySelector('.nav button[data-tab="' + tab + '"]');
  const section = document.getElementById('sec-' + tab);
  if (!btn || !section) return;

  document.querySelectorAll('.nav button').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
  section.classList.add('active');
  btn.scrollIntoView({ behavior:'smooth', block:'nearest', inline:'center' });

  if (tab === 'bodymap') initBodyMap();
  if (tab === 'freenotes') initFreeNotesCanvas();
  if (tab === 'exercises') renderExercises();
  if (tab === 'iceheat' && typeof onIceHeatAreaChange === 'function') onIceHeatAreaChange();
  if (tab === 'exam') renderRegionTabs();
  if (tab === 'imaging') {
    // Auto-populate the first time the user opens the tab in this visit
    if (!document.getElementById('imgPatientSummary').dataset.populated) {
      refreshImagingFromNotes();
      document.getElementById('imgPatientSummary').dataset.populated = '1';
    }
  }
  if (tab === 'cert') {
    if (!document.getElementById('certPatientSummary').dataset.populated) {
      refreshCertFromNotes();
      document.getElementById('certPatientSummary').dataset.populated = '1';
    }
  }
  if (tab === 'report') updateReferralFilters();
  updateNextSectionButton();
}

document.querySelectorAll('.nav button').forEach(btn => {
  btn.addEventListener('click', () => {
    activateSection(btn.dataset.tab);
  });
});

function updateNextSectionButton() {
  const navButtons = Array.from(document.querySelectorAll('.nav button[data-tab]'));
  const activeIndex = navButtons.findIndex(btn => btn.classList.contains('active'));
  const activeSection = activeIndex >= 0 ? document.getElementById('sec-' + navButtons[activeIndex].dataset.tab) : null;
  let wrap = document.getElementById('sectionNextNav');

  if (!wrap) {
    wrap = document.createElement('div');
    wrap.id = 'sectionNextNav';
    wrap.className = 'section-next-nav no-print';
    wrap.innerHTML = "<button id=\"sectionNextButton\" class=\"section-next-button\" type=\"button\" data-cc-click=\"goToNextSection()\"><span><span class=\"next-caption\">Next section</span><span id=\"sectionNextName\" class=\"next-name\"></span></span><span class=\"next-arrow\" aria-hidden=\"true\">→</span></button>";
  }

  if (!activeSection || activeIndex < 0 || activeIndex >= navButtons.length - 1) {
    wrap.remove();
    return;
  }

  activeSection.appendChild(wrap);
  document.getElementById('sectionNextName').textContent = navButtons[activeIndex + 1].textContent.trim();
  document.getElementById('sectionNextButton').removeAttribute('aria-label'); // v6 audit: the visible text is the name (WCAG 2.5.3 label in name)
}

function goToNextSection() {
  const navButtons = Array.from(document.querySelectorAll('.nav button[data-tab]'));
  const activeIndex = navButtons.findIndex(btn => btn.classList.contains('active'));
  if (activeIndex < 0 || activeIndex >= navButtons.length - 1) return;
  activateSection(navButtons[activeIndex + 1].dataset.tab);
  window.scrollTo({ top:0, behavior:'smooth' });
}

// V4.5.2 safety: if the Examination tab is already active after load, render C/S immediately.
setTimeout(function(){
  var examSection = document.getElementById('sec-exam');
  if (examSection && examSection.classList.contains('active')) renderRegionTabs();
}, 0);

// ============================================
// VISIT TYPE
// ============================================
function setVisitType(type, el) {
  APP.visitType = type;
  el.parentElement.querySelectorAll('.chip').forEach(c => c.classList.remove('active'));
  el.classList.add('active');
  document.getElementById('followupLoad').style.display = type === 'followup' ? 'block' : 'none';
  if (type === 'followup') loadSavedVisits();
}

function toggleChip(el) {
  el.classList.toggle('active');
  if (el.closest && el.closest('#conditions')) syncMedicationSectionsFromConditions(el);
}

function toggleExamRegion(el) {
  el.classList.toggle('active');
  const region = el.dataset.region;
  if (el.classList.contains('active')) {
    if (!APP.activeRegions.includes(region)) APP.activeRegions.push(region);
    // Last selected region owns the exam. Overlap (shoulder/C-S, hip/lumbar,
    // hip/pelvis, knee/hip) must not leave the previous region's fields up.
    APP.currentRegion = region;
  } else {
    APP.activeRegions = APP.activeRegions.filter(r => r !== region);
    if (APP.currentRegion === region) APP.currentRegion = APP.activeRegions[APP.activeRegions.length - 1] || null;
  }
  renderRegionTabs();
}

