function hasScode(region) {
  var D = getExamData(region);
  var icd = (D.icd10 || '') + '|' + (D.icd10_2 || '');
  return /^S/i.test(D.icd10 || '') || /^S/i.test(D.icd10_2 || '');
}

function buildExtCauseSearchHTML(region, currentVal) {
  var displayText = '';
  if (currentVal) {
    for (var i = 0; i < EXT_CAUSE_CODES.length; i++) {
      if (EXT_CAUSE_CODES[i].code === currentVal) { displayText = currentVal + ' \u2014 ' + EXT_CAUSE_CODES[i].desc; break; }
    }
    if (!displayText) displayText = currentVal;
  }
  return '<div class="icd-search-wrap">' +
    '<input type="text" value="' + (displayText||'').replace(/"/g,'&quot;') + '" ' +
      'placeholder="Search external cause code or description..." ' +
      "data-cc-focus=\"extCauseFocus(this,'" + region + '\')" ' +
      "data-cc-input=\"extCauseSearch(this,'" + region + '\')" ' +
      "data-cc-keydown=\"extCauseKey(event,this)\" " +
      'data-region="' + region + '" data-code="' + (currentVal||'') + '">' +
    "<button class=\"icd-clear\" data-cc-click=\"extCauseClear(this.previousElementSibling,'" + region + '\')" style="' + (currentVal ? '' : 'display:none') + '">&times;</button>' +
    '<div class="icd-results" id="extres_' + region + '"></div>' +
  '</div>';
}

function extCauseFocus(input, region) {
  if (input.dataset.code) { input.value = ''; input.dataset.code = ''; }
  extCauseRender(region, input.value);
}

function extCauseSearch(input, region) {
  input.dataset.code = '';
  input.nextElementSibling.style.display = input.value ? 'block' : 'none';
  extCauseRender(region, input.value);
}

function extCauseRender(region, query) {
  var container = document.getElementById('extres_' + region);
  if (!container) return;
  var q = (query || '').toLowerCase().trim();
  var results = [];
  for (var i = 0; i < EXT_CAUSE_CODES.length; i++) {
    if (!q || EXT_CAUSE_CODES[i].code.toLowerCase().indexOf(q) >= 0 || EXT_CAUSE_CODES[i].desc.toLowerCase().indexOf(q) >= 0) {
      results.push(EXT_CAUSE_CODES[i]);
    }
  }
  var html = '';
  if (results.length === 0 && q) {
    html = '<div class="icd-empty">No matches \u2014 press Enter to use "' + q + '" as custom code</div>';
  } else {
    for (var i = 0; i < Math.min(results.length, 50); i++) {
      html += '<div class="icd-item" data-code="' + results[i].code + '" data-desc="' + results[i].desc.replace(/"/g,'&quot;') + "\" data-cc-click=\"extCausePick(this,'" + region + '\')">' +
        '<span class="icd-code">' + results[i].code + '</span><span class="icd-desc">' + results[i].desc + '</span></div>';
    }
    if (results.length > 50) html += '<div class="icd-empty">Type to narrow results (' + results.length + ' total)</div>';
  }
  container.innerHTML = html;
  container.classList.add('show');
  container.scrollTop = 0;
}

function extCausePick(item, region) {
  var code = item.dataset.code;
  var desc = item.dataset.desc;
  var container = document.getElementById('extres_' + region);
  var input = container.previousElementSibling.previousElementSibling;
  input.value = code + ' \u2014 ' + desc;
  input.dataset.code = code;
  input.nextElementSibling.style.display = 'block';
  getExamData(region).extCause = code;
  container.classList.remove('show');
}

function extCauseKey(e, input) {
  var region = input.dataset.region;
  if (e.key === 'Enter') {
    e.preventDefault();
    var container = document.getElementById('extres_' + region);
    var first = container.querySelector('.icd-item');
    if (first) { extCausePick(first, region); }
    else if (input.value.trim()) { input.dataset.code = input.value.trim(); getExamData(region).extCause = input.value.trim(); container.classList.remove('show'); }
  } else if (e.key === 'Escape') { document.getElementById('extres_' + region).classList.remove('show'); input.blur(); }
}

function extCauseClear(input, region) {
  input.value = ''; input.dataset.code = ''; input.nextElementSibling.style.display = 'none';
  getExamData(region).extCause = '';
  document.getElementById('extres_' + region).classList.remove('show');
  input.focus();
}

