function getPatternsByRegion(region) {
  return CLINICAL_PATTERNS.filter(function(p) { return p.regions.indexOf(region) >= 0; });
}

function applyPattern(region, patternIndex) {
  var patterns = getPatternsByRegion(region);
  var p = patterns[patternIndex];
  if (!p) return;
  var D = getExamData(region);

  // Store active pattern for exercise recommendations
  APP.activePattern = p.name;
  D.clinicalImpression = p.impression;
  var impEl = document.querySelector('#soap-assess textarea[placeholder*="correlating"]');
  if (impEl) impEl.value = p.impression;

  // Fill DDx (structured + legacy textarea)
  if (p.ddx) {
    dxEnsureDdxState(D);
    D.ddxClinicianLocked = false;
    D.ddxDismissedIds = [];
    D.ddxReviewed = false;
    var ddxItems = dxDdxFromPattern(p);
    // Enrich lightly with map/region alts excluding primary
    var condLabel0 = (typeof PATTERN_CONDITION_LABELS !== 'undefined' && PATTERN_CONDITION_LABELS[p.name]) ? PATTERN_CONDITION_LABELS[p.name] : p.name;
    var enriched = computeFormulatedDdx(region, condLabel0, (p.suggestedICD && p.suggestedICD[0]) || '');
    // Prefer pattern items first
    var seenP = {};
    var mergedP = [];
    ddxItems.concat(enriched).forEach(function(it){
      if (!it || !it.label) return;
      var id = it.id || dxMakeDdxId(it.label, it.code);
      if (seenP[id]) return;
      seenP[id] = true;
      mergedP.push(it);
    });
    syncDdxIntoExam(region, mergedP.slice(0, 6), { force: true, syncSecondary: true, forceSecondary: !D.secondaryDx });
    var ddxEl = document.querySelector('#soap-assess textarea[placeholder*="differential"]');
    if (ddxEl) ddxEl.value = D.ddx || p.ddx;
  }

  // Suggest ICD-10 / condition — never silently overwrite after confirm
  if (D.dxConfirmed) {
    showToast('Pattern impression/DDx applied. Unlock confirmed diagnosis to change condition/ICD.');
  } else {
    if ((!D.icd10 || !D.dxIcdLocked) && p.suggestedICD && p.suggestedICD.length > 0) {
      D.icd10 = p.suggestedICD[0];
      D.formulatedIcd10 = p.suggestedICD[0];
      D.dxIcdLocked = false;
    }
    if (!D.icd10_2 && p.suggestedICD && p.suggestedICD.length > 1) {
      D.icd10_2 = p.suggestedICD[1];
    }
    var condLabel = (typeof PATTERN_CONDITION_LABELS !== 'undefined' && PATTERN_CONDITION_LABELS[p.name]) ? PATTERN_CONDITION_LABELS[p.name] : p.name;
    if (!D.dxConditionLocked || !D.primaryDx) {
      D.formulatedCondition = condLabel;
      D.primaryDx = condLabel;
      D.dxConditionLocked = false;
    }
    D.dxConfirmed = false;
  }

  // Suggest additional exam regions
  if (p.regions.length > 1) {
    p.regions.forEach(function(r) {
      if (APP.activeRegions.indexOf(r) === -1) {
        APP.activeRegions.push(r);
        var chip = document.querySelector('#examRegionSelect .chip[data-region="'+r+'"]');
        if (chip) chip.classList.add('active');
      }
    });
  }

  // Close pattern dropdown
  document.getElementById('patternResults_' + region).classList.remove('show');

  // Added overlap regions stay available as tabs, but the panel stays on
  // the region this pattern was applied to (not a neighbour such as C/S).
  APP.currentRegion = resolveExamRegion(region) || region;
  renderRegionTabs();
  showToast('Pattern applied \u2014 review and adjust findings');
}

function buildPatternSearchHTML(region) {
  var patterns = getPatternsByRegion(region);
  if (patterns.length === 0) return '';
  return '<div style="margin-top:10px">' +
    '<label>Clinical Biomechanical Patterns <span style="font-weight:400;color:var(--text3)">\u2014 auto-fills impression, DDx &amp; ICD-10</span></label>' +
    '<div class="icd-search-wrap">' +
      '<input type="text" placeholder="Search patterns (e.g. upper cross, trochanteric, disc...)" ' +
        "data-cc-focus=\"patternSearchRender('" + region + '\',this.value)" ' +
        "data-cc-input=\"patternSearchRender('" + region + '\',this.value)">' +
      '<div class="icd-results" id="patternResults_' + region + '"></div>' +
    '</div></div>';
}

function patternSearchRender(region, query) {
  var container = document.getElementById('patternResults_' + region);
  if (!container) return;
  var patterns = getPatternsByRegion(region);
  var q = (query || '').toLowerCase().trim();
  var html = '';
  var count = 0;
  for (var i = 0; i < patterns.length; i++) {
    var p = patterns[i];
    if (!q || p.name.toLowerCase().indexOf(q) >= 0 || p.impression.toLowerCase().indexOf(q) >= 0 ||
        p.keyFindings.join(' ').toLowerCase().indexOf(q) >= 0) {
      html += "<div class=\"icd-item\" data-cc-click=\"applyPattern('" + region + '\',' + i + ')" style="padding:10px 12px">' +
        '<div style="font-weight:600;color:var(--accent);font-size:12px;margin-bottom:2px">' + p.name + '</div>' +
        '<div style="font-size:11px;color:var(--text2)">' + p.keyFindings.slice(0, 4).join(' \u2022 ') + (p.keyFindings.length > 4 ? ' \u2026' : '') + '</div>' +
      '</div>';
      count++;
    }
  }
  if (count === 0) html = '<div class="icd-empty">No matching patterns</div>';
  container.innerHTML = html;
  container.classList.add('show');
}

function buildICD10SearchHTML(region, field, currentVal) {
  var displayText = '';
  if (currentVal) {
    var codes = ICD10_CODES[region] || [];
    for (var i = 0; i < codes.length; i++) {
      if (codes[i].code === currentVal) { displayText = currentVal + ' \u2014 ' + codes[i].desc; break; }
    }
    if (!displayText) displayText = currentVal;
  }
  var inputVal = currentVal ? displayText : '';
  return '<div class="icd-search-wrap">' +
    '<input type="text" value="' + inputVal.replace(/"/g,'&quot;') + '" ' +
      'placeholder="Search code or diagnosis..." ' +
      "data-cc-focus=\"icd10Focus(this,'" + region + '\',\'' + field + '\')" ' +
      "data-cc-input=\"icd10Search(this,'" + region + '\',\'' + field + '\')" ' +
      "data-cc-keydown=\"icd10Key(event,this)\" " +
      'data-region="' + region + '" data-field="' + field + '" data-code="' + (currentVal||'') + '">' +
    "<button class=\"icd-clear\" data-cc-click=\"icd10Clear(this.previousElementSibling,'" + region + '\',\'' + field + '\')" style="' + (currentVal ? '' : 'display:none') + '">&times;</button>' +
    '<div class="icd-results" id="icd10res_' + region + '_' + field + '"></div>' +
  '</div>';
}

function icd10Focus(input, region, field) {
  var query = input.dataset.code ? '' : input.value;
  if (input.dataset.code) { input.value = ''; input.dataset.code = ''; }
  icd10Render(region, field, query);
}

function icd10Search(input, region, field) {
  input.dataset.code = '';
  var clear = input.nextElementSibling;
  clear.style.display = input.value ? 'block' : 'none';
  icd10Render(region, field, input.value);
}

function icd10Render(region, field, query) {
  var container = document.getElementById('icd10res_' + region + '_' + field);
  if (!container) return;
  var codes = ICD10_CODES[region] || [];
  var q = (query || '').toLowerCase().trim();
  var results = [];

  for (var i = 0; i < codes.length; i++) {
    if (!q || codes[i].code.toLowerCase().indexOf(q) >= 0 || codes[i].desc.toLowerCase().indexOf(q) >= 0) {
      results.push(codes[i]);
    }
  }

  // Also search other regions if query is specific enough
  var otherResults = [];
  if (q.length >= 2) {
    var regionNames = {cs:'C/S',ts:'T/S',ls:'L/S',pelvis:'Pelvis',hip:'Hip',shoulder:'Shoulder',elbow:'Elbow',wrist:'Wrist',knee:'Knee',ankle:'Ankle'};
    var otherKeys = Object.keys(ICD10_CODES);
    for (var k = 0; k < otherKeys.length; k++) {
      if (otherKeys[k] === region) continue;
      var oCodes = ICD10_CODES[otherKeys[k]];
      for (var j = 0; j < oCodes.length; j++) {
        if (oCodes[j].code.toLowerCase().indexOf(q) >= 0 || oCodes[j].desc.toLowerCase().indexOf(q) >= 0) {
          // Avoid duplicates
          var isDup = false;
          for (var r = 0; r < results.length; r++) { if (results[r].code === oCodes[j].code) { isDup = true; break; } }
          for (var r = 0; r < otherResults.length; r++) { if (otherResults[r].code === oCodes[j].code) { isDup = true; break; } }
          if (!isDup) otherResults.push({code: oCodes[j].code, desc: oCodes[j].desc, from: regionNames[otherKeys[k]]});
        }
      }
    }
  }

  var html = '';
  if (results.length === 0 && otherResults.length === 0 && q) {
    html = '<div class="icd-empty">No matches \u2014 press Enter to use "' + q + '" as custom code</div>';
  } else {
    if (results.length > 0) {
      for (var i = 0; i < results.length; i++) {
        html += '<div class="icd-item" data-code="' + results[i].code + '" data-desc="' + results[i].desc.replace(/"/g,'&quot;') + "\" data-cc-click=\"icd10Pick(this,'" + region + '\',\'' + field + '\')">' +
          '<span class="icd-code">' + results[i].code + '</span><span class="icd-desc">' + results[i].desc + '</span></div>';
      }
    }
    if (otherResults.length > 0) {
      html += '<div class="icd-cat">From other regions</div>';
      for (var i = 0; i < otherResults.length; i++) {
        html += '<div class="icd-item" data-code="' + otherResults[i].code + '" data-desc="' + otherResults[i].desc.replace(/"/g,'&quot;') + "\" data-cc-click=\"icd10Pick(this,'" + region + '\',\'' + field + '\')">' +
          '<span class="icd-code">' + otherResults[i].code + '</span><span class="icd-desc">' + otherResults[i].desc + ' <small style=\'color:var(--text3)\'>(' + otherResults[i].from + ')</small></span></div>';
      }
    }
  }

  container.innerHTML = html;
  container.classList.add('show');
  container.scrollTop = 0;
}

function icd10Pick(item, region, field) {
  var code = item.dataset.code;
  var desc = item.dataset.desc;
  var container = document.getElementById('icd10res_' + region + '_' + field);
  var input = container.previousElementSibling.previousElementSibling;
  input.value = code + ' \u2014 ' + desc;
  input.dataset.code = code;
  input.nextElementSibling.style.display = 'block';
  var D = getExamData(region);
  D[field] = code;
  if (field === 'icd10') {
    D.formulatedIcd10 = code;
    if (!D.dxConfirmed) D.dxIcdLocked = true;
    try { refreshFormulatedDxStatus(region); } catch(e) {}
  }
  container.classList.remove('show');
}

function icd10Key(e, input) {
  var region = input.dataset.region;
  var field = input.dataset.field;
  if (e.key === 'Enter') {
    e.preventDefault();
    var container = document.getElementById('icd10res_' + region + '_' + field);
    var first = container.querySelector('.icd-item');
    if (first) {
      icd10Pick(first, region, field);
    } else if (input.value.trim()) {
      // Custom code
      input.dataset.code = input.value.trim();
      getExamData(region)[field] = input.value.trim();
      container.classList.remove('show');
    }
  } else if (e.key === 'Escape') {
    var container = document.getElementById('icd10res_' + region + '_' + field);
    container.classList.remove('show');
    input.blur();
  }
}

function icd10Clear(input, region, field) {
  input.value = '';
  input.dataset.code = '';
  input.nextElementSibling.style.display = 'none';
  getExamData(region)[field] = '';
  var container = document.getElementById('icd10res_' + region + '_' + field);
  container.classList.remove('show');
  input.focus();
}

// Close ICD-10 dropdowns on outside click
document.addEventListener('click', function(e) {
  if (!e.target.closest('.icd-search-wrap')) {
    document.querySelectorAll('.icd-results.show').forEach(function(el) { el.classList.remove('show'); });
    // Restore display text for any unfocused inputs with a selected code
    document.querySelectorAll('.icd-search-wrap input[data-code]').forEach(function(inp) {
      if (inp.dataset.code && document.activeElement !== inp) {
        var region = inp.dataset.region;
        var code = inp.dataset.code;
        var codes = ICD10_CODES[region] || [];
        for (var i = 0; i < codes.length; i++) {
          if (codes[i].code === code) { inp.value = code + ' \u2014 ' + codes[i].desc; return; }
        }
        inp.value = code;
      }
    });
  }
});

