function findConditionExercises() {
  var matched = [];
  var usedIds = {};
  // Check all active exam regions for ICD-10 codes and diagnoses
  APP.activeRegions.forEach(function(r) {
    var D = APP.examData[r] || {};
    var codes = [D.icd10||'', D.icd10_2||'', D.formulatedIcd10||''];
    var dxText = ((D.primaryDx||'') + ' ' + (D.secondaryDx||'') + ' ' + (D.formulatedCondition||'') + (D.dxConfirmed ? ' confirmed' : '')).toLowerCase();
    CONDITION_EXERCISES.forEach(function(cond) {
      if (usedIds[cond.id]) return;
      // Match by ICD-10 code
      for (var c = 0; c < codes.length; c++) {
        if (codes[c]) {
          for (var j = 0; j < cond.codes.length; j++) {
            if (codes[c] === cond.codes[j] || codes[c].indexOf(cond.codes[j]) === 0) {
              matched.push(cond); usedIds[cond.id] = true; return;
            }
          }
        }
      }
      // Match by keyword in diagnosis text
      if (dxText.length > 2) {
        for (var k = 0; k < cond.keywords.length; k++) {
          if (dxText.indexOf(cond.keywords[k].toLowerCase()) >= 0) {
            matched.push(cond); usedIds[cond.id] = true; return;
          }
        }
      }
    });
  });
  return matched;
}



function renderExercises() {
  var region = document.getElementById('exRegion').value;
  var list = EXERCISES[currentExCat] && EXERCISES[currentExCat][region] ? EXERCISES[currentExCat][region] : [];
  var container = document.getElementById('exerciseList');
  container.innerHTML = '';

  // Map tab to category tag
  var catMap = {stretch:'s', strength:'r', mobility:'m', nerve:'n'};
  var activeCat = catMap[currentExCat] || 's';

  var allConditions = [];
  var recommendedNames = {};

  // 1. Pattern-based
  var patternName = APP.activePattern || '';
  var patternEx = PATTERN_EXERCISES[patternName] || null;
  if (patternEx) {
    allConditions.push({name: patternName, stages: patternEx, source: 'pattern'});
  }

  // 2. ICD-10 / diagnosis-based
  var condMatches = findConditionExercises();
  condMatches.forEach(function(cond) {
    var isDup = false;
    for (var i = 0; i < allConditions.length; i++) {
      if (allConditions[i].name === cond.name) { isDup = true; break; }
    }
    if (!isDup) allConditions.push({name: cond.name, stages: cond.stages, source: 'icd10'});
  });

  // Build recommended names (only for active category)
  allConditions.forEach(function(c) {
    c.stages.forEach(function(stage) {
      stage.items.forEach(function(item) {
        if (!item.cat || item.cat === activeCat) recommendedNames[item.name] = true;
      });
    });
  });

  // Render condition-specific blocks (filtered by category)
  var hasConditionContent = false;
  if (allConditions.length > 0) {
    allConditions.forEach(function(cond) {
      // Filter stages to only include items matching active category
      var filteredStages = [];
      cond.stages.forEach(function(stage) {
        var filtered = stage.items.filter(function(item) { return !item.cat || item.cat === activeCat; });
        if (filtered.length > 0) filteredStages.push({stage:stage.stage, stageClass:stage.stageClass, desc:stage.desc, items:filtered});
      });
      if (filteredStages.length === 0) return;
      hasConditionContent = true;

      var recDiv = document.createElement('div');
      recDiv.className = 'ex-recommended';
      var sourceLabel = cond.source === 'pattern' ? '\u2605 Clinical Pattern' : '\u2605 ICD-10 Matched';
      var catLabel = currentExCat.charAt(0).toUpperCase() + currentExCat.slice(1);
      var recHTML = '<div class="ex-rec-title">' + sourceLabel + ' \u2014 ' + catLabel + '</div>';
      recHTML += '<div class="ex-rec-subtitle">' + cond.name + '</div>';
      filteredStages.forEach(function(stage) {
        recHTML += '<div class="ex-stage">';
        recHTML += '<div class="ex-stage-header"><span class="ex-stage-label ' + stage.stageClass + '">' + stage.stage + '</span><span class="ex-stage-desc">' + stage.desc + '</span></div>';
        stage.items.forEach(function(item) {
          var imgBtn = "<button type=\"button\" class=\"ex-img-btn\" data-cc-click=\"showExerciseImageFromBtn(this)\">🖼 Image</button>";
                    var _idesc = getExerciseDescription(item.name);
          recHTML += '<div class="exercise-card recommended"><div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><label style="margin:0;flex:1"><input type="checkbox" style="width:auto;margin-right:8px">' + escapeExHtml(item.name) + '</label>' + imgBtn + '</div>' + (_idesc ? '<div class="ex-desc">' + escapeExHtml(_idesc) + '</div>' : '') + '<div class="ex-rx">' + item.rx + '</div></div>';
        });
        recHTML += '</div>';
      });
      recDiv.innerHTML = recHTML;
      container.appendChild(recDiv);
    });
    if (hasConditionContent) {
      container.innerHTML += '<hr class="ex-divider"><div class="ex-divider-label">General ' + currentExCat + ' exercises \u2014 ' + region + '</div>';
    }
  }

  if (!list.length && !hasConditionContent) {
    container.innerHTML += '<p style="color:var(--text3);font-size:12px">No ' + currentExCat + ' exercises for this condition/region.</p>';
    return;
  }
  list.forEach(function(ex) {
    var isRec = recommendedNames[ex.name] ? ' recommended' : '';
    var div = document.createElement('div');
    div.className = 'exercise-card' + isRec;
    var _desc = getExerciseDescription(ex.name);
    div.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><label style="margin:0;flex:1"><input type="checkbox" style="width:auto;margin-right:8px">' + escapeExHtml(ex.name) + "</label><button type=\"button\" class=\"ex-img-btn\" data-cc-click=\"showExerciseImageFromBtn(this)\">🖼 Image</button></div>" + (_desc ? '<div class="ex-desc">' + escapeExHtml(_desc) + '</div>' : '') + '<div style="margin-top:6px"><input placeholder="Sets × Reps / Duration" style="font-size:12px"></div>';
    container.appendChild(div);
  });
}

// PDF LETTERHEAD + EMAIL (no external library)
// ============================================
function miniPDFTextOnly(subject, contentText, patientName) {
  var PP = ccPdfProf(); // P1 latest v4: Profile values, not hard-coded
  var date = new Date().toLocaleDateString('en-ZA',{year:'numeric',month:'long',day:'numeric'});
  var pw = 595.28, ph = 841.89; // A4
  var ml = 71, mr = 71, tw = pw - ml - mr;
  var streams = [], currentPage = 0;
  var s = '';
  var LHP = lhRawPdf(pw, ph);
  s += LHP.pageOps(true);

  function rgb(r,g,b) { return (r/255).toFixed(3)+' '+(g/255).toFixed(3)+' '+(b/255).toFixed(3); }
  function esc(t) { return toLatin1(t).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)'); }
  function rect(x,y,w,h,r,g,b) { s += rgb(r,g,b)+' rg '+x.toFixed(2)+' '+(ph-y-h).toFixed(2)+' '+w.toFixed(2)+' '+h.toFixed(2)+' re f\n'; }
  function strokeRect(x,y,w,h,r,g,b) { s += rgb(r,g,b)+' RG 0.5 w '+x.toFixed(2)+' '+(ph-y-h).toFixed(2)+' '+w.toFixed(2)+' '+h.toFixed(2)+' re S\n'; }
  function txt(str,x,y,size,r,g,b,font) {
    font = font || 'F1';
    s += 'BT\n/'+font+' '+size+' Tf\n'+rgb(r,g,b)+' rg\n'+x.toFixed(2)+' '+(ph-y).toFixed(2)+' Td\n('+esc(str)+') Tj\nET\n';
  }
  function newPage() { if(s) streams.push(s); s = ''; currentPage++; s += LHP.pageOps(false); }
  function wrapLines(text, maxW, size) {
    var charW = size * 0.52;
    var maxChars = Math.floor(maxW / charW);
    var result = [];
    var paragraphs = text.split('\n');
    for (var p = 0; p < paragraphs.length; p++) {
      var para = paragraphs[p];
      if (para.length === 0) { result.push(''); continue; }
      while (para.length > 0) {
        if (para.length <= maxChars) { result.push(para); break; }
        var cut = para.lastIndexOf(' ', maxChars);
        if (cut <= 0) cut = maxChars;
        result.push(para.substring(0, cut));
        para = para.substring(cut).replace(/^\s/,'');
      }
    }
    return result;
  }

  var HDR = ccHdrPracCols(PP, pw, ml, mr); // P1 latest v5: wrap/fit long Profile addresses
  if (!LHP.custom) {
  // === HEADER BAR ===
  rect(0, 0, pw, HDR.band, 43, 95, 92);
  rect(0, HDR.band, pw, 5.5, 201, 149, 107); // gold accent

  // Name + credentials
  txt(PP.name, ml, 38, 18, 255, 255, 255, 'F2');
  txt(PP.quals, ml, 56, 9, 220, 235, 235, 'F1');
  txt('Practice Number: ' + PP.prNo, ml, 70, 8, 200, 220, 220, 'F1');

  // Thin separator line in header
  s += rgb(255,255,255)+' RG 0.3 w '+(ml).toFixed(2)+' '+(ph-84).toFixed(2)+' m '+(pw-mr).toFixed(2)+' '+(ph-84).toFixed(2)+' l S\n';

  // Practice columns (left: first practice, right: second), wrapped to the column width
  ccHdrPracDraw(HDR, PP, txt);

  }

  // === BODY ===
  var y = LHP.custom ? LHP.top : 158 + HDR.shift;
  txt(date, ml, y, 9, 138, 138, 138, 'F1');
  y += 24;
  txt('Dear ' + (patientName || 'Patient') + ',', ml, y, 11, 45, 45, 45, 'F1');
  y += 20;

  // Content
  var lines = wrapLines(contentText || '', tw, 10);
  for (var i = 0; i < lines.length; i++) {
    if (y > LHP.limit(ph - 160)) { newPage(); y = LHP.contY(70); }
    txt(lines[i], ml, y, 10, 45, 45, 45, 'F1');
    y += 14;
  }

  // === DISCLAIMER BOX ===
  y += 16;
  if (y > LHP.limit(ph - 160)) { newPage(); y = LHP.contY(70); }
  var discText = 'Dear patient, please note this treatment is specific for your condition based upon your examination. Please do not deviate from the instructions. In case of an adverse reaction, stop all treatment and call ' + (PP.name || 'your practitioner') + ' immediately.';
  var discLines = wrapLines(discText, tw - 20, 8);
  var discH = discLines.length * 11 + 16;

  // Light background box
  rect(ml, y, tw, discH, 247, 245, 242);
  strokeRect(ml, y, tw, discH, 224, 220, 215);

  // Disclaimer text
  y += 12;
  for (var d = 0; d < discLines.length; d++) {
    txt(discLines[d], ml + 10, y, 8, 90, 90, 90, 'F3');
    y += 11;
  }
  y += 12;

  // === CLOSING ===
  y += 12;
  if (y > LHP.limit(ph - 100)) { newPage(); y = LHP.contY(70); }
  txt('Kind regards,', ml, y, 10, 45, 45, 45, 'F1');
  y += 22;
  txt(PP.name, ml, y, 11, 43, 95, 92, 'F2');
  y += 14;
  txt(PP.quals, ml, y, 8, 138, 138, 138, 'F1');
  y += 10;
  txt('Practice Nr: ' + PP.prNo, ml, y, 8, 138, 138, 138, 'F1');

  if (!LHP.custom) {
  // === FOOTER ===
  s += rgb(224,220,215)+' RG 0.5 w '+ml.toFixed(2)+' 52 m '+(pw-mr).toFixed(2)+' 52 l S\n';
  txt('Generated by ChiroClinic on ' + date, pw/2 - 80, ph - 40, 7, 138, 138, 138, 'F1');
  txt('Confidential \u2014 intended for the named recipient only', pw/2 - 95, ph - 28, 7, 138, 138, 138, 'F1');

  }
  streams.push(s);

  // === BUILD PDF ===
  var objs = [];
  function obj(content) { objs.push(content); return objs.length; }

  obj('<<  /Type /Catalog /Pages 2 0 R >>');
  obj('PAGES_PLACEHOLDER');
  obj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
  obj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  obj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Oblique /Encoding /WinAnsiEncoding >>');

  var lhRes = LHP.emit(obj);
  var pageRefs = [];
  for (var p = 0; p < streams.length; p++) {
    var streamBytes = streams[p];
    var streamObjNum = obj('<< /Length ' + streamBytes.length + ' >>\nstream\n' + streamBytes + 'endstream');
    var pageObjNum = obj('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+pw.toFixed(2)+' '+ph.toFixed(2)+'] /Contents '+streamObjNum+' 0 R /Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R >>' + (lhRes ? ' /XObject <<' + lhRes + ' >>' : '') + ' >> >>');
    pageRefs.push(pageObjNum + ' 0 R');
  }

  objs[1] = '<< /Type /Pages /Kids [' + pageRefs.join(' ') + '] /Count ' + streams.length + ' >>';

  var pdf = '%PDF-1.4\n';
  var offsets = [];
  for (var i = 0; i < objs.length; i++) {
    offsets.push(pdf.length);
    pdf += (i+1) + ' 0 obj\n' + objs[i] + '\nendobj\n';
  }
  var xrefOffset = pdf.length;
  pdf += 'xref\n0 ' + (objs.length+1) + '\n0000000000 65535 f \n';
  for (var i = 0; i < offsets.length; i++) {
    pdf += String(offsets[i]).padStart(10,'0') + ' 00000 n \n';
  }
  pdf += 'trailer\n<< /Size '+(objs.length+1)+' /Root 1 0 R >>\nstartxref\n'+xrefOffset+'\n%%EOF';

  return pdf;
}

async function shareLetterPDFTextOnly(subject, contentText, patientName, patientEmail) {
  if (window.CCPractice && !CCPractice.requireAll('Exercise letter', lhEffective().mode === 'default')) return; // P1 latest v4: no empty Profile field on the letter
  try {
    showToast('Generating PDF...');
    var pdfStr = miniPDFTextOnly(subject, contentText, patientName);
    var bytes = new Uint8Array(pdfStr.length);
    for (var i = 0; i < pdfStr.length; i++) bytes[i] = pdfStr.charCodeAt(i) & 0xFF;
    var blob = new Blob([bytes], { type: 'application/pdf' });
    var fileName = subject.replace(/[^a-zA-Z0-9 ]/g, '').replace(/\s+/g, '_') + '.pdf';
    var file = new File([blob], fileName, { type: 'application/pdf' });

    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({
        title: subject,
        text: 'Dear ' + (patientName || 'Patient') + ', please see the attached instructions.',
        files: [file]
      });
      showToast('Letter shared!');
    } else {
      var a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = fileName;
      a.click();
      URL.revokeObjectURL(a.href);
      showToast('PDF downloaded \u2014 attach it to your email');
      if (patientEmail) {
        var ms = encodeURIComponent(subject);
        var mb = encodeURIComponent('Dear '+(patientName||'Patient')+',\n\nPlease see the attached instructions.\n\n'+ccLetterSignoff());
        setTimeout(function(){ window.open('mailto:'+patientEmail+'?subject='+ms+'&body='+mb); }, 600);
      }
    }
  } catch(err) {
    if (err.name !== 'AbortError') { console.error(err); showToast(err.message || 'Error generating PDF'); }
  }
}

function _jpegDims(byteStr) {
  var i = 2; // skip SOI FF D8
  while (i < byteStr.length - 9) {
    if (byteStr.charCodeAt(i) !== 0xFF) return null;
    var marker = byteStr.charCodeAt(i+1);
    if ((marker >= 0xC0 && marker <= 0xC3) ||
        (marker >= 0xC5 && marker <= 0xC7) ||
        (marker >= 0xC9 && marker <= 0xCB) ||
        (marker >= 0xCD && marker <= 0xCF)) {
      var h = (byteStr.charCodeAt(i+5) << 8) | byteStr.charCodeAt(i+6);
      var w = (byteStr.charCodeAt(i+7) << 8) | byteStr.charCodeAt(i+8);
      return { width: w, height: h };
    }
    var segLen = (byteStr.charCodeAt(i+2) << 8) | byteStr.charCodeAt(i+3);
    if (segLen <= 0) return null;
    i += 2 + segLen;
  }
  return null;
}

function _dataUrlToBytes(dataUrl) {
  try { return atob(dataUrl.split(',')[1] || ''); } catch (e) { return ''; }
}


function miniPDF(subject, contentText, patientName, opts) {
  var PP = ccPdfProf(); // P1 latest v4: Profile values, not hard-coded
  opts = opts || {};
  var imageDataUrl = opts.imageDataUrl || null;
  var imageCaption = opts.imageCaption || '';
  var date = new Date().toLocaleDateString('en-ZA',{year:'numeric',month:'long',day:'numeric'});
  var pw = 595.28, ph = 841.89; // A4
  var ml = 71, mr = 71, tw = pw - ml - mr;
  var streams = [], currentPage = 0;
  var s = '';
  var LHP = lhRawPdf(pw, ph);
  s += LHP.pageOps(true);

  // Pre-decode image (if provided) so we can size it during layout
  var imgBytes = null, imgW = 0, imgH = 0, dispW = 0, dispH = 0;
  if (imageDataUrl) {
    imgBytes = _dataUrlToBytes(imageDataUrl);
    var dims = imgBytes ? _jpegDims(imgBytes) : null;
    if (dims && dims.width && dims.height) {
      imgW = dims.width; imgH = dims.height;
      var maxW = Math.min(tw, 320);
      var maxH = 360;
      var scale = Math.min(maxW / imgW, maxH / imgH);
      dispW = imgW * scale;
      dispH = imgH * scale;
    } else {
      imgBytes = null; // bail if we can't parse
    }
  }

  function rgb(r,g,b) { return (r/255).toFixed(3)+' '+(g/255).toFixed(3)+' '+(b/255).toFixed(3); }
  function esc(t) { return toLatin1(t).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)'); }
  function rect(x,y,w,h,r,g,b) { s += rgb(r,g,b)+' rg '+x.toFixed(2)+' '+(ph-y-h).toFixed(2)+' '+w.toFixed(2)+' '+h.toFixed(2)+' re f\n'; }
  function strokeRect(x,y,w,h,r,g,b) { s += rgb(r,g,b)+' RG 0.5 w '+x.toFixed(2)+' '+(ph-y-h).toFixed(2)+' '+w.toFixed(2)+' '+h.toFixed(2)+' re S\n'; }
  function txt(str,x,y,size,r,g,b,font) {
    font = font || 'F1';
    s += 'BT\n/'+font+' '+size+' Tf\n'+rgb(r,g,b)+' rg\n'+x.toFixed(2)+' '+(ph-y).toFixed(2)+' Td\n('+esc(str)+') Tj\nET\n';
  }
  function newPage() { if(s) streams.push(s); s = ''; currentPage++; s += LHP.pageOps(false); }
  function wrapLines(text, maxW, size) {
    var charW = size * 0.52;
    var maxChars = Math.floor(maxW / charW);
    var result = [];
    var paragraphs = text.split('\n');
    for (var p = 0; p < paragraphs.length; p++) {
      var para = paragraphs[p];
      if (para.length === 0) { result.push(''); continue; }
      while (para.length > 0) {
        if (para.length <= maxChars) { result.push(para); break; }
        var cut = para.lastIndexOf(' ', maxChars);
        if (cut <= 0) cut = maxChars;
        result.push(para.substring(0, cut));
        para = para.substring(cut).replace(/^\s/,'');
      }
    }
    return result;
  }

  var HDR = ccHdrPracCols(PP, pw, ml, mr); // P1 latest v5: wrap/fit long Profile addresses
  if (!LHP.custom) {
  // === HEADER BAR ===
  rect(0, 0, pw, HDR.band, 43, 95, 92);
  rect(0, HDR.band, pw, 5.5, 201, 149, 107); // gold accent

  // Name + credentials
  txt(PP.name, ml, 38, 18, 255, 255, 255, 'F2');
  txt(PP.quals, ml, 56, 9, 220, 235, 235, 'F1');
  txt('Practice Number: ' + PP.prNo, ml, 70, 8, 200, 220, 220, 'F1');

  // Thin separator line in header
  s += rgb(255,255,255)+' RG 0.3 w '+(ml).toFixed(2)+' '+(ph-84).toFixed(2)+' m '+(pw-mr).toFixed(2)+' '+(ph-84).toFixed(2)+' l S\n';

  // Practice columns (left: first practice, right: second), wrapped to the column width
  ccHdrPracDraw(HDR, PP, txt);

  }

  // === BODY ===
  var y = LHP.custom ? LHP.top : 158 + HDR.shift;
  txt(date, ml, y, 9, 138, 138, 138, 'F1');
  y += 24;
  txt('Dear ' + (patientName || 'Patient') + ',', ml, y, 11, 45, 45, 45, 'F1');
  y += 20;

  // Content
  var lines = wrapLines(contentText || '', tw, 10);
  for (var i = 0; i < lines.length; i++) {
    if (y > LHP.limit(ph - 160)) { newPage(); y = LHP.contY(70); }
    txt(lines[i], ml, y, 10, 45, 45, 45, 'F1');
    y += 14;
  }

  // === EMBEDDED IMAGE (e.g. ice/heat placement) ===
  if (imgBytes) {
    y += 10;
    // Make sure we have enough space; else start a new page
    if (y + dispH + 30 > ph - 100) { newPage(); y = LHP.contY(70); }
    var imgX = ml + (tw - dispW) / 2;
    var imgY = y;
    // Border around image
    strokeRect(imgX - 2, imgY - 2, dispW + 4, dispH + 4, 200, 200, 200);
    // q a b c d e f cm /Im1 Do Q  — image origin is bottom-left in PDF coords
    s += 'q\n' + dispW.toFixed(2) + ' 0 0 ' + dispH.toFixed(2) + ' ' + imgX.toFixed(2) + ' ' + (ph - imgY - dispH).toFixed(2) + ' cm\n/Im1 Do\nQ\n';
    y += dispH + 8;
    if (imageCaption) {
      txt(imageCaption, ml, y, 8, 110, 110, 110, 'F3');
      y += 14;
    }
  }

  // === DISCLAIMER BOX ===
  y += 16;
  if (y > LHP.limit(ph - 160)) { newPage(); y = LHP.contY(70); }
  var discText = 'Dear patient, please note this treatment is specific for your condition based upon your examination. Please do not deviate from the instructions. In case of an adverse reaction, stop all treatment and call ' + (PP.name || 'your practitioner') + ' immediately.';
  var discLines = wrapLines(discText, tw - 20, 8);
  var discH = discLines.length * 11 + 16;

  // Light background box
  rect(ml, y, tw, discH, 247, 245, 242);
  strokeRect(ml, y, tw, discH, 224, 220, 215);

  // Disclaimer text
  y += 12;
  for (var d = 0; d < discLines.length; d++) {
    txt(discLines[d], ml + 10, y, 8, 90, 90, 90, 'F3');
    y += 11;
  }
  y += 12;

  // === CLOSING ===
  y += 12;
  if (y > LHP.limit(ph - 100)) { newPage(); y = LHP.contY(70); }
  txt('Kind regards,', ml, y, 10, 45, 45, 45, 'F1');
  y += 22;
  txt(PP.name, ml, y, 11, 43, 95, 92, 'F2');
  y += 14;
  txt(PP.quals, ml, y, 8, 138, 138, 138, 'F1');
  y += 10;
  txt('Practice Nr: ' + PP.prNo, ml, y, 8, 138, 138, 138, 'F1');

  if (!LHP.custom) {
  // === FOOTER ===
  s += rgb(224,220,215)+' RG 0.5 w '+ml.toFixed(2)+' 52 m '+(pw-mr).toFixed(2)+' 52 l S\n';
  txt('Generated by ChiroClinic on ' + date, pw/2 - 80, ph - 40, 7, 138, 138, 138, 'F1');
  txt('Confidential \u2014 intended for the named recipient only', pw/2 - 95, ph - 28, 7, 138, 138, 138, 'F1');

  }
  streams.push(s);

  // === BUILD PDF ===
  var objs = [];
  function obj(content) { objs.push(content); return objs.length; }

  obj('<<  /Type /Catalog /Pages 2 0 R >>');
  obj('PAGES_PLACEHOLDER');
  obj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
  obj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  obj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Oblique /Encoding /WinAnsiEncoding >>');

  // Image XObject (if any) — emitted with raw JPEG bytes (DCTDecode filter)
  var imageObjNum = 0;
  var resourcesXObj = '';
  var imXObj = '';
  if (imgBytes) {
    imageObjNum = obj('<< /Type /XObject /Subtype /Image /Width ' + imgW + ' /Height ' + imgH + ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ' + imgBytes.length + ' >>\nstream\n' + imgBytes + '\nendstream');
    imXObj = ' /Im1 ' + imageObjNum + ' 0 R';
  }

  var lhRes = LHP.emit(obj);
  if (imXObj || lhRes) resourcesXObj = ' /XObject <<' + imXObj + lhRes + ' >>';
  var pageRefs = [];
  for (var p = 0; p < streams.length; p++) {
    var streamBytes = streams[p];
    var streamObjNum = obj('<< /Length ' + streamBytes.length + ' >>\nstream\n' + streamBytes + 'endstream');
    var pageObjNum = obj('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+pw.toFixed(2)+' '+ph.toFixed(2)+'] /Contents '+streamObjNum+' 0 R /Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R >>' + resourcesXObj + ' >> >>');
    pageRefs.push(pageObjNum + ' 0 R');
  }

  objs[1] = '<< /Type /Pages /Kids [' + pageRefs.join(' ') + '] /Count ' + streams.length + ' >>';

  var pdf = '%PDF-1.4\n';
  var offsets = [];
  for (var i = 0; i < objs.length; i++) {
    offsets.push(pdf.length);
    pdf += (i+1) + ' 0 obj\n' + objs[i] + '\nendobj\n';
  }
  var xrefOffset = pdf.length;
  pdf += 'xref\n0 ' + (objs.length+1) + '\n0000000000 65535 f \n';
  for (var i = 0; i < offsets.length; i++) {
    pdf += String(offsets[i]).padStart(10,'0') + ' 00000 n \n';
  }
  pdf += 'trailer\n<< /Size '+(objs.length+1)+' /Root 1 0 R >>\nstartxref\n'+xrefOffset+'\n%%EOF';

  return pdf;
}

async function shareLetterPDF(subject, contentText, patientName, patientEmail, opts) {
  if (window.CCPractice && !CCPractice.requireAll('Exercise letter', lhEffective().mode === 'default')) return; // P1 latest v4: no empty Profile field on the letter
  try {
    showToast('Generating PDF...');
    var pdfStr = miniPDF(subject, contentText, patientName, opts || {});
    var bytes = new Uint8Array(pdfStr.length);
    for (var i = 0; i < pdfStr.length; i++) bytes[i] = pdfStr.charCodeAt(i) & 0xFF;
    var blob = new Blob([bytes], { type: 'application/pdf' });
    var fileName = subject.replace(/[^a-zA-Z0-9 ]/g, '').replace(/\s+/g, '_') + '.pdf';
    var file = new File([blob], fileName, { type: 'application/pdf' });

    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({
        title: subject,
        text: 'Dear ' + (patientName || 'Patient') + ', please see the attached instructions.',
        files: [file]
      });
      showToast('Letter shared!');
    } else {
      var a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = fileName;
      a.click();
      URL.revokeObjectURL(a.href);
      showToast('PDF downloaded \u2014 attach it to your email');
      if (patientEmail) {
        var ms = encodeURIComponent(subject);
        var mb = encodeURIComponent('Dear '+(patientName||'Patient')+',\n\nPlease see the attached instructions.\n\n'+ccLetterSignoff());
        setTimeout(function(){ window.open('mailto:'+patientEmail+'?subject='+ms+'&body='+mb); }, 600);
      }
    }
  } catch(err) {
    if (err.name !== 'AbortError') { console.error(err); showToast(err.message || 'Error generating PDF'); }
  }
}


function getSelectedExercises() {
  var selected = [];
  var cards = document.querySelectorAll('#exerciseList .exercise-card');
  cards.forEach(function(card) {
    var cb = card.querySelector('input[type="checkbox"]');
    if (cb && cb.checked) {
      var label = cb.parentElement ? cb.parentElement.textContent.trim() : '';
      var rxInput = card.querySelector('input[placeholder]');
      var rx = '';
      if (rxInput) { rx = rxInput.value || rxInput.placeholder || ''; }
      // Also check for .ex-rx (recommended exercises have rx in a div)
      var rxDiv = card.querySelector('.ex-rx');
      if (rxDiv && !rx) rx = rxDiv.textContent.trim();
      if (rxDiv && !rxInput) rx = rxDiv.textContent.trim();
      selected.push({ name: label, rx: rx });
    }
  });
  return selected;
}

function emailExercises() {
  var email = document.getElementById('ptEmail').value;
  var custom = document.getElementById('exCustomInstructions').value;
  var name = document.getElementById('ptFirstName').value;
  var region = document.getElementById('exRegion').value;
  if (!email) { showToast('Please enter patient email on Patient tab'); return; }

  var selected = getSelectedExercises();
  var body = 'Please find your prescribed exercise instructions below:\n\n';

  if (selected.length > 0) {
    body += 'TARGET REGION: ' + region + '\n';
    body += '────────────────────────────────────\n\n';
    for (var i = 0; i < selected.length; i++) {
      var ex = selected[i];
      body += (i + 1) + '. ' + ex.name + '\n';
      var _ed=getExerciseDescription(ex.name); if (_ed) body += '   ' + _ed + '\n';
      if (ex.rx) body += '   Prescription: ' + ex.rx + '\n';
      body += '\n';
    }
    body += '────────────────────────────────────\n';
  } else {
    body += '(No exercises selected — please check the exercises you wish to prescribe)\n';
  }

  if (custom) {
    body += '\nADDITIONAL INSTRUCTIONS:\n' + custom + '\n';
  }

  if (selected.length === 0 && !custom) { showToast('Please select exercises or add custom instructions'); return; }

  shareLetterPDF('Exercise Instructions - ' + (loadProfile().name || 'ChiroClinic'), body.trim(), name, email);
}



