// Get the image key from area/side/variant/modality selections.
function getIceHeatImageKey(area, side, variant, modality) {
  var entry = null;
  if (ICEHEAT_NO_SIDE_REGIONS[area]) {
    entry = ICEHEAT_KEYS[area];
  } else if (ICEHEAT_VARIANT_REGIONS[area]) {
    entry = ICEHEAT_KEYS[area + '|' + side + '|' + variant];
  } else {
    entry = ICEHEAT_KEYS[area + '|' + side];
  }
  if (!entry) return null;
  // Contrast uses Ice image first (cold phase shown for placement reference)
  return (modality === 'Heat') ? entry.Heat : entry.Ice;
}

// Build full clinical description text for current selections.
function getIceHeatDescriptionHTML(area, side, variant, modality) {
  var d = ICEHEAT_DESCRIPTIONS[area];
  if (!d) return '<em style="color:var(--text3)">No description for this area.</em>';
  var placement = (typeof d.placement === 'string') ? d.placement : (d.placement[variant] || d.placement['Posterior'] || '');
  var indHeat = d.indications_heat || '';
  var indIce  = d.indications_ice  || '';
  var cautions = d.cautions || '';
  var modBlock = '';
  if (modality === 'Heat') {
    modBlock = '<div style="margin-top:8px"><strong style="color:#c0392b">Heat indications:</strong> ' + indHeat + '</div>';
  } else if (modality === 'Ice') {
    modBlock = '<div style="margin-top:8px"><strong style="color:#24599a">Ice indications:</strong> ' + indIce + '</div>';
  } else {
    modBlock = '<div style="margin-top:8px"><strong style="color:#24599a">Ice (first 10 min):</strong> ' + indIce + '</div>'
             + '<div style="margin-top:6px"><strong style="color:#c0392b">Heat (next 10 min):</strong> ' + indHeat + '</div>';
  }
  var header = area + (ICEHEAT_NO_SIDE_REGIONS[area] ? '' : ' — ' + side + (ICEHEAT_VARIANT_REGIONS[area] ? ' (' + variant + ')' : ''));
  return '<div style="font-weight:600;font-size:14px;margin-bottom:6px">' + header + '</div>'
       + '<div><strong>Placement:</strong> ' + placement + '</div>'
       + modBlock
       + '<div style="margin-top:8px;padding-top:8px;border-top:1px dashed var(--border)"><strong style="color:#6e5630">Cautions:</strong> ' + cautions + '</div>';
}

// Plain-text variant for the PDF letter.
function getIceHeatDescriptionText(area, side, variant, modality) {
  var d = ICEHEAT_DESCRIPTIONS[area];
  if (!d) return '';
  var placement = (typeof d.placement === 'string') ? d.placement : (d.placement[variant] || d.placement['Posterior'] || '');
  var header = area + (ICEHEAT_NO_SIDE_REGIONS[area] ? '' : ' - ' + side + (ICEHEAT_VARIANT_REGIONS[area] ? ' (' + variant + ')' : ''));
  var out = 'AREA DETAIL: ' + header + '\n';
  out += '\nPlacement: ' + placement + '\n';
  if (modality === 'Heat') {
    out += '\nHeat indications: ' + d.indications_heat + '\n';
  } else if (modality === 'Ice') {
    out += '\nIce indications: ' + d.indications_ice + '\n';
  } else {
    out += '\nIce phase (first 10 min): ' + d.indications_ice + '\n';
    out += '\nHeat phase (next 10 min): ' + d.indications_heat + '\n';
  }
  out += '\nCautions: ' + d.cautions + '\n';
  return out;
}

// Toggle Side / Variant rows based on selected area.
function onIceHeatAreaChange() {
  var area = document.getElementById('ihArea').value;
  var sideRow = document.getElementById('ihSideRow');
  var variantRow = document.getElementById('ihVariantRow');
  sideRow.style.display = ICEHEAT_NO_SIDE_REGIONS[area] ? 'none' : '';
  variantRow.style.display = ICEHEAT_VARIANT_REGIONS[area] ? '' : 'none';
  renderIceHeatPreview();
}


// Shared helper: keys that reuse a contralateral image and need horizontal mirror
// in preview, modal, email/PDF data-URL, and any print path. #25 now ships a real
// flipped JPG (25_Wrist_Right_Heat.jpg), so the set is empty — keep the helper so
// future mirrored keys cannot be forgotten by one export path.
function iceHeatNeedsMirror(key) {
  var MIRRORED_ICEHEAT_KEYS = {
    // '25_Wrist_Right_Heat': true  // retired — real asset generated 2026-09-27
  };
  return !!(key && MIRRORED_ICEHEAT_KEYS[key]);
}

// Update inline image + description.
function renderIceHeatPreview() {
  var area = document.getElementById('ihArea').value;
  var side = document.getElementById('ihSide') ? document.getElementById('ihSide').value : 'Left';
  var variant = document.getElementById('ihVariant') ? document.getElementById('ihVariant').value : 'Posterior';
  var modality = document.getElementById('ihModality').value;

  var key = getIceHeatImageKey(area, side, variant, modality);
  var imgEl = document.getElementById('ihImage');
  var emptyEl = document.getElementById('ihImageEmpty');
  var imgData = key && ICEHEAT_IMAGES[key];
  if (imgData) {
    imgEl.src = imgData;
    imgEl.style.display = '';
    emptyEl.style.display = 'none';
    var needsMirror = iceHeatNeedsMirror(key);
    imgEl.style.transform = needsMirror ? 'scaleX(-1)' : '';
    imgEl.dataset.mirrored = needsMirror ? 'true' : 'false';
    imgEl.dataset.iceheatKey = key || '';
    var displayModality = modality.indexOf('Contrast') === 0 ? 'Ice first' : modality;
    var labelParts = [];
    if (!ICEHEAT_NO_SIDE_REGIONS[area]) labelParts.push(side);
    labelParts.push(area);
    if (ICEHEAT_VARIANT_REGIONS[area]) labelParts.push(variant + ' view');
    labelParts.push(displayModality);
    var label = labelParts.join(' • ');
    imgEl.dataset.caption = label;
    var labelEl = document.getElementById('ihImageLabel');
    if (labelEl) { labelEl.textContent = label; labelEl.style.display = ''; }
  } else {
    imgEl.style.display = 'none';
    imgEl.removeAttribute('src');
    imgEl.style.transform = '';
    emptyEl.style.display = '';
    var labelEl = document.getElementById('ihImageLabel');
    if (labelEl) labelEl.style.display = 'none';
  }

  var descEl = document.getElementById('ihDescription');
  descEl.innerHTML = getIceHeatDescriptionHTML(area, side, variant, modality);
}

function openIceHeatModal() {
  var imgEl = document.getElementById('ihImage');
  if (!imgEl || !imgEl.src || imgEl.style.display === 'none') return;
  var modal = document.createElement('div');
  modal.className = 'ex-img-modal';
  var caption = imgEl.dataset.caption || 'Ice/Heat placement';
  var needsMirror = imgEl.dataset.mirrored === 'true' || iceHeatNeedsMirror(imgEl.dataset.iceheatKey);
  var mirrorStyle = needsMirror ? ' style="transform:scaleX(-1)"' : '';
  modal.innerHTML = '<div style="max-width:90vw;text-align:center"><img src="' + imgEl.src + '" alt="' + caption + '"' + mirrorStyle + '><div class="ex-img-caption">' + caption + ' — tap anywhere to close</div></div>';
  modal.addEventListener('click', function() { document.body.removeChild(modal); });
  document.body.appendChild(modal);
}

function iceHeatImageToDataUrl(src, mirrored) {
  return fetch(src).then(function(response) {
    if (!response.ok) throw new Error('Placement image could not be loaded');
    return response.blob();
  }).then(function(blob) {
    return new Promise(function(resolve, reject) {
      var objectUrl = URL.createObjectURL(blob);
      var img = new Image();
      img.onload = function() {
        try {
          var canvas = document.createElement('canvas');
          canvas.width = img.naturalWidth;
          canvas.height = img.naturalHeight;
          var ctx = canvas.getContext('2d');
          if (mirrored) { ctx.translate(canvas.width, 0); ctx.scale(-1, 1); }
          ctx.drawImage(img, 0, 0);
          URL.revokeObjectURL(objectUrl);
          resolve(canvas.toDataURL('image/jpeg', 0.9));
        } catch (err) { URL.revokeObjectURL(objectUrl); reject(err); }
      };
      img.onerror = function() { URL.revokeObjectURL(objectUrl); reject(new Error('Placement image could not be prepared')); };
      img.src = objectUrl;
    });
  });
}

async function emailIceHeat() {
  var email = document.getElementById('ptEmail').value;
  var custom = document.getElementById('ihCustom').value;
  var mod = document.getElementById('ihModality').value;
  var area = document.getElementById('ihArea').value;
  var side = document.getElementById('ihSide') ? document.getElementById('ihSide').value : '';
  var variant = document.getElementById('ihVariant') ? document.getElementById('ihVariant').value : '';
  var dur = document.getElementById('ihDuration').value;
  var freq = document.getElementById('ihFreq').value;
  var name = document.getElementById('ptFirstName').value;
  if (!email) { showToast('Please enter patient email on Patient tab'); return; }

  var areaLabel = area;
  if (!ICEHEAT_NO_SIDE_REGIONS[area]) areaLabel += ' (' + side + (ICEHEAT_VARIANT_REGIONS[area] ? ', ' + variant : '') + ')';

  var body = 'Please follow the instructions below for your home care:\n\n';
  body += 'MODALITY: ' + mod + '\n';
  body += 'AREA: ' + areaLabel + '\n';
  body += 'DURATION: ' + dur + '\n';
  body += 'FREQUENCY: ' + freq + '\n';

  var descText = getIceHeatDescriptionText(area, side, variant, mod);
  if (descText) body += '\n' + descText;

  if (mod === 'Ice') {
    body += '\nIMPORTANT:\n- Always wrap the ice pack in a thin cloth or towel — never apply directly to skin.\n- If the area becomes numb or excessively red, remove the ice immediately.\n';
  } else if (mod === 'Heat') {
    body += '\nIMPORTANT:\n- Do not apply heat to acute injuries or swollen areas.\n- Use moderate warmth — do not fall asleep on a heating pad.\n';
  } else if (mod.indexOf('Contrast') >= 0) {
    body += '\nIMPORTANT:\n- Start with ice, then switch to heat.\n- Apply ice for 10 minutes, then heat for 10 minutes. Repeat as instructed.\n';
  }

  if (custom) {
    body += '\nADDITIONAL INSTRUCTIONS:\n' + custom + '\n';
  }

  var key = getIceHeatImageKey(area, side, variant, mod);
  var imageDataUrl = null;
  if (key && ICEHEAT_IMAGES[key]) {
    try { imageDataUrl = await iceHeatImageToDataUrl(ICEHEAT_IMAGES[key], iceHeatNeedsMirror(key)); }
    catch (err) { console.warn(err); showToast('Image unavailable; creating text instructions'); }
  }
  await shareLetterPDF(mod + ' Instructions - ' + (loadProfile().name || 'ChiroClinic'), body.trim(), name, email, {
    imageDataUrl: imageDataUrl,
    imageCaption: imageDataUrl ? ('Placement reference: ' + areaLabel + ' — ' + (mod.indexOf('Contrast') === 0 ? 'Ice first' : mod)) : ''
  });
}

