// P1 v6 audit (XSS): escape user-entered text before it is put into HTML (print windows, lists). Display text is unchanged.
function ccH(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); }
function ccSafeImgSrc(u) { u = String(u || ''); return /^data:image\/(png|jpe?g|gif|webp|svg\+xml);base64,[A-Za-z0-9+\/=\s]+$/i.test(u) || /^(https?:|blob:|\.?\/)/i.test(u) && !/["'<>\s]/.test(u) ? u : ''; }
function ccEscObj(o) { const r = {}; Object.keys(o || {}).forEach(k => { const v = o[k]; r[k] = (typeof v === 'string') ? (k === 'signature' || k === 'logo' ? ccSafeImgSrc(v) : ccH(v)) : v; }); return r; }
function loadProfile() {
  try {
    const raw = localStorage.getItem('chiroclinic_profile');
    if (!raw) return Object.assign({}, PROFILE_DEFAULTS);
    return Object.assign({}, PROFILE_DEFAULTS, JSON.parse(raw));
  } catch(e) { return Object.assign({}, PROFILE_DEFAULTS); }
}

// P1 latest v5: browser tab title and top bar come from the Profile (fallback "ChiroClinic")
function ccApplyProfileHeader() {
  let p = {}; try { p = loadProfile() || {}; } catch (e) {}
  const name = String(p.name || '').trim(), quals = String(p.quals || '').trim(), prNo = String(p.prNo || '').trim();
  document.title = name ? 'ChiroClinic — ' + name : 'ChiroClinic';
  const h = document.getElementById('hdrName'); if (h) { h.textContent = name || 'ChiroClinic'; h.title = name || 'ChiroClinic'; }
  const sub = document.getElementById('hdrSub'); if (sub) sub.textContent = [quals, prNo ? 'Pr nr: ' + prNo : ''].filter(Boolean).join('  |  ');
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', ccApplyProfileHeader); else setTimeout(ccApplyProfileHeader, 0);
window.addEventListener('storage', function (e) { if (!e || e.key === 'chiroclinic_profile') ccApplyProfileHeader(); });

function showProfileModal() {
  const p = loadProfile();
  document.getElementById('prfName').value = p.name;
  document.getElementById('prfQuals').value = p.quals;
  document.getElementById('prfPrNo').value = p.prNo;
  document.getElementById('prfHpcsa').value = p.hpcsa;
  document.getElementById('prfMobile').value = p.mobile;
  document.getElementById('prfEmail').value = p.email;
  document.getElementById('prfMelkbosstrandAddr').value = p.melkbosAddr;
  document.getElementById('prfMelkbosstrandPhone').value = p.melkbosPhone;
  document.getElementById('prfMelkbosstrandEmail').value = p.melkbosEmail;
  document.getElementById('prfVredAddr').value = p.vredAddr;
  document.getElementById('prfVredPhone').value = p.vredPhone;
  document.getElementById('prfVredEmail').value = p.vredEmail;
  renderSignaturePreview(p.signature);
  lhFillForm();
  document.getElementById('profileModal').classList.add('show');
}

function renderSignaturePreview(dataUrl) {
  const box = document.getElementById('prfSigPreview');
  if (dataUrl) {
    box.innerHTML = '<img src="' + dataUrl + '" alt="Signature" style="max-width:100%;max-height:120px">';
  } else {
    box.innerHTML = '<em style="color:var(--text3);font-size:12px">No signature uploaded</em>';
  }
}

function handleSignatureUpload(e) {
  const file = e.target.files[0];
  if (!file) return;
  if (file.size > 2 * 1024 * 1024) { showToast('Signature image too large (max 2 MB)'); return; }
  const reader = new FileReader();
  reader.onload = function(ev) {
    // Resize to max 600x200 to keep storage reasonable
    const img = new Image();
    img.onload = function() {
      const canvas = document.createElement('canvas');
      const maxW = 600, maxH = 200;
      let w = img.width, h = img.height;
      const ratio = Math.min(maxW / w, maxH / h, 1);
      w = Math.round(w * ratio);
      h = Math.round(h * ratio);
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext('2d');
      ctx.clearRect(0, 0, w, h);
      ctx.drawImage(img, 0, 0, w, h);
      const dataUrl = canvas.toDataURL('image/png');
      document.getElementById('prfSigPreview').dataset.signature = dataUrl;
      renderSignaturePreview(dataUrl);
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
}

function clearSignature() {
  document.getElementById('prfSigPreview').dataset.signature = '';
  renderSignaturePreview('');
}

function saveProfile() {
  if (!lhSaveFromForm()) return;
  const sig = document.getElementById('prfSigPreview').dataset.signature ||
              (document.querySelector('#prfSigPreview img') ? document.querySelector('#prfSigPreview img').src : '') ||
              loadProfile().signature;
  const profile = {
    name: document.getElementById('prfName').value.trim() || PROFILE_DEFAULTS.name,
    quals: document.getElementById('prfQuals').value.trim() || PROFILE_DEFAULTS.quals,
    prNo: document.getElementById('prfPrNo').value.trim() || PROFILE_DEFAULTS.prNo,
    hpcsa: document.getElementById('prfHpcsa').value.trim(),
    mobile: document.getElementById('prfMobile').value.trim(),
    email: document.getElementById('prfEmail').value.trim(),
    melkbosAddr: document.getElementById('prfMelkbosstrandAddr').value.trim(),
    melkbosPhone: document.getElementById('prfMelkbosstrandPhone').value.trim(),
    melkbosEmail: document.getElementById('prfMelkbosstrandEmail').value.trim(),
    vredAddr: document.getElementById('prfVredAddr').value.trim(),
    vredPhone: document.getElementById('prfVredPhone').value.trim(),
    vredEmail: document.getElementById('prfVredEmail').value.trim(),
    signature: sig
  };
  try {
    localStorage.setItem('chiroclinic_profile', JSON.stringify(profile));
    ccApplyProfileHeader();
    showToast('Profile saved');
    document.getElementById('profileModal').classList.remove('show');
  } catch(e) {
    showToast('Could not save — signature may be too large');
  }
}


// ============================================
// PRACTITIONER LETTERHEAD (shared header/footer for every letter, certificate and PDF)
// Stored like the profile: localStorage on this device. The app has one practitioner profile,
// so there is one letterhead setting (key below).
// ============================================
const LH_KEY = 'chiroclinic_letterhead';
const LH_DEFAULTS = { mode: 'default', headerImg: '', headerW: 0, headerH: 0, footerImg: '', footerW: 0, footerH: 0, topMm: 10, bottomMm: 12 };
const LH_SIDE_MM = 16;       // side margin used for letterhead width on every document
let _lhDraft = null;
// Built-in letterhead for Dr Theunis J Greyvensteyn (TJG). Used when this device has no saved letterhead
// and the profile name is his; other practitioners fall back to the default ChiroClinic (CC) header.
const LH_TJG_PRESET = { mode: 'image', headerImg: 'data:image/jpeg;base64,', headerW: 2480, headerH: 418, footerImg: 'data:image/jpeg;base64,', footerW: 2480, footerH: 167, topMm: 10, bottomMm: 10 };
function lhIsTJG() { const n = String((loadProfile() || {}).name || '').toLowerCase().replace(/[^a-z]/g, ''); return /greyvensteyn/.test(n) && /(theunis|tj|drtj)/.test(n); }
         // working copy while the Profile window is open

function loadLetterhead() {
  try {
    const raw = localStorage.getItem(LH_KEY);
    if (!raw && lhIsTJG()) return Object.assign({}, LH_DEFAULTS, LH_TJG_PRESET);
    return Object.assign({}, LH_DEFAULTS, raw ? JSON.parse(raw) : {});
  } catch (e) { return Object.assign({}, LH_DEFAULTS); }
}
// The setting actually used for output (image mode without an image falls back to the default header)
function lhEffective(src) {
  const L = Object.assign({}, LH_DEFAULTS, src || loadLetterhead());
  L.topMm = Math.max(0, Math.min(150, Number(L.topMm) || 0));
  L.bottomMm = Math.max(0, Math.min(80, Number(L.bottomMm) || 0));
  if (L.mode === 'image' && !(L.headerImg && L.headerW && L.headerH)) L.mode = 'default';
  if (L.mode !== 'image') { L.footerImg = ''; }
  if (!(L.footerImg && L.footerW && L.footerH)) L.footerImg = '';
  return L;
}
function lhGeometryMm(L, contentWidthMm) {
  const cw = contentWidthMm || (210 - 2 * LH_SIDE_MM);
  const headH = (L.mode === 'image') ? cw * L.headerH / L.headerW : 0;
  const footH = L.footerImg ? cw * L.footerH / L.footerW : 0;
  return { cw: cw, headH: headH, footH: footH };
}

// ---- HTML documents (print windows) ----
// The default header in each template sits between <!--LH-HEADER-START--> and <!--LH-HEADER-END-->,
// the body between <!--LH-BODY-START--> and <!--LH-BODY-END-->.
// opt.sideMm = @page side margin of that document; opt.padMm = extra inner padding (documents with 0 page margin)
function lhApplyToHtml(html, opt) {
  opt = opt || {};
  const L = lhEffective();
  if (L.mode === 'default') return html;
  const side = opt.sideMm != null ? opt.sideMm : LH_SIDE_MM;
  const pad = opt.padMm || 0;
  let band = '';
  if (L.mode === 'image' && !opt.forCanvas) {
    band = '<div class="lh-band" style="margin:0 ' + pad + 'mm 5mm;padding:0"><img src="' + ccSafeImgSrc(L.headerImg) + '" alt="Letterhead" style="display:block;width:100%;height:auto"></div>';
  }
  // P1 latest v4: name the practice where the patient was seen under the image letterhead (templates carry <!--CC-PRACTICE:name-->)
  const pm = html.match(/<!--CC-PRACTICE:([^>]*?)-->/);
  if (pm && pm[1] && window.CCPractice) band += CCPractice.lineHtml(pm[1]);
  html = html.replace(/<!--LH-HEADER-START-->[\s\S]*?<!--LH-HEADER-END-->/, band);
  if (opt.forCanvas) return html;
  html = html.replace(/@page\s*\{[^}]*\}/, '@page { size: A4; margin: ' + L.topMm + 'mm ' + side + 'mm ' + L.bottomMm + 'mm; }');
  if (L.footerImg) {
    const g = lhGeometryMm(L, 210 - 2 * side - 2 * pad);
    const foot = '<div class="lh-foot" style="position:fixed;left:' + pad + 'mm;right:' + pad + 'mm;bottom:0"><img src="' + ccSafeImgSrc(L.footerImg) + '" alt="" style="display:block;width:100%;height:auto"></div>';
    html = html.replace('<!--LH-BODY-START-->', '<table class="lh-wrap" style="width:100%;border-collapse:collapse;border:0"><tfoot><tr><td style="padding:0;border:0"><div style="height:' + (g.footH + 3).toFixed(1) + 'mm"></div></td></tr></tfoot><tbody><tr><td style="padding:0;border:0">')
               .replace('<!--LH-BODY-END-->', '</td></tr></tbody></table>' + foot);
  }
  return html;
}

// ---- html2canvas → jsPDF documents (emailed referral PDF) ----
// Places the rendered body inside the letterhead content area, page by page.
function lhCanvasToPdf(pdf, canvas, L) {
  const g = lhGeometryMm(L);
  const pxPerMm = canvas.width / 210;
  const ctx = canvas.getContext('2d');
  function rowBlank(y) {
    if (y < 0 || y >= canvas.height) return false;
    try {
      const d = ctx.getImageData(0, y, canvas.width, 1).data; let dark = 0;
      for (let x = 0; x < canvas.width; x += 4) { const i = x * 4; if (d[i] < 245 || d[i + 1] < 245 || d[i + 2] < 245) dark++; }
      return dark < 3;
    } catch (e) { return false; }
  }
  let yPx = 0, page = 0;
  while (yPx < canvas.height - 2) {
    if (page > 0) pdf.addPage();
    let topMm = L.topMm;
    if (page === 0 && L.mode === 'image') {
      pdf.addImage(L.headerImg, 'JPEG', LH_SIDE_MM, L.topMm, g.cw, g.headH);
      topMm += g.headH + 3;
    }
    let bottomMm = L.bottomMm;
    if (L.footerImg) {
      pdf.addImage(L.footerImg, 'JPEG', LH_SIDE_MM, 297 - L.bottomMm - g.footH, g.cw, g.footH);
      bottomMm += g.footH + 3;
    }
    const availPx = Math.max(20, Math.floor((297 - topMm - bottomMm) * pxPerMm));
    let slice = Math.min(availPx, canvas.height - yPx);
    if (yPx + slice < canvas.height) {
      const back = Math.floor(15 * pxPerMm);
      for (let dy = 0; dy < back; dy += 2) {
        const t = yPx + slice - dy;
        if (rowBlank(t) && rowBlank(t - 1) && rowBlank(t - 2)) { slice -= dy; break; }
      }
    }
    const c = document.createElement('canvas'); c.width = canvas.width; c.height = slice;
    const cx = c.getContext('2d'); cx.fillStyle = '#ffffff'; cx.fillRect(0, 0, c.width, c.height); cx.drawImage(canvas, 0, -yPx);
    pdf.addImage(c.toDataURL('image/jpeg', 0.92), 'JPEG', 0, topMm, 210, slice / pxPerMm);
    yPx += slice; page++;
  }
}

// ---- Hand-built PDFs (exercise letters, clinical record export) ----
// Returns helpers the generators use; in default mode everything is a no-op so the original header stays.
function lhRawPdf(pw, ph) {
  const L = lhEffective();
  const R = { custom: L.mode !== 'default', mode: L.mode };
  if (!R.custom) {
    R.pageOps = function () { return ''; };
    R.limit = function (v) { return v; };
    R.contY = function (v) { return v; };
    R.top = 0; R.contTop = 0; R.footTextY = 0;
    R.emit = function () { return ''; };
    return R;
  }
  const mm = 72 / 25.4, g = lhGeometryMm(L);
  const side = LH_SIDE_MM * mm, cw = g.cw * mm, top = L.topMm * mm, bottom = L.bottomMm * mm;
  const hh = g.headH * mm, fh = g.footH * mm;
  const footSpace = L.footerImg ? fh + 3 * mm : 0;
  R.top = top + (L.mode === 'image' ? hh + 6 * mm : 0) + 12;   // first text baseline on page 1
  R.contTop = top + 12;                                        // first text baseline on later pages
  R.footTextY = ph - bottom - footSpace - 2;                   // page-number line (exam export)
  const bodyBottom = R.footTextY - 14;
  R.limit = function (v) { return Math.min(v, bodyBottom); };
  R.contY = function () { return R.contTop; };
  R.pageOps = function (first) {
    let o = '';
    if (first && L.mode === 'image') o += 'q ' + cw.toFixed(2) + ' 0 0 ' + hh.toFixed(2) + ' ' + side.toFixed(2) + ' ' + (ph - top - hh).toFixed(2) + ' cm /LHh Do Q\n';
    if (L.footerImg) o += 'q ' + cw.toFixed(2) + ' 0 0 ' + fh.toFixed(2) + ' ' + side.toFixed(2) + ' ' + bottom.toFixed(2) + ' cm /LHf Do Q\n';
    return o;
  };
  R.emit = function (obj) {
    let res = '';
    function img(name, url, w, h) {
      const b = _dataUrlToBytes(url);
      const n = obj('<< /Type /XObject /Subtype /Image /Width ' + w + ' /Height ' + h + ' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ' + b.length + ' >>\nstream\n' + b + '\nendstream');
      res += ' /' + name + ' ' + n + ' 0 R';
    }
    if (L.mode === 'image') img('LHh', L.headerImg, L.headerW, L.headerH);
    if (L.footerImg) img('LHf', L.footerImg, L.footerW, L.footerH);
    return res;
  };
  return R;
}

// ---- Profile window: Letterhead section ----
function lhFillForm() {
  _lhDraft = loadLetterhead();
  document.getElementById('lhMode').value = _lhDraft.mode;
  document.getElementById('lhTop').value = _lhDraft.topMm;
  document.getElementById('lhBottom').value = _lhDraft.bottomMm;
  lhRenderPreview();
}
function lhFormChanged() {
  if (!_lhDraft) _lhDraft = loadLetterhead();
  const prevMode = _lhDraft.mode;
  _lhDraft.mode = document.getElementById('lhMode').value;
  if (_lhDraft.mode === 'paper' && prevMode !== 'paper' && Number(document.getElementById('lhTop').value) < 30) {
    document.getElementById('lhTop').value = 45;   // sensible start for pre-printed paper
  }
  _lhDraft.topMm = Number(document.getElementById('lhTop').value) || 0;
  _lhDraft.bottomMm = Number(document.getElementById('lhBottom').value) || 0;
  lhRenderPreview();
}
function lhHandleUpload(e, which) {
  const file = e.target.files[0];
  e.target.value = '';
  if (!file) return;
  if (!/^image\/(png|jpe?g)$/i.test(file.type)) { showToast('Letterhead must be a PNG or JPG image. For a PDF letterhead, save the page as PNG first.'); return; }
  if (file.size > 10 * 1024 * 1024) { showToast('Image too large (max 10 MB)'); return; }
  const reader = new FileReader();
  reader.onload = function (ev) {
    const img = new Image();
    img.onload = function () {
      // Keep aspect ratio; cap at 2480 px wide (≈ 350 dpi across the 178 mm printed width); white paper background
      const r = Math.min(1, 2480 / img.width);
      const w = Math.max(1, Math.round(img.width * r)), h = Math.max(1, Math.round(img.height * r));
      const c = document.createElement('canvas'); c.width = w; c.height = h;
      const x = c.getContext('2d'); x.fillStyle = '#ffffff'; x.fillRect(0, 0, w, h); x.drawImage(img, 0, 0, w, h);
      const url = c.toDataURL('image/jpeg', 0.9);
      if (!_lhDraft) _lhDraft = loadLetterhead();
      if (which === 'footer') { _lhDraft.footerImg = url; _lhDraft.footerW = w; _lhDraft.footerH = h; }
      else {
        _lhDraft.headerImg = url; _lhDraft.headerW = w; _lhDraft.headerH = h;
        _lhDraft.mode = 'image'; document.getElementById('lhMode').value = 'image';
      }
      lhRenderPreview();
    };
    img.src = ev.target.result;
  };
  reader.readAsDataURL(file);
}
function lhClearImage(which) {
  if (!_lhDraft) _lhDraft = loadLetterhead();
  if (which === 'footer') { _lhDraft.footerImg = ''; _lhDraft.footerW = 0; _lhDraft.footerH = 0; }
  else { _lhDraft.headerImg = ''; _lhDraft.headerW = 0; _lhDraft.headerH = 0; }
  lhRenderPreview();
}
function lhRenderPreview() {
  const box = document.getElementById('lhPreview');
  if (!box || !_lhDraft) return;
  const L = lhEffective(_lhDraft);
  const W = 150, k = W / 210, H = Math.round(297 * k);
  const g = lhGeometryMm(L);
  const side = LH_SIDE_MM * k;
  let inner = '';
  let y = L.topMm * k;
  if (L.mode === 'default') {
    const logo = (document.querySelector('.header-logo img') || {}).src || '';
    y = 10 * k;
    inner += '<div style="position:absolute;left:' + side + 'px;right:' + side + 'px;top:' + y + 'px;height:' + (16 * k) + 'px;border-bottom:1.5px solid #2B5F5C;display:flex;gap:3px;align-items:flex-start">' +
      (logo ? '<img src="' + ccSafeImgSrc(logo) + '" alt="" style="width:' + (9 * k) + 'px;height:' + (9 * k) + 'px">' : '') +
      '<div style="flex:1"><div style="height:3px;width:60%;background:#2B5F5C;margin:1px 0 2px"></div><div style="height:2px;width:45%;background:#bbb"></div></div></div>';
    y += 22 * k;
  } else if (L.mode === 'paper') {
    inner += '<div style="position:absolute;left:0;right:0;top:0;height:' + (L.topMm * k) + 'px;background:repeating-linear-gradient(45deg,#F0EDEA,#F0EDEA 3px,#fff 3px,#fff 6px);border-bottom:1px dashed #8A8A8A;font-size:8px;color:#5A5A5A;display:flex;align-items:center;justify-content:center">pre-printed area</div>';
    y += 3 * k;
  } else {
    inner += '<img src="' + ccSafeImgSrc(L.headerImg) + '" alt="" style="position:absolute;left:' + side + 'px;width:' + (g.cw * k) + 'px;top:' + y + 'px;height:' + (g.headH * k) + 'px">';
    y += (g.headH + 5) * k;
  }
  let bottom = H - L.bottomMm * k;
  if (L.footerImg) {
    inner += '<img src="' + ccSafeImgSrc(L.footerImg) + '" alt="" style="position:absolute;left:' + side + 'px;width:' + (g.cw * k) + 'px;top:' + (bottom - g.footH * k) + 'px;height:' + (g.footH * k) + 'px">';
    bottom -= (g.footH + 3) * k;
  }
  let lines = '';
  for (let ly = y + 4; ly < bottom - 2; ly += 6) lines += '<div style="position:absolute;left:' + side + 'px;right:' + (side + (ly % 30 < 6 ? 30 : 0)) + 'px;top:' + ly + 'px;height:2px;background:#D0CBC5"></div>';
  box.innerHTML = '<div style="position:relative;width:' + W + 'px;height:' + H + 'px;background:#fff;border:1px solid var(--border2);box-shadow:0 2px 8px rgba(0,0,0,.08);overflow:hidden">' + inner + lines + '</div>';
  const st = document.getElementById('lhStatus');
  if (st) {
    const raw = _lhDraft;
    st.textContent = (raw.headerImg ? 'Header image: ' + raw.headerW + ' × ' + raw.headerH + ' px' : 'No header image') + ' · ' +
      (raw.footerImg ? 'Footer image: ' + raw.footerW + ' × ' + raw.footerH + ' px' : 'No footer image') +
      (raw.mode === 'image' && !raw.headerImg ? ' — upload a header image, otherwise the default header is used' : '');
  }
}
function lhSaveFromForm() {
  if (!_lhDraft) return true;
  lhFormChanged();
  try { localStorage.setItem(LH_KEY, JSON.stringify(_lhDraft)); return true; }
  catch (e) { showToast('Could not save letterhead — image too large for this device storage. Try a smaller image.'); return false; }
}

// P1 latest v5 (user decision 2026-10-17): the first practice is named "Melkbosstrand Chiropractic".
// Practices have a fixed id; any saved label (old "Melkbosstrand Practice" included) maps to the same id.
var CC_PRACTICE_LABEL = { melkbos: 'Melkbosstrand Chiropractic', vred: 'Vredenburg Practice' };
var CC_PRACTICE_ALIASES = { 'melkbosstrand chiropractic': 'melkbos', 'melkbosstrand practice': 'melkbos', 'vredenburg practice': 'vred' };
function ccPracticeId(n) { return CC_PRACTICE_ALIASES[String(n || '').trim().toLowerCase()] || ''; }
function ccPracticeName(n) { const id = ccPracticeId(n); return id ? CC_PRACTICE_LABEL[id] : (n || ''); }

function profilePracticeBlock(practiceName) {
  const p = loadProfile();
  const pid = ccPracticeId(practiceName);
  if (pid === 'melkbos') {
    return { name: CC_PRACTICE_LABEL.melkbos, addr: p.melkbosAddr, phone: p.melkbosPhone, email: p.melkbosEmail };
  }
  if (pid === 'vred') {
    return { name: 'Vredenburg Practice', addr: p.vredAddr, phone: p.vredPhone, email: p.vredEmail };
  }
  return { name: '', addr: '', phone: '', email: '' };
}

// P1 latest v4: practitioner + practice details for the raw-PDF documents (exercise letters, exam record), from the Profile
// P1 latest v5: plain-letterhead header practice columns — wrap long Profile addresses to the column width, shrink the
// font a little (7.5 → 6.5 pt) and, if still needed, grow the header band so no address line is clipped or runs into the other column.
// Widths use Helvetica (PDF standard font F1) character widths in 1/1000 em.
var CC_HELV = (function () { var m = {}, g = { 278: " !,./:;Ifijlt|'[]\\", 333: "()-r`", 500: "cksvxyzJ?", 584: "+<=>~", 611: "FTZ", 667: "ABEKPSVXY&", 722: "CDHNRUw", 778: "GOQ", 833: "mM", 889: "%", 944: "W", 1015: "@" };
  Object.keys(g).forEach(function (w) { g[w].split('').forEach(function (c) { m[c] = +w; }); }); m['\u00a0'] = 278; return m; })();
function ccHelvW(t, size) { var W = 0, s = String(t || ''); for (var i = 0; i < s.length; i++) W += CC_HELV[s[i]] || 556; return W * size / 1000; }
function ccWrapW(text, maxW, size) { var out = [];
  String(text || '').split('\n').forEach(function (para) { if (!para.trim()) return; if (ccHelvW(para, size) <= maxW) { out.push(para); return; }
    var words = para.split(' '), line = null, push = function (l) { l = String(l || '').trim(); if (l) out.push(l); }; // split on single spaces so '  |  ' spacing survives
    words.forEach(function (w) { while (w && ccHelvW(w, size) > maxW) { var k = w.length; while (k > 1 && ccHelvW(w.slice(0, k), size) > maxW) k--; if (line) { push(line); line = null; } push(w.slice(0, k)); w = w.slice(k); }
      var tryL = line === null ? w : line + ' ' + w; if (ccHelvW(tryL.trim(), size) <= maxW) line = tryL; else { push(line); line = w; } });
    push(line); });
  return out; }
function ccHdrPracCols(PP, pw, ml, mr) {
  var c1 = ml, c2 = pw / 2 + 15, w1 = c2 - 15 - c1, w2 = pw - mr - c2, sz, a1, a2, n;
  var keepPhone = function (b, w, z) { var l2 = String(b.l2 || ''), ph = String(b.phone || ''); // keep a phone number on one line when the line has to wrap
    return ph && ccHelvW(l2, z) > w && l2.indexOf(ph) >= 0 ? l2.replace(ph, ph.replace(/ /g, '\u00a0')) : l2; };
  var pick = function (b, w, z) { return [].concat(ccWrapW(b.l1, w, z), ccWrapW(keepPhone(b, w, z), w, z)); };
  for (sz = 7.5; sz >= 6.5; sz -= 0.5) { a1 = pick(PP.m, w1, sz); a2 = pick(PP.v, w2, sz); n = Math.max(a1.length, a2.length); if (n <= 2) break; }
  if (sz < 6.5) sz = 6.5;
  var lh = sz + 2.5, last = 108 + (Math.max(n, 1) - 1) * lh, band = Math.max(130, Math.ceil(last + 8));
  var H = { size: sz, lh: lh, c1: c1, c2: c2, w1: w1, w2: w2, a1: a1, a2: a2, band: band, shift: band - 130, lastBaseline: last };
  try { window.__ccLastHdr = H; } catch (e) {}
  return H; }
function ccHdrPracDraw(H, PP, txt) {
  txt(PP.m.name, H.c1, 97, 8, 255, 255, 255, 'F2');
  H.a1.forEach(function (l, i) { txt(l, H.c1, 108 + i * H.lh, H.size, 210, 225, 225, 'F1'); });
  txt(PP.v.name, H.c2, 97, 8, 255, 255, 255, 'F2');
  H.a2.forEach(function (l, i) { txt(l, H.c2, 108 + i * H.lh, H.size, 210, 225, 225, 'F1'); }); }
function ccPdfProf() {
  const p = loadProfile();
  const pr = n => { const b = profilePracticeBlock(n) || {}; const lines = String(b.addr || '').split(/\n+/).map(x => x.trim()).filter(Boolean);
    return { name: n, l1: lines[0] || '', l2: [lines.slice(1).join(', '), b.phone || ''].filter(Boolean).join('  |  '), phone: b.phone || '' }; };
  return { name: p.name || '', quals: p.quals || '', prNo: p.prNo || '', m: pr(CC_PRACTICE_LABEL.melkbos), v: pr(CC_PRACTICE_LABEL.vred) };
}
function ccLetterSignoff() { const P = ccPdfProf(); return 'Kind regards,\n' + P.name + '\n' + P.quals + '\nPr ' + P.prNo; }

function profileLetterheadHTML(practiceName) {
  const p = ccEscObj(loadProfile());
  const pr = ccEscObj(profilePracticeBlock(practiceName));
  let practiceHTML = '';
  if (pr.name) {
    practiceHTML = '<strong>' + pr.name + '</strong>';
    if (pr.addr) practiceHTML += '<br>' + pr.addr.replace(/\n/g, '<br>');
    if (pr.phone) practiceHTML += '<br>Tel: ' + pr.phone;
    if (pr.email) practiceHTML += '<br>' + pr.email;
  } else {
    practiceHTML = 'Western Cape, South Africa';
  }
  let practitionerContact = '';
  if (p.mobile) practitionerContact += '<div class="sub">Mobile: ' + p.mobile + '</div>';
  if (p.email && !pr.email) practitionerContact += '<div class="sub">' + p.email + '</div>';

  const _lhLogo = ccSafeImgSrc((document.querySelector('.header-logo img') || {}).src || '');
  return {
    practitionerHTML:
      (_lhLogo ? '<div style="display:flex;gap:4mm;align-items:flex-start"><img src="' + _lhLogo + '" alt="" style="width:15mm;height:15mm;flex-shrink:0"><div>' : '') +
      '<h1>' + p.name + '</h1>' +
      '<div class="sub">' + p.quals + '</div>' +
      '<div class="sub"><strong>Practice number: ' + p.prNo + '</strong>' +
      (p.hpcsa ? ' &nbsp;·&nbsp; HPCSA: ' + p.hpcsa : '') + '</div>' +
      practitionerContact + (_lhLogo ? '</div></div>' : ''),
    practiceHTML: practiceHTML
  };
}

function profileSignatureBlockHTML() {
  const p = ccEscObj(loadProfile());
  let sigImg = '';
  if (p.signature) {
    sigImg = '<img src="' + p.signature + '" alt="Signature" style="max-height:60px;max-width:240px;display:block;margin-bottom:4px">';
  }
  return sigImg +
    '<div style="border-top:1px solid #999;padding-top:6px;width:60%;margin-top:' + (p.signature ? '0' : '36') + 'px">' +
    '<div style="font-weight:bold">' + p.name + '</div>' +
    '<div style="font-size:9pt;color:#555">' + p.quals + ' &nbsp;·&nbsp; Pr nr: ' + p.prNo + '</div>' +
    '</div>';
}

