function imgRecommend(activeRegions, examData) {
  // Collect all ICD-10 codes from active regions
  const codes = [];
  (activeRegions || []).forEach(r => {
    const D = (examData || {})[r] || {};
    if (D.icd10) codes.push({ region: r, code: D.icd10 });
    if (D.icd10_2) codes.push({ region: r, code: D.icd10_2 });
  });

  // Try specific rules first (in order)
  for (const rule of IMG_RULES) {
    for (const c of codes) {
      if (rule.pattern.test(c.code) && (!rule.region || rule.region === c.region)) {
        const def = IMG_REGION_DEFAULTS[c.region] || {};
        return {
          modality: rule.modality,
          regionLabel: rule.regionLabel || def.regionLabel || '',
          views: rule.views ? rule.views.slice() : (rule.appendViews ? (def.views || []).concat(rule.appendViews) : (def.views || []).slice()),
          rationale: rule.rationale,
          matchedCode: c.code,
          regionCode: c.region
        };
      }
    }
  }

  // Fallback: region default for the focused exam region (else first active)
  const r = (APP.currentRegion && (activeRegions || []).indexOf(APP.currentRegion) >= 0) ? APP.currentRegion : (activeRegions || [])[0];
  if (r && IMG_REGION_DEFAULTS[r]) {
    const d = IMG_REGION_DEFAULTS[r];
    return {
      modality: d.modality,
      regionLabel: d.regionLabel,
      views: d.views.slice(),
      rationale: d.rationale,
      matchedCode: '',
      regionCode: r
    };
  }
  return null;
}

function imgPracticeAutoDetect() {
  // Melkbosstrand Wed/Fri, Vredenburg Mon/Tue/Thu (per practitioner schedule)
  const dateStr = document.getElementById('visitDate').value || document.getElementById('imgRefDate').value;
  if (!dateStr) return '';
  // P1 latest v3: one schedule for every document (p1-docpractice.js); weekend = no practice unless chosen by hand
  return (window.CCPractice ? CCPractice.forDate(dateStr).name : '') || '';
}

function onRadPracticeChange() {
  const sel = document.getElementById('imgRadPractice').value;
  const ref = document.getElementById('imgReferredTo');
  if (sel && sel !== 'The Radiologist' && !ref.value.trim()) {
    ref.value = sel;
  } else if (sel === 'The Radiologist' && !ref.value.trim()) {
    ref.value = '';
  }
}

function imgFormatPatientSummary() {
  const fn = (document.getElementById('ptFirstName').value || '').trim();
  const ln = (document.getElementById('ptLastName').value || '').trim();
  const dob = document.getElementById('ptDOB').value || '';
  const id = (document.getElementById('ptID').value || '').trim();
  const gender = document.getElementById('ptGender').value || '';
  const phone = (document.getElementById('ptPhone').value || '').trim();
  const medAid = (document.getElementById('ptMedAid').value || '').trim();
  const medAidNo = (document.getElementById('ptMedAidNo').value || '').trim();

  let age = '';
  if (dob) {
    const b = new Date(dob);
    if (!isNaN(b.getTime())) {
      const t = new Date();
      let a = t.getFullYear() - b.getFullYear();
      const m = t.getMonth() - b.getMonth();
      if (m < 0 || (m === 0 && t.getDate() < b.getDate())) a--;
      age = a + ' yrs';
    }
  }

  const fullName = (fn + ' ' + ln).trim() || '<em style="color:var(--red)">Patient name missing</em>';
  let html = '<div><strong>' + fullName + '</strong>';
  if (age) html += ' <span style="color:var(--text2)">(' + age + ')</span>';
  if (gender) html += ' <span style="color:var(--text2)">— ' + gender + '</span>';
  html += '</div>';
  if (dob) html += '<div style="color:var(--text2)">DOB: ' + dob + '</div>';
  if (id) html += '<div style="color:var(--text2)">ID: ' + id + '</div>';
  if (phone) html += '<div style="color:var(--text2)">Phone: ' + phone + '</div>';
  if (medAid || medAidNo) html += '<div style="color:var(--text2)">Medical Aid: ' + (medAid || '—') + (medAidNo ? ' — ' + medAidNo : '') + '</div>';
  return html;
}

function imgBuildClinicalHistory() {
  const lines = [];
  const region = document.getElementById('pcRegion').value;
  const side = document.getElementById('pcSide').value;
  const onset = document.getElementById('pcOnset').value;
  const duration = document.getElementById('pcDuration').value;
  const frequency = document.getElementById('pcFrequency').value;

  if (region) {
    let l = 'Patient presenting with ' + (region.toLowerCase());
    if (side) l += ' (' + side.toLowerCase() + ')';
    if (duration) l += ' of ' + duration + ' duration';
    if (onset) l += ', onset ' + onset;
    if (frequency) l += ', ' + frequency.toLowerCase();
    l += '.';
    lines.push(l);
  }

  // Add VAS and quality from active regions
  (APP.activeRegions || []).forEach(r => {
    const R = REGIONS[r], D = getExamData(r);
    const parts = [];
    if (D.vas) parts.push('VAS ' + D.vas + '/10');
    if (D.quality && D.quality.length) parts.push('character: ' + D.quality.join(', ').toLowerCase());
    if (D.aggFactors && D.aggFactors.length) parts.push('aggravated by ' + D.aggFactors.join(', ').toLowerCase());
    if (D.relFactors && D.relFactors.length) parts.push('relieved by ' + D.relFactors.join(', ').toLowerCase());
    if (parts.length) lines.push(R.name + ': ' + parts.join('; ') + '.');
  });

  // Key exam findings
  (APP.activeRegions || []).forEach(r => {
    const R = REGIONS[r], D = getExamData(r);
    const findings = [];
    // Limited ROM
    ROMDATA.entries(r, D, 'A').forEach(e => {
      const v = e.deg, n = ROMDATA.norm(r, e.i).deg;
      if (ROMDATA.filled(v) && n != null && n > 10 && Number(v) < n * 0.7) {
        findings.push(ROMDATA.label(e) + ' restricted to ' + v + '° (norm ' + n + '°)' + (ROMDATA.isYes(e.pain) ? ', painful' : ''));
      }
    });
    // Positive ortho
    R.ortho.forEach(t => {
      if (D['ort_R_' + t] === 'Positive') findings.push(t + ' positive on the right');
      if (D['ort_L_' + t] === 'Positive') findings.push(t + ' positive on the left');
    });
    // Neuro deficits
    if (D.dermatomeNotes) findings.push('dermatomal change: ' + D.dermatomeNotes);
    if (findings.length) lines.push('On examination of ' + R.name.toLowerCase() + ': ' + findings.join('; ') + '.');
  });

  // Red flags
  const flags = [...document.querySelectorAll('#redFlags .chip.active')].map(c => c.dataset.val);
  if (flags.length) lines.push('Red flags noted: ' + flags.join(', ') + '.');

  // Conservative care to date
  const prevTx = document.getElementById('pcPrevTx').value;
  const prevTxCount = document.getElementById('pcPrevTxCount').value;
  const prevResp = document.getElementById('pcPrevResponse').value;
  if (prevTx || prevTxCount || prevResp) {
    let l = 'Conservative management to date';
    if (prevTx) l += ': ' + prevTx;
    if (prevTxCount) l += ' (' + prevTxCount + ' sessions)';
    if (prevResp) l += '; response: ' + prevResp.toLowerCase();
    l += '.';
    lines.push(l);
  }

  // Relevant history
  const conds = [...document.querySelectorAll('#conditions .chip.active')].map(c => c.dataset.val || c.textContent.trim());
  if (conds.length) lines.push('Past medical history: ' + conds.join(', ') + '.');
  const meds = gatherMedications().filter(med => med.status !== 'Stopped / Previous');
  if (meds.length) lines.push('Current medications: ' + meds.map(medicationDisplayText).join('; ') + '.');
  const allergies = document.getElementById('allergies').value;
  if (allergies) lines.push('Allergies: ' + allergies + '.');

  return lines.join(' ');
}

function imgBuildClinicalQuestion(rec) {
  if (!rec) return '';
  const r = rec.regionCode;
  const dx = (APP.examData[r] || {}).primaryDx || '';
  const code = rec.matchedCode || '';
  let q = '';
  if (rec.modality.indexOf('X-ray') >= 0) {
    q = 'Please assess for alignment, degenerative change, neural foraminal narrowing, and any bony pathology';
    if (rec.regionLabel.toLowerCase().includes('spine')) q += ' or instability on dynamic views';
    q += '.';
  } else if (rec.modality === 'MRI') {
    q = 'Please assess for ' + (dx ? dx.toLowerCase() : 'soft tissue / neural pathology') +
        ' and correlate findings with the clinical picture' + (code ? ' (' + code + ')' : '') + '.';
  } else if (rec.modality === 'Ultrasound') {
    q = 'Please assess for ' + (dx ? dx.toLowerCase() : 'soft tissue pathology') +
        '. Dynamic assessment as appropriate.';
  } else if (rec.modality.indexOf('CT') >= 0) {
    q = 'Please assess for bony detail and exclude fracture / structural pathology.';
  } else {
    q = 'Please correlate imaging findings with the clinical picture provided.';
  }
  return q;
}

function imgBuildDxList() {
  const out = [];
  (APP.activeRegions || []).forEach(r => {
    const R = REGIONS[r], D = getExamData(r);
    if (D.primaryDx || D.icd10) {
      out.push({ region: R.name, dx: D.primaryDx || '', code: D.icd10 || '', primary: true });
    }
    if (D.secondaryDx || D.icd10_2) {
      out.push({ region: R.name, dx: D.secondaryDx || '', code: D.icd10_2 || '', primary: false });
    }
  });
  return out;
}

function refreshImagingFromNotes() {
  // Date defaults
  if (!document.getElementById('imgRefDate').value) {
    document.getElementById('imgRefDate').value = document.getElementById('visitDate').value || localISODate();
  }
  // Practice auto-detect
  if (!document.getElementById('imgPractice').value) {
    document.getElementById('imgPractice').value = imgPracticeAutoDetect() || '';
  }

  // Patient summary
  document.getElementById('imgPatientSummary').innerHTML = imgFormatPatientSummary();

  // Diagnoses list
  const dxList = imgBuildDxList();
  const dxBox = document.getElementById('imgDxList');
  if (dxList.length === 0) {
    dxBox.innerHTML = '<em style="color:var(--text3)">No diagnoses entered on the Examination tab yet.</em>';
  } else {
    dxBox.innerHTML = dxList.map(d => {
      const tag = d.primary ? '<span style="background:var(--accent);color:#fff;font-size:10px;padding:2px 6px;border-radius:4px;font-weight:600">PRIMARY</span>' :
                              '<span style="background:var(--text3);color:#fff;font-size:10px;padding:2px 6px;border-radius:4px;font-weight:600">SECONDARY</span>';
      return '<div style="margin-bottom:6px;display:flex;gap:8px;align-items:center;flex-wrap:wrap">' +
             tag +
             '<span style="font-weight:600;color:var(--accent)">' + (d.code || '—') + '</span>' +
             '<span style="color:var(--text2)">' + (d.dx || '') + '</span>' +
             '<span style="color:var(--text3);font-size:11px">(' + d.region + ')</span>' +
             '</div>';
    }).join('');
  }

  // External cause code: surface row if any active region has S-code dx, or pull existing extCause
  const hasSCode = dxList.some(d => /^S/i.test(d.code || ''));
  let firstExtCause = '';
  (APP.activeRegions || []).forEach(r => {
    const D = APP.examData[r] || {};
    if (D.extCause && !firstExtCause) firstExtCause = D.extCause;
  });
  const extRow = document.getElementById('imgExtCauseRow');
  if (hasSCode || firstExtCause) {
    extRow.style.display = 'block';
    if (!document.getElementById('imgExtCause').value && firstExtCause) {
      document.getElementById('imgExtCause').value = firstExtCause;
    }
  } else {
    extRow.style.display = 'none';
  }

  // Recommendation
  const rec = imgRecommend(APP.activeRegions, APP.examData);
  if (rec) {
    document.getElementById('imgModality').value = rec.modality;
    document.getElementById('imgRegion').value = rec.regionLabel;
    // Side from primary complaint or first active region
    const side = document.getElementById('pcSide').value || (APP.examData[rec.regionCode] || {}).side || '';
    if (side && side !== 'Both' && side !== 'Central') document.getElementById('imgSide').value = side;
    else if (side === 'Both') document.getElementById('imgSide').value = 'Both';

    // Render views as toggleable chips
    renderImgViews(rec.views, true);

    document.getElementById('imgRationale').value = rec.rationale;

    if (!document.getElementById('imgClinicalQ').value) {
      document.getElementById('imgClinicalQ').value = imgBuildClinicalQuestion(rec);
    }
  }

  // Clinical history
  document.getElementById('imgClinicalHx').value = imgBuildClinicalHistory();

  // Allergies
  const allergies = document.getElementById('allergies').value;
  if (allergies && !document.getElementById('imgAllergies').value) {
    document.getElementById('imgAllergies').value = allergies;
  }

  // Last-used radiology practice
  try {
    const lastRad = localStorage.getItem('chiroclinic_lastRadPractice') || '';
    if (lastRad && !document.getElementById('imgRadPractice').value) {
      document.getElementById('imgRadPractice').value = lastRad;
      onRadPracticeChange();
    }
  } catch(e) {}

  showToast('Imaging referral refreshed from notes');
}

function renderImgViews(views, allActive) {
  const box = document.getElementById('imgViewsChips');
  if (!views || views.length === 0) {
    box.innerHTML = '<em style="color:var(--text3);font-size:12px">No standard views suggested for this modality. Add custom views below.</em>';
    return;
  }
  box.innerHTML = views.map(v =>
    '<span class="chip' + (allActive ? ' active' : '') + "\" data-cc-click=\"toggleChip(this)\" data-val=\"" + ccH(v) + '">' + ccH(v) + '</span>'
  ).join('');
}

function onModalityChange() {
  const modality = document.getElementById('imgModality').value;
  const region = document.getElementById('imgRegion').value;

  // Suggest views based on modality + region
  let views = [];
  const r = (APP.currentRegion && (APP.activeRegions || []).indexOf(APP.currentRegion) >= 0) ? APP.currentRegion : (APP.activeRegions || [])[0];
  const def = IMG_REGION_DEFAULTS[r];

  if (modality.indexOf('X-ray') >= 0 && def) {
    views = def.views.slice();
  } else if (modality === 'MRI') {
    views = ['Sagittal T1', 'Sagittal T2', 'Sagittal STIR', 'Axial T2'];
  } else if (modality === 'Ultrasound') {
    views = ['Targeted ultrasound of the affected region', 'Compare contralateral side'];
  } else if (modality.indexOf('CT') >= 0) {
    views = ['Axial 1mm slices', 'Coronal reconstruction', 'Sagittal reconstruction'];
  } else if (modality.indexOf('Bone Scan') >= 0) {
    views = ['Three-phase bone scan', 'Whole body imaging', 'SPECT if focal area suspected'];
  } else if (modality === 'DEXA') {
    views = ['Lumbar spine (L1–L4)', 'Bilateral hips', 'Forearm if indicated'];
  }

  renderImgViews(views, true);
}

function imgGatherSelectedViews() {
  const selected = [...document.querySelectorAll('#imgViewsChips .chip.active')].map(c => c.dataset.val);
  const custom = (document.getElementById('imgViewsCustom').value || '').trim();
  if (custom) selected.push(custom);
  return selected;
}

function printImagingReferral() {
  const fn = (ccH(document.getElementById('ptFirstName').value) || '').trim();
  const ln = (ccH(document.getElementById('ptLastName').value) || '').trim();
  const fullName = (fn + ' ' + ln).trim();
  if (!fullName) { showToast('Patient name required before printing'); return; }
  if (!document.getElementById('imgModality').value) { showToast('Please select an imaging modality'); return; }

  const dob = ccH(document.getElementById('ptDOB').value);
  const id = ccH(document.getElementById('ptID').value);
  const gender = ccH(document.getElementById('ptGender').value);
  const phone = ccH(document.getElementById('ptPhone').value);
  const medAid = ccH(document.getElementById('ptMedAid').value);
  const medAidNo = ccH(document.getElementById('ptMedAidNo').value);
  const fileNo = ccH(document.getElementById('ptFileNo').value);

  let age = '';
  if (dob) {
    const b = new Date(dob);
    if (!isNaN(b.getTime())) {
      const t = new Date();
      let a = t.getFullYear() - b.getFullYear();
      const m = t.getMonth() - b.getMonth();
      if (m < 0 || (m === 0 && t.getDate() < b.getDate())) a--;
      age = a + ' years';
    }
  }

  const refDate = ccH(document.getElementById('imgRefDate').value || localISODate());
  // P1 latest v3: no empty practice address — a form choice is checked; otherwise the visit-date practice, or the weekend prompt
  const _imgPrac = ccPracticeName(document.getElementById('imgPractice').value);
  const practice = _imgPrac ? CCPractice.require(_imgPrac, 'Imaging referral') : CCPractice.gate(document.getElementById('visitDate').value || refDate, 'Imaging referral', function (n) { const sel = document.getElementById('imgPractice'); if (sel && !sel.value) sel.value = n; printImagingReferral(); });
  if (!practice) return;
  const urgency = ccH(document.getElementById('imgUrgency').value || 'Routine');
  const radPractice = document.getElementById('imgRadPractice').value; // raw (stored); escaped where printed
  const referredTo = ccH(document.getElementById('imgReferredTo').value) ||
                     (radPractice && radPractice !== 'The Radiologist' ? ccH(radPractice) : 'The Radiologist');
  const modality = ccH(document.getElementById('imgModality').value);
  const region = ccH(document.getElementById('imgRegion').value);
  const side = ccH(document.getElementById('imgSide').value);
  const contrast = ccH(document.getElementById('imgContrast').value);
  const views = imgGatherSelectedViews();
  const clinicalHx = ccH(document.getElementById('imgClinicalHx').value);
  const clinicalQ = ccH(document.getElementById('imgClinicalQ').value);
  const rationale = ccH(document.getElementById('imgRationale').value);
  const pregnancy = ccH(document.getElementById('imgPregnancy').value);
  const renal = ccH(document.getElementById('imgRenal').value);
  const implants = ccH(document.getElementById('imgImplants').value);
  const claustro = ccH(document.getElementById('imgClaustro').value);
  const allergies = ccH(document.getElementById('imgAllergies').value);
  const priorImaging = ccH(document.getElementById('imgPriorImaging').value);
  const extCause = (ccH(document.getElementById('imgExtCause').value) || '').trim();

  // Save last-used radiology practice
  try { if (radPractice) localStorage.setItem('chiroclinic_lastRadPractice', radPractice); } catch(e) {}

  const dxList = imgBuildDxList();
  let dxHTML = dxList.length ? dxList.map(d =>
    '<div>' + (d.code ? '<strong>' + ccH(d.code) + '</strong> — ' : '') + ccH(d.dx || '') +
    (d.primary ? ' <em style="color:#666">(primary)</em>' : ' <em style="color:#666">(secondary)</em>') + '</div>'
  ).join('') : '<div><em>—</em></div>';
  if (extCause) {
    dxHTML += '<div style="margin-top:6px"><strong>External Cause:</strong> ' + extCause + '</div>';
  }

  const viewsHTML = views.length ? '<ul style="margin:4px 0 0 18px;padding:0">' + views.map(v => '<li>' + ccH(v) + '</li>').join('') + '</ul>' : '<div><em>As per radiologist protocol</em></div>';

  const lh = profileLetterheadHTML(practice);
  const sigBlockHTML = profileSignatureBlockHTML();

  const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Imaging Referral — ${fullName}</title>
<style>
  @page { size: A4; margin: 18mm 16mm; }
  body { font-family: 'Helvetica Neue', Arial, sans-serif; font-size: 11pt; color: #222; line-height: 1.45; }
  .header { border-bottom: 2px solid #2B5F5C; padding-bottom: 10px; margin-bottom: 16px; display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; }
  .header h1 { font-size: 18pt; color: #2B5F5C; margin: 0 0 2px 0; }
  .header .sub { font-size: 9pt; color: #555; }
  .practice-block { text-align: right; font-size: 9.5pt; color: #555; line-height: 1.4; min-width: 30%; }
  .doc-title { text-align: center; font-size: 14pt; font-weight: bold; color: #2B5F5C; letter-spacing: 1px; margin: 14px 0 18px; text-transform: uppercase; }
  .urgency { display: inline-block; padding: 2px 10px; border-radius: 4px; font-weight: bold; font-size: 9pt; margin-left: 8px; }
  .urgency.routine { background: #e8f5e9; color: #2e7d32; }
  .urgency.urgent { background: #fff3cd; color: #856404; }
  .urgency.emergency { background: #f8d7da; color: #721c24; }
  .grid { display: grid; grid-template-columns: 140px 1fr; gap: 4px 12px; margin-bottom: 10px; }
  .grid .lbl { font-weight: 600; color: #555; }
  h2 { font-size: 11pt; color: #2B5F5C; border-bottom: 1px solid #ccc; padding-bottom: 3px; margin: 14px 0 6px; text-transform: uppercase; letter-spacing: 0.5px; }
  .box { background: #f7f5f2; border-left: 3px solid #2B5F5C; padding: 8px 12px; margin: 6px 0; }
  .signature { margin-top: 24px; }
  .footer { margin-top: 24px; font-size: 8.5pt; color: #888; text-align: center; border-top: 1px solid #ddd; padding-top: 6px; }
  @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } .no-print { display: none; } }
  .no-print { position: fixed; top: 10px; right: 10px; background: #2B5F5C; color: white; border: none; padding: 10px 16px; border-radius: 6px; cursor: pointer; font-size: 11pt; }
</style></head>
<body>
<button class="no-print" data-cc-click="window.print()">🖨 Print / Save as PDF</button>

<!--CC-PRACTICE:${practice}-->
<!--LH-HEADER-START-->
<div class="header">
  <div>
    ${lh.practitionerHTML}
  </div>
  <div class="practice-block">
    ${lh.practiceHTML}<br>
    <strong>Date: ${refDate}</strong>
  </div>
</div>
<!--LH-HEADER-END-->
<!--LH-BODY-START-->

<div class="doc-title">Radiological Referral
  <span class="urgency ${urgency.toLowerCase().indexOf('emergency') >= 0 ? 'emergency' : (urgency.toLowerCase().indexOf('urgent') >= 0 ? 'urgent' : 'routine')}">${urgency}</span>
</div>

<p>To: <strong>${referredTo}</strong></p>
<p>Dear Colleague,</p>
<p>I would be grateful if you could perform the following imaging study on my patient and forward your report at your earliest convenience.</p>

<h2>Patient Details</h2>
<div class="grid">
  <div class="lbl">Name:</div><div>${fullName}</div>
  ${dob ? '<div class="lbl">Date of Birth:</div><div>' + dob + (age ? ' (' + age + ')' : '') + '</div>' : ''}
  ${gender ? '<div class="lbl">Gender:</div><div>' + gender + '</div>' : ''}
  ${id ? '<div class="lbl">ID Number:</div><div>' + id + '</div>' : ''}
  ${phone ? '<div class="lbl">Phone:</div><div>' + phone + '</div>' : ''}
  ${medAid ? '<div class="lbl">Medical Aid:</div><div>' + medAid + (medAidNo ? ' — ' + medAidNo : '') + '</div>' : ''}
  ${fileNo ? '<div class="lbl">File Number:</div><div>' + fileNo + '</div>' : ''}
</div>

<h2>Imaging Requested</h2>
<div class="grid">
  <div class="lbl">Modality:</div><div><strong>${modality}</strong></div>
  <div class="lbl">Region:</div><div>${region}${side && side !== 'N/A' ? ' — ' + side : ''}</div>
  <div class="lbl">Contrast:</div><div>${contrast || 'Not required'}</div>
  <div class="lbl">Views / Sequences:</div><div>${viewsHTML}</div>
</div>

<h2>Working Diagnosis</h2>
${dxHTML}

<h2>Clinical History</h2>
<div class="box">${(clinicalHx || '<em>—</em>').replace(/\n/g, '<br>')}</div>

<h2>Clinical Question</h2>
<div class="box">${clinicalQ || '<em>Please correlate findings with the clinical picture provided.</em>'}</div>

${rationale ? '<h2>Rationale for Referral</h2><div class="box" style="border-left-color:#888;font-size:10pt;color:#555">' + rationale + '</div>' : ''}

<h2>Safety Screening</h2>
<div class="grid">
  <div class="lbl">Pregnancy:</div><div>${pregnancy || 'N/A'}</div>
  ${renal ? '<div class="lbl">Renal Function (eGFR):</div><div>' + renal + '</div>' : ''}
  ${implants ? '<div class="lbl">Implants / Devices:</div><div>' + implants + '</div>' : ''}
  ${claustro && claustro !== 'No' ? '<div class="lbl">Claustrophobia:</div><div>' + claustro + '</div>' : ''}
  ${allergies ? '<div class="lbl">Allergies:</div><div>' + allergies + '</div>' : ''}
  ${priorImaging ? '<div class="lbl">Previous Imaging:</div><div>' + priorImaging.replace(/\n/g, '<br>') + '</div>' : ''}
</div>

<p style="margin-top: 20px;">Thank you for your assistance with this patient. Please do not hesitate to contact me should you require any further clinical information.</p>

<div class="signature">${sigBlockHTML}</div>

<div class="footer">This referral was generated electronically on ${new Date().toLocaleString('en-ZA')}.</div>

<!--LH-BODY-END-->
</body></html>`;

  const w = window.open('', '_blank');
  if (!w) { showToast('Popup blocked — allow popups to print referral'); return; }
  w.document.write(lhApplyToHtml(html, { sideMm: 16 }));
  w.document.close();
  CCEv.popup(w, { printAfter: 400 }); // v8 CSP: was an inline <script> in the popup
}

// ============================================
// CERTIFICATE OF INDISPOSITION
// ============================================

function certCalcDuration() {
  const from = document.getElementById('certFromDate').value;
  const to = document.getElementById('certToDate').value;
  const label = document.getElementById('certDurationLabel');
  if (!from || !to) { label.textContent = 'Period not set'; return null; }
  const fd = new Date(from), td = new Date(to);
  if (isNaN(fd.getTime()) || isNaN(td.getTime()) || td < fd) {
    label.textContent = 'Invalid date range';
    return null;
  }
  const days = Math.round((td - fd) / 86400000) + 1;
  const fromFmt = fd.toLocaleDateString('en-ZA', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  const toFmt = td.toLocaleDateString('en-ZA', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  label.textContent = days + (days === 1 ? ' day' : ' days') + ' — ' + fromFmt + (days > 1 ? ' to ' + toFmt : '');
  return { days, from, to, fromFmt, toFmt };
}

function certQuickSet(days) {
  let consult = document.getElementById('certConsultDate').value;
  if (!consult) {
    consult = document.getElementById('visitDate').value || localISODate();
    document.getElementById('certConsultDate').value = consult;
  }
  document.getElementById('certFromDate').value = consult;
  const to = new Date(consult);
  to.setDate(to.getDate() + days - 1);
  document.getElementById('certToDate').value = localISODate(to);
  certCalcDuration();
  certUpdateQrPreview();
}

function onCertTypeChange() { /* hook for future logic */ }

['certFromDate','certToDate'].forEach(id => {
  document.addEventListener('DOMContentLoaded', () => {
    const el = document.getElementById(id);
    if (el) el.addEventListener('change', () => { certCalcDuration(); certUpdateQrPreview(); });
  });
});

function certBuildPatientSummary() {
  const fn = (document.getElementById('ptFirstName').value || '').trim();
  const ln = (document.getElementById('ptLastName').value || '').trim();
  const dob = document.getElementById('ptDOB').value || '';
  const id = (document.getElementById('ptID').value || '').trim();
  const gender = document.getElementById('ptGender').value || '';

  let age = '';
  if (dob) {
    const b = new Date(dob);
    if (!isNaN(b.getTime())) {
      const t = new Date();
      let a = t.getFullYear() - b.getFullYear();
      const m = t.getMonth() - b.getMonth();
      if (m < 0 || (m === 0 && t.getDate() < b.getDate())) a--;
      age = a + ' yrs';
    }
  }

  const fullName = (fn + ' ' + ln).trim() || '<em style="color:var(--red)">Patient name missing</em>';
  let html = '<div><strong>' + fullName + '</strong>';
  if (age) html += ' <span style="color:var(--text2)">(' + age + ')</span>';
  if (gender) html += ' <span style="color:var(--text2)">— ' + gender + '</span>';
  html += '</div>';
  if (dob) html += '<div style="color:var(--text2)">DOB: ' + dob + '</div>';
  if (id) html += '<div style="color:var(--text2)">ID: ' + id + '</div>';
  return html;
}

function certBuildDiagnosisText() {
  // Pull primary dx from active regions
  const items = [];
  (APP.activeRegions || []).forEach(r => {
    const D = APP.examData[r] || {};
    if (D.primaryDx || D.icd10) {
      items.push((D.icd10 ? D.icd10 + ' — ' : '') + (D.primaryDx || ''));
    }
  });
  return items.join('; ');
}

function certBuildQrPayload() {
  const profile = loadProfile();
  const fn = (document.getElementById('ptFirstName').value || '').trim();
  const ln = (document.getElementById('ptLastName').value || '').trim();
  const id = (document.getElementById('ptID').value || '').trim();
  const from = document.getElementById('certFromDate').value;
  const to = document.getElementById('certToDate').value;
  const consult = document.getElementById('certConsultDate').value;
  const type = document.getElementById('certType').value;
  const issued = localISODate();

  const lines = [
    'CERTIFICATE OF INDISPOSITION',
    'Patient: ' + (fn + ' ' + ln).trim(),
    id ? 'ID: ' + id : '',
    consult ? 'Consult: ' + consult : '',
    from && to ? 'Period: ' + from + ' to ' + to : '',
    type ? 'Type: ' + type : '',
    'Issued by: ' + profile.name,
    'Pr No: ' + profile.prNo,
    'Issued on: ' + issued
  ].filter(Boolean);
  return lines.join('\n');
}

function certUpdateQrPreview() {
  const box = document.getElementById('certQrPreview');
  if (!box) return;
  const fn = (document.getElementById('ptFirstName').value || '').trim();
  const ln = (document.getElementById('ptLastName').value || '').trim();
  if (!fn && !ln) {
    box.innerHTML = '<em style="color:var(--text3);font-size:12px">Enter patient details to generate QR preview</em>';
    return;
  }
  try {
    const payload = certBuildQrPayload();
    const qr = qrcode(0, 'M');
    qr.addData(payload);
    qr.make();
    box.innerHTML = '<div style="display:inline-block;background:#fff;padding:8px;border-radius:6px;border:1px solid var(--border)">' +
                    qr.createSvgTag({ scalable: true, margin: 0 }).replace('<svg', '<svg style="width:140px;height:140px"') +
                    '</div>' +
                    '<div style="font-size:11px;color:var(--text3);margin-top:6px">Encodes ' + payload.split('\n').length + ' lines · ' + payload.length + ' chars</div>';
  } catch(e) {
    box.innerHTML = '<em style="color:var(--red);font-size:12px">QR generation failed: ' + e.message + '</em>';
  }
}

function refreshCertFromNotes() {
  // Date defaults
  if (!document.getElementById('certConsultDate').value) {
    document.getElementById('certConsultDate').value = document.getElementById('visitDate').value || localISODate();
  }
  document.getElementById('certPatientSummary').innerHTML = certBuildPatientSummary();

  // Auto-fill diagnosis if empty
  if (!document.getElementById('certDiagnosis').value) {
    const dx = certBuildDiagnosisText();
    if (dx) document.getElementById('certDiagnosis').value = dx;
  }
  certCalcDuration();
  certUpdateQrPreview();
  showToast('Certificate refreshed from notes');
}

function printCertificate() {
  const fn = (ccH(document.getElementById('ptFirstName').value) || '').trim();
  const ln = (ccH(document.getElementById('ptLastName').value) || '').trim();
  const fullName = (fn + ' ' + ln).trim();
  if (!fullName) { showToast('Patient name required'); return; }

  const dob = ccH(document.getElementById('ptDOB').value);
  const id = ccH(document.getElementById('ptID').value);
  const gender = ccH(document.getElementById('ptGender').value);
  const fileNo = ccH(document.getElementById('ptFileNo').value);

  let age = '';
  if (dob) {
    const b = new Date(dob);
    if (!isNaN(b.getTime())) {
      const t = new Date();
      let a = t.getFullYear() - b.getFullYear();
      const m = t.getMonth() - b.getMonth();
      if (m < 0 || (m === 0 && t.getDate() < b.getDate())) a--;
      age = a + ' years';
    }
  }

  const consult = document.getElementById('certConsultDate').value || localISODate();
  const from = document.getElementById('certFromDate').value;
  const to = document.getElementById('certToDate').value;
  if (!from || !to) { showToast('Please set From and To dates for the indisposition period'); return; }
  const dur = certCalcDuration();
  if (!dur) { showToast('Invalid date range'); return; }

  const type = ccH(document.getElementById('certType').value);
  const disclosure = document.getElementById('certDisclosure').value;
  const dxText = ccH(document.getElementById('certDiagnosis').value).trim();
  const restrictions = ccH(document.getElementById('certRestrictions').value).trim();
  const notes = ccH(document.getElementById('certNotes').value).trim();

  // Practice — from the consult date (P1 latest v3: weekend = prompt + manual choice; never an empty practice address)
  const practice = CCPractice.gate(consult, 'Certificate', printCertificate);
  if (!practice) return;

  // Diagnosis disclosure
  let diagnosisHTML = '';
  if (disclosure === 'generic' || !dxText) {
    diagnosisHTML = 'a medical condition';
  } else if (disclosure === 'code') {
    // Extract codes only
    const codes = [];
    (APP.activeRegions || []).forEach(r => {
      const D = APP.examData[r] || {};
      if (D.icd10) codes.push(ccH(D.icd10));
    });
    diagnosisHTML = codes.length ? 'a medical condition (ICD-10: ' + codes.join(', ') + ')' : 'a medical condition';
  } else {
    diagnosisHTML = dxText;
  }

  // QR code
  const qrPayload = certBuildQrPayload();
  const qr = qrcode(0, 'M');
  qr.addData(qrPayload);
  qr.make();
  const qrSvg = qr.createSvgTag({ scalable: true, margin: 0 });

  const lh = profileLetterheadHTML(practice);
  const sigBlockHTML = profileSignatureBlockHTML();

  const consultFmt = new Date(consult).toLocaleDateString('en-ZA', { day: 'numeric', month: 'long', year: 'numeric' });

  const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Certificate of Indisposition — ${fullName}</title>
<style>
  @page { size: A4; margin: 18mm 16mm; }
  body { font-family: 'Helvetica Neue', Arial, sans-serif; font-size: 11pt; color: #222; line-height: 1.55; }
  .header { border-bottom: 2px solid #2B5F5C; padding-bottom: 10px; margin-bottom: 16px; display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; }
  .header h1 { font-size: 18pt; color: #2B5F5C; margin: 0 0 2px 0; }
  .header .sub { font-size: 9pt; color: #555; }
  .practice-block { text-align: right; font-size: 9.5pt; color: #555; line-height: 1.4; min-width: 30%; }
  .doc-title { text-align: center; font-size: 16pt; font-weight: bold; color: #2B5F5C; letter-spacing: 1.5px; margin: 18px 0 22px; text-transform: uppercase; border-top: 1px solid #2B5F5C; border-bottom: 1px solid #2B5F5C; padding: 10px 0; }
  .body-content { display: flex; gap: 20px; align-items: flex-start; }
  .body-text { flex: 1; }
  .qr-block { width: 130px; flex-shrink: 0; text-align: center; padding: 8px; border: 1px solid #ccc; border-radius: 6px; background: #fafafa; }
  .qr-block svg { width: 110px; height: 110px; }
  .qr-block .qr-label { font-size: 7.5pt; color: #555; margin-top: 4px; }
  .grid { display: grid; grid-template-columns: 130px 1fr; gap: 4px 12px; margin-bottom: 12px; }
  .grid .lbl { font-weight: 600; color: #555; }
  .statement { font-size: 11.5pt; line-height: 1.7; margin: 14px 0; }
  .statement strong { color: #2B5F5C; }
  .period-box { background: #f7f5f2; border: 1px solid #ccc; border-left: 4px solid #2B5F5C; padding: 12px 16px; margin: 12px 0; }
  .period-box .lbl { font-weight: 600; color: #555; font-size: 9.5pt; text-transform: uppercase; letter-spacing: 0.5px; }
  .period-box .val { font-size: 12pt; margin-top: 2px; }
  .period-box .duration { font-size: 14pt; font-weight: bold; color: #2B5F5C; margin-top: 4px; }
  h2 { font-size: 10.5pt; color: #2B5F5C; border-bottom: 1px solid #ccc; padding-bottom: 3px; margin: 16px 0 6px; text-transform: uppercase; letter-spacing: 0.5px; }
  .signature { margin-top: 40px; }
  .footer { margin-top: 24px; font-size: 8.5pt; color: #888; text-align: center; border-top: 1px solid #ddd; padding-top: 6px; }
  @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } .no-print { display: none; } }
  .no-print { position: fixed; top: 10px; right: 10px; background: #2B5F5C; color: white; border: none; padding: 10px 16px; border-radius: 6px; cursor: pointer; font-size: 11pt; }
</style></head>
<body>
<button class="no-print" data-cc-click="window.print()">🖨 Print / Save as PDF</button>

<!--CC-PRACTICE:${practice}-->
<!--LH-HEADER-START-->
<div class="header">
  <div>
    ${lh.practitionerHTML}
  </div>
  <div class="practice-block">
    ${lh.practiceHTML}
  </div>
</div>
<!--LH-HEADER-END-->
<!--LH-BODY-START-->

<div class="doc-title">Certificate of Indisposition</div>

<div class="body-content">
  <div class="body-text">
    <h2>Patient</h2>
    <div class="grid">
      <div class="lbl">Name:</div><div><strong>${fullName}</strong></div>
      ${dob ? '<div class="lbl">Date of Birth:</div><div>' + dob + (age ? ' (' + age + ')' : '') + '</div>' : ''}
      ${gender ? '<div class="lbl">Gender:</div><div>' + gender + '</div>' : ''}
      ${id ? '<div class="lbl">ID Number:</div><div>' + id + '</div>' : ''}
      ${fileNo ? '<div class="lbl">File Number:</div><div>' + fileNo + '</div>' : ''}
    </div>
  </div>
  <div class="qr-block">
    ${qrSvg}
    <div class="qr-label">Scan to verify</div>
  </div>
</div>

<p class="statement">This is to certify that the above-mentioned patient was examined by me on <strong>${consultFmt}</strong> and was found to be suffering from <strong>${diagnosisHTML}</strong>.</p>

<div class="period-box">
  <div class="lbl">${type}</div>
  <div class="val">From: <strong>${dur.fromFmt}</strong></div>
  <div class="val">To: <strong>${dur.toFmt}</strong> (inclusive)</div>
  <div class="duration">${dur.days} ${dur.days === 1 ? 'day' : 'days'}</div>
</div>

${restrictions ? '<h2>Restrictions / Recommendations</h2><p>' + restrictions.replace(/\n/g, '<br>') + '</p>' : ''}

${notes ? '<h2>Additional Notes</h2><p>' + notes.replace(/\n/g, '<br>') + '</p>' : ''}

<div class="signature">${sigBlockHTML}</div>

<div class="footer">Issued electronically on ${new Date().toLocaleString('en-ZA')} · Verify via QR code above</div>

<!--LH-BODY-END-->
</body></html>`;

  const w = window.open('', '_blank');
  if (!w) { showToast('Popup blocked — allow popups to print certificate'); return; }
  w.document.write(lhApplyToHtml(html, { sideMm: 16 }));
  w.document.close();
  CCEv.popup(w, { printAfter: 400 }); // v8 CSP: was an inline <script> in the popup
}

