function ensurePdfLibs() {
  // Libraries are embedded above — no async load needed.
  return Promise.resolve();
}

// Render an HTML string to a PDF Blob.
// Returns a Promise<Blob>.
async function renderHtmlToPdfBlob(html, filename) {
  await ensurePdfLibs();
  const LHc = lhEffective();
  if (LHc.mode !== 'default') html = lhApplyToHtml(html, { forCanvas: true });
  const jsPDF = window.jspdf.jsPDF;
  // Strip the outer <html><head>...</head><body> wrapper. Keep just CSS + body content.
  const styleMatch = html.match(/<style[^>]*>([\s\S]*?)<\/style>/);
  const bodyMatch = html.match(/<body[^>]*>([\s\S]*?)<\/body>/i);
  const cssText = styleMatch ? styleMatch[1] : '';
  const bodyHtml = bodyMatch ? bodyMatch[1] : html;

  // Create a hidden host element with scoped styles
  const scopeId = 'pdf_scope_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7);
  const wrapper = document.createElement('div');
  wrapper.id = scopeId;
  wrapper.style.cssText = 'position:fixed;top:0;left:-99999px;width:794px;background:#ffffff;color:#222;font-family:Helvetica,Arial,sans-serif;box-sizing:border-box';
  // Scope the embedded CSS rules to this wrapper to avoid clobbering the app
  const scopedCss = cssText.replace(/(^|})\s*([^@{}]+){/g, (m, brace, sel) => {
    const trimmed = sel.trim();
    if (!trimmed || trimmed.startsWith('@')) return m;
    const scoped = trimmed.split(',').map(s => {
      const ts = s.trim();
      if (ts === 'body' || ts === 'html') return '#' + scopeId;
      return '#' + scopeId + ' ' + ts;
    }).join(',');
    return brace + scoped + '{';
  });
  const styleTag = document.createElement('style');
  styleTag.textContent = scopedCss;
  document.head.appendChild(styleTag);
  wrapper.innerHTML = bodyHtml;
  document.body.appendChild(wrapper);

  try {
    // Wait for layout + any embedded images
    await new Promise(r => setTimeout(r, 300));
    const imgs = wrapper.querySelectorAll('img');
    await Promise.all([...imgs].map(img => img.complete ? Promise.resolve() :
      new Promise(res => { img.onload = res; img.onerror = res; })));

    const canvas = await window.html2canvas(wrapper, {
      scale: 2,
      useCORS: true,
      backgroundColor: '#ffffff',
      logging: false
    });

    if (!canvas || !canvas.width || !canvas.height) {
      throw new Error('Rendered canvas has zero dimensions (' + (canvas && canvas.width) + 'x' + (canvas && canvas.height) + ')');
    }

    const pdfW = 210; // A4 width mm
    const pdfH = 297; // A4 height mm
    const imgW = pdfW;
    const imgH = (canvas.height / canvas.width) * pdfW;

    const pdf = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });

    if (LHc.mode !== 'default') {
      lhCanvasToPdf(pdf, canvas, LHc);
    } else if (imgH <= pdfH * 1.05) {
      // Fits on one page (or close enough — slight scale to avoid creating a near-empty 2nd page)
      const imgData = canvas.toDataURL('image/jpeg', 0.92);
      const fitH = Math.min(imgH, pdfH);
      pdf.addImage(imgData, 'JPEG', 0, 0, imgW, fitH);
    } else {
      // Multi-page slicing — find natural break points (whitespace rows) to avoid cutting through text
      const ctx = canvas.getContext('2d');
      const pxPerMm = canvas.width / pdfW;
      const pageHeightPx = Math.floor(pdfH * pxPerMm);
      // helper: detect if a row is "blank-ish" (mostly white pixels)
      function rowIsWhitespace(y, sampleStep) {
        if (y < 0 || y >= canvas.height) return false;
        try {
          const data = ctx.getImageData(0, y, canvas.width, 1).data;
          let darkPixels = 0;
          for (let x = 0; x < canvas.width; x += sampleStep) {
            const i = x * 4;
            // RGB darker than ~245 = content
            if (data[i] < 245 || data[i+1] < 245 || data[i+2] < 245) darkPixels++;
          }
          return darkPixels < 3; // allow up to 2 noisy pixels
        } catch(e) { return false; }
      }
      let yPx = 0;
      let pageIdx = 0;
      const maxBackOffPx = Math.floor(15 * pxPerMm); // up to 15mm back
      while (yPx < canvas.height) {
        let sliceHeight;
        if (yPx + pageHeightPx >= canvas.height) {
          // last page — take everything that's left
          sliceHeight = canvas.height - yPx;
        } else {
          let target = yPx + pageHeightPx;
          // Walk up until we find a row of whitespace
          let breakAt = target;
          for (let dy = 0; dy < maxBackOffPx; dy += 2) {
            if (rowIsWhitespace(target - dy, 4)) {
              // Check that we have a few consecutive whitespace rows (not a tiny gap)
              let consecutive = 0;
              for (let k = 0; k < 4; k++) {
                if (rowIsWhitespace(target - dy - k, 4)) consecutive++;
              }
              if (consecutive >= 3) { breakAt = target - dy; break; }
            }
          }
          sliceHeight = breakAt - yPx;
          if (sliceHeight < pageHeightPx * 0.3) sliceHeight = pageHeightPx; // safety: don't make a tiny page
        }
        if (sliceHeight <= 0) break;
        const slice = document.createElement('canvas');
        slice.width = canvas.width;
        slice.height = sliceHeight;
        const sctx = slice.getContext('2d');
        sctx.fillStyle = '#ffffff';
        sctx.fillRect(0, 0, slice.width, slice.height);
        sctx.drawImage(canvas, 0, -yPx);
        const sliceData = slice.toDataURL('image/jpeg', 0.92);
        const sliceMm = sliceHeight / pxPerMm;
        if (pageIdx > 0) pdf.addPage();
        pdf.addImage(sliceData, 'JPEG', 0, 0, pdfW, sliceMm);
        yPx += sliceHeight;
        pageIdx++;
      }
    }
    return pdf.output('blob');
  } finally {
    document.body.removeChild(wrapper);
    document.head.removeChild(styleTag);
  }
}

// Strip the floating no-print buttons (the print/email buttons in the document window)
// before rendering to PDF, so they don't appear on the saved file.
function stripNoPrintFromHtml(html) {
  return html.replace(/<button class="no-print"[^>]*>[\s\S]*?<\/button>/g, '')
             .replace(/<script[\s\S]*?window\.print\(\)[\s\S]*?<\/script>/g, '');
}

// Share or download a PDF Blob, then optionally open mailto.
// Uses Web Share API on mobile/iPad (works on iOS Safari 15+, Chrome Android).
// Falls back to download + mailto on desktop.
async function sharePdfBlob(pdfBlob, filename, recipientEmail, subject, body) {
  const file = new File([pdfBlob], filename, { type: 'application/pdf' });

  // Try Web Share API with files (mobile-friendly)
  if (navigator.canShare && navigator.canShare({ files: [file] })) {
    try {
      await navigator.share({
        files: [file],
        title: subject || filename,
        text: body || ''
      });
      return { method: 'share' };
    } catch (e) {
      if (e.name === 'AbortError') return { method: 'aborted' };
      // Fall through to download fallback
      console.warn('Share failed, falling back to download', e);
    }
  }

  // Fallback: download the PDF + open mailto
  const url = URL.createObjectURL(pdfBlob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1500);

  if (recipientEmail) {
    const mailto = 'mailto:' + recipientEmail +
      '?subject=' + encodeURIComponent(subject || '') +
      '&body=' + encodeURIComponent((body || '') + '\n\nPlease find the PDF attached (downloaded to your device — drag it into this email before sending).');
    setTimeout(() => { window.location.href = mailto; }, 500);
  }
  return { method: 'download' };
}



const REFERRAL_DATABASE_VERSION = 'sa-referrals-2026-08-22-v1';

function importReferralDatabase(options) {
  options = options || {};
  const database = Array.isArray(window.CHIROCLINIC_REFERRAL_DATABASE) ? window.CHIROCLINIC_REFERRAL_DATABASE : [];
  if (!database.length) {
    if (!options.silent) showToast('Referral database is unavailable');
    return 0;
  }
  const existing = loadReferralNetwork();
  const knownDatabaseIds = new Set(existing.map(p => p.databaseId).filter(Boolean));
  const knownKeys = new Set(existing.map(p => [p.name, p.type, p.area].map(v => (v || '').toLowerCase().trim()).join('|')));
  let added = 0;
  database.forEach(source => {
    const key = [source.name, source.type, source.area].map(v => (v || '').toLowerCase().trim()).join('|');
    if (knownDatabaseIds.has(source.databaseId) || knownKeys.has(key)) return;
    existing.push({
      id: 'p_db_' + source.databaseId,
      databaseId: source.databaseId,
      name: source.name,
      type: source.type,
      province: source.province || '',
      practice: source.practice || '',
      area: source.area || source.province || '',
      phone: source.phone || '',
      email: source.email || '',
      address: source.address || '',
      source: source.source || '',
      notes: source.notes || '',
      starred: false
    });
    knownDatabaseIds.add(source.databaseId);
    knownKeys.add(key);
    added++;
  });
  saveReferralNetwork(existing);
  localStorage.setItem('chiroclinic_referral_database_version', REFERRAL_DATABASE_VERSION);
  if (!options.silent) {
    showToast(added ? ('Added ' + added + ' referral provider' + (added === 1 ? '' : 's')) : 'SA referral database is up to date');
    renderReferralNetworkList();
    updateReferralFilters();
  }
  return added;
}

function ensureReferralDatabaseInitialized() {
  if (localStorage.getItem('chiroclinic_referral_database_version') === REFERRAL_DATABASE_VERSION) return;
  importReferralDatabase({ silent: true });
}

