function seedReferralNetwork() {
  const existing = loadReferralNetwork();
  if (existing.length > 0) {
    if (!confirm('Your network already has ' + existing.length + ' practitioner' + (existing.length === 1 ? '' : 's') +
                 '. Add the starter set to existing entries? (Duplicates will not be added.)')) return;
  }
  const existingNames = new Set(existing.map(p => (p.name || '').toLowerCase()));
  let added = 0;
  REFERRAL_NETWORK_SEED.forEach(s => {
    if (existingNames.has((s.name || '').toLowerCase())) return;
    existing.push({
      id: 'p_seed_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7),
      name: s.name, type: s.type, area: s.area,
      phone: s.phoneSeed || '', email: s.emailSeed || '',
      address: s.address || '',
      notes: s.notes || '',
      starred: false
    });
    added++;
  });
  saveReferralNetwork(existing);
  showToast('Added ' + added + ' starter practitioner' + (added === 1 ? '' : 's'));
  renderReferralNetworkList();
  updateReferralFilters();
}

function clearReferralNetwork() {
  const existing = loadReferralNetwork();
  if (existing.length === 0) { showToast('Network is already empty'); return; }
  if (!confirm('Permanently delete all ' + existing.length + ' practitioner' + (existing.length === 1 ? '' : 's') + ' from your network? This cannot be undone.')) return;
  saveReferralNetwork([]);
  renderReferralNetworkList();
  updateReferralFilters();
  showToast('Network cleared');
}

function toggleStarPractitioner(id) {
  const network = loadReferralNetwork();
  const p = network.find(x => x.id === id);
  if (!p) return;
  p.starred = !p.starred;
  saveReferralNetwork(network);
  renderReferralNetworkList();
  updateReferralFilters();
}

function loadReferralNetwork() {
  try {
    const raw = localStorage.getItem('chiroclinic_referral_network');
    if (!raw) return [];
    const arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr : [];
  } catch(e) { return []; }
}

function saveReferralNetwork(arr) {
  try {
    localStorage.setItem('chiroclinic_referral_network', JSON.stringify(arr));
    return true;
  } catch(e) { return false; }
}

function refSelectedTypes() {
  return [...document.querySelectorAll('#refTypeChips .chip.active')].map(c => c.dataset.val);
}

function toggleRefType(el) {
  el.classList.toggle('active');
  updateReferralFilters();
}

// Sort helper: starred first, then alphabetical
function refSortFn(a, b) {
  if ((b.starred ? 1 : 0) !== (a.starred ? 1 : 0)) return (b.starred ? 1 : 0) - (a.starred ? 1 : 0);
  return (a.name || '').localeCompare(b.name || '');
}

function updateReferralFilters() {
  const network = loadReferralNetwork();
  const selectedTypes = refSelectedTypes();
  const areaSel = document.getElementById('refArea');
  const currentArea = areaSel.value;

  let filtered = network;
  if (selectedTypes.length) {
    filtered = network.filter(p => selectedTypes.includes(p.type));
  }

  const areas = [...new Set(filtered.map(p => p.area).filter(Boolean))].sort();
  areaSel.innerHTML = '<option value="">— Any area —</option>' +
    areas.map(a => '<option value="' + ccH(a) + '">' + ccH(a) + '</option>').join('');
  if (areas.includes(currentArea)) areaSel.value = currentArea;

  updateReferralPractitionerList();

  const count = network.length;
  const starredCount = network.filter(p => p.starred).length;
  document.getElementById('refNetworkCount').textContent =
    count === 0 ? 'Network is empty' :
    (count === 1 ? '1 practitioner' : count + ' practitioners') +
    (starredCount ? ' · ' + starredCount + ' starred ★' : '');
}

function updateReferralPractitionerList() {
  const network = loadReferralNetwork();
  const selectedTypes = refSelectedTypes();
  const area = document.getElementById('refArea').value;
  const sel = document.getElementById('refPractitioner');
  const currentId = sel.value;

  let filtered = network;
  if (selectedTypes.length) filtered = filtered.filter(p => selectedTypes.includes(p.type));
  if (area) filtered = filtered.filter(p => p.area === area);
  filtered.sort(refSortFn);

  if (filtered.length === 0) {
    sel.innerHTML = '<option value="">— No practitioners match —</option>';
  } else {
    sel.innerHTML = '<option value="">— Select practitioner —</option>' +
      filtered.map(pRaw => {
        const p = ccEscObj(pRaw);
        const star = p.starred ? '★ ' : '';
        return '<option value="' + p.id + '">' + star + p.name + ' (' + p.type + (p.area ? ' · ' + p.area : '') + ')</option>';
      }).join('');
    if (filtered.find(p => p.id === currentId)) sel.value = currentId;
  }

  onReferralPractitionerSelected();
}

function onReferralPractitionerSelected() {
  const id = document.getElementById('refPractitioner').value;
  const preview = document.getElementById('refSelectedPreview');
  if (!id) { preview.style.display = 'none'; return; }
  const pRaw = loadReferralNetwork().find(x => x.id === id);
  if (!pRaw) { preview.style.display = 'none'; return; }
  const p = ccEscObj(pRaw);
  preview.style.display = 'block';
  const star = p.starred ? '<span style="color:#f59e0b;font-size:14px" title="Starred">★</span> ' : '';
  let html = star + '<strong>' + p.name + '</strong> <span style="color:var(--text3)">— ' + p.type + '</span>';
  if (p.area) html += '<br><span style="color:var(--text2)">' + p.area + '</span>';
  if (p.phone) html += '<br><span style="color:var(--text2)">📞 ' + p.phone + '</span>';
  if (p.email) html += '<br><span style="color:var(--text2)">✉️ ' + p.email + '</span>';
  if (p.address) html += '<br><span style="color:var(--text2)">' + p.address.replace(/\n/g, ', ') + '</span>';
  if (p.notes) html += '<br><em style="color:var(--text3);font-size:11px">' + p.notes + '</em>';
  if (!p.phone && !p.email) {
    html += '<br><span style="color:var(--red);font-size:11px;font-weight:600">⚠ No phone/email — add via "Manage Network" before referring</span>';
  }
  preview.innerHTML = html;
}

// ----- Manage Network modal -----

function showReferralNetworkModal() {
  hideReferralEditor();
  renderReferralNetworkList();
  document.getElementById('referralNetworkModal').classList.add('show');
}

function renderReferralNetworkList() {
  const search = (document.getElementById('refNetSearch').value || '').toLowerCase().trim();
  const showStarredOnly = document.getElementById('refNetStarredOnly') && document.getElementById('refNetStarredOnly').checked;
  let network = loadReferralNetwork();
  if (search) {
    network = network.filter(p =>
      (p.name || '').toLowerCase().includes(search) ||
      (p.type || '').toLowerCase().includes(search) ||
      (p.area || '').toLowerCase().includes(search) ||
      (p.province || '').toLowerCase().includes(search) ||
      (p.practice || '').toLowerCase().includes(search) ||
      (p.address || '').toLowerCase().includes(search)
    );
  }
  if (showStarredOnly) network = network.filter(p => p.starred);
  network.sort(refSortFn);

  // Update area suggestions datalist
  const allAreas = [...new Set(loadReferralNetwork().map(p => p.area).filter(Boolean))].sort();
  document.getElementById('refAreaSuggestions').innerHTML = allAreas.map(a => '<option value="' + ccH(a) + '">').join('');

  const box = document.getElementById('refNetList');
  if (network.length === 0) {
    box.innerHTML = '<em style="color:var(--text3);padding:16px;display:block;text-align:center">' +
      (search ? 'No matches for "' + ccH(search) + '"' :
       showStarredOnly ? 'No starred practitioners yet — tap a ☆ to star one.' :
       'Network is empty — tap "+ Add New" or "↻ Sync SA Database" to populate it.') +
      '</em>';
    return;
  }
  box.innerHTML = network.map(pRaw => {
    const p = ccEscObj(pRaw);
    const starIcon = p.starred ? '★' : '☆';
    const starColor = p.starred ? '#f59e0b' : '#ccc';
    const noContact = !p.phone && !p.email;
    return '<div style="padding:10px 12px;border-bottom:1px solid var(--border);display:flex;gap:8px;align-items:center;justify-content:space-between">' +
      "<button data-cc-click=\"toggleStarPractitioner(" + ccH(JSON.stringify(String(pRaw.id))) + ')" title="' + (p.starred ? 'Unstar' : 'Star') + '" style="background:none;border:none;color:' + starColor + ';font-size:20px;cursor:pointer;padding:0 4px;line-height:1">' + starIcon + '</button>' +
      '<div style="flex:1;min-width:0">' +
        '<div style="font-weight:600;color:var(--text)">' + p.name + (noContact ? ' <span style="color:var(--red);font-size:10px;font-weight:600">⚠ no contact</span>' : '') + '</div>' +
        '<div style="font-size:12px;color:var(--text2)">' + p.type + (p.area ? ' · ' + p.area : '') + '</div>' +
        (p.email || p.phone ? '<div style="font-size:11px;color:var(--text3);margin-top:2px">' + [p.phone, p.email].filter(Boolean).join(' · ') + '</div>' : '') +
      '</div>' +
      '<div style="display:flex;gap:4px;flex-shrink:0">' +
        "<button data-cc-click=\"showReferralEditor(" + ccH(JSON.stringify(String(pRaw.id))) + ')" style="background:var(--accent2);color:#fff;padding:6px 10px;border-radius:5px;font-size:11px">Edit</button>' +
        "<button data-cc-click=\"deleteReferralPractitioner(" + ccH(JSON.stringify(String(pRaw.id))) + ')" style="background:var(--red);color:#fff;padding:6px 10px;border-radius:5px;font-size:11px">×</button>' +
      '</div>' +
    '</div>';
  }).join('');
}

function showReferralEditor(id) {
  const editor = document.getElementById('refNetEditor');
  if (id) {
    const p = loadReferralNetwork().find(x => x.id === id);
    if (!p) return;
    document.getElementById('refEdId').value = p.id;
    document.getElementById('refEdName').value = p.name || '';
    document.getElementById('refEdType').value = p.type || '';
    document.getElementById('refEdArea').value = p.area || '';
    document.getElementById('refEdPhone').value = p.phone || '';
    document.getElementById('refEdEmail').value = p.email || '';
    document.getElementById('refEdAddress').value = p.address || '';
    document.getElementById('refEdNotes').value = p.notes || '';
  } else {
    document.getElementById('refEdId').value = '';
    ['refEdName','refEdType','refEdArea','refEdPhone','refEdEmail','refEdAddress','refEdNotes'].forEach(id => {
      document.getElementById(id).value = '';
    });
  }
  editor.style.display = 'block';
  // Scroll modal to editor
  setTimeout(() => editor.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
}

function hideReferralEditor() {
  document.getElementById('refNetEditor').style.display = 'none';
}

function saveReferralPractitioner() {
  const name = document.getElementById('refEdName').value.trim();
  const type = document.getElementById('refEdType').value.trim();
  const area = document.getElementById('refEdArea').value.trim();
  if (!name) { showToast('Name is required'); return; }
  if (!type) { showToast('Type is required'); return; }
  if (!area) { showToast('Area is required'); return; }

  const id = document.getElementById('refEdId').value || ('p_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7));
  const network = loadReferralNetwork();
  const existing = network.find(x => x.id === id);
  const p = {
    ...(existing || {}),
    id, name, type, area,
    phone: document.getElementById('refEdPhone').value.trim(),
    email: document.getElementById('refEdEmail').value.trim(),
    address: document.getElementById('refEdAddress').value.trim(),
    notes: document.getElementById('refEdNotes').value.trim(),
    starred: existing ? !!existing.starred : false
  };

  const idx = network.findIndex(x => x.id === id);
  if (idx >= 0) network[idx] = p; else network.push(p);
  if (!saveReferralNetwork(network)) { showToast('Could not save'); return; }

  showToast('Practitioner saved');
  hideReferralEditor();
  renderReferralNetworkList();
  updateReferralFilters();
}

function deleteReferralPractitioner(id) {
  if (!confirm('Delete this practitioner from your network?')) return;
  const network = loadReferralNetwork().filter(x => x.id !== id);
  saveReferralNetwork(network);
  renderReferralNetworkList();
  updateReferralFilters();
  showToast('Practitioner removed');
}

// ----- Address report / generate referral letter -----

function getSelectedReferralPractitioner() {
  const id = document.getElementById('refPractitioner').value;
  if (!id) return null;
  return loadReferralNetwork().find(x => x.id === id) || null;
}

function addressReportToReferral() {
  const p = getSelectedReferralPractitioner();
  if (!p) { showToast('Select a practitioner first'); return; }
  const profile = loadProfile();
  const reportEl = document.getElementById('reportOutput');
  let body = (reportEl.value || '').trim();

  // Strip any prior "Dear ..." salutation and "Yours sincerely ..." sign-off
  body = body.replace(/^Dear[^\n]*\n+/i, '').replace(/\n+Yours sincerely[\s\S]*$/i, '').trim();

  const salutation = 'Dear ' + p.name + ',';
  const reLine = 'RE: ' +
    [document.getElementById('ptFirstName').value, document.getElementById('ptLastName').value].filter(Boolean).join(' ') +
    (document.getElementById('ptDOB').value ? ' (DOB ' + document.getElementById('ptDOB').value + ')' : '');

  const signoff =
    'Yours sincerely,\n\n' +
    profile.name + '\n' +
    profile.quals + '\n' +
    'Pr nr: ' + profile.prNo;

  reportEl.value = salutation + '\n\n' + reLine + '\n\n' + body + '\n\n' + signoff;
  showToast('Report addressed to ' + p.name);
}

function buildReferralLetterHtml(pRaw) {
  const p = ccEscObj(pRaw || {}); // P1 v6 audit: recipient fields escaped for HTML
  // Returns the full HTML string for the referral letter (used both for print window and PDF generation).
  const fn = (ccH(document.getElementById('ptFirstName').value) || '').trim();
  const ln = (ccH(document.getElementById('ptLastName').value) || '').trim();
  const fullName = (fn + ' ' + ln).trim();
  if (!fullName) return null;

  const dob = ccH(document.getElementById('ptDOB').value);
  const id = ccH(document.getElementById('ptID').value);
  const gender = ccH(document.getElementById('ptGender').value);
  const phone = ccH(document.getElementById('ptPhone').value);
  const medAid = ccH(document.getElementById('ptMedAid').value);
  const medAidNo = ccH(document.getElementById('ptMedAidNo').value);

  let age = '';
  if (dob) {
    const b = new Date(dob);
    if (!isNaN(b.getTime())) {
      const t = new Date();
      let a = t.getFullYear() - b.getFullYear();
      const m = t.getMonth() - b.getMonth();
      if (m < 0 || (m === 0 && t.getDate() < b.getDate())) a--;
      age = a + ' years';
    }
  }

  const visitDate = document.getElementById('visitDate').value || localISODate();
  // P1 latest v3: callers gate first (CCPractice.gate); here only the resolved name is read
  const practice = CCPractice.forDate(visitDate).name;

  const complaint = ccH(document.getElementById('pcRegion').value);
  const side = ccH(document.getElementById('pcSide').value);
  const duration = ccH(document.getElementById('pcDuration').value);
  const onset = ccH(document.getElementById('pcOnset').value);

  const dxList = imgBuildDxList();
  const dxHTML = dxList.length ?
    dxList.map(d => '<div>' + (d.code ? '<strong>' + ccH(d.code) + '</strong> — ' : '') + ccH(d.dx || '') +
      (d.primary ? ' <em style="color:#666">(primary)</em>' : ' <em style="color:#666">(secondary)</em>') + '</div>').join('') :
    '<div><em>No working diagnosis recorded</em></div>';

  const clinicalHx = ccH(imgBuildClinicalHistory());
  const aiReport = (document.getElementById('reportOutput').value || '').trim();

  const referralReasons = {
    'General Practitioner': 'general medical assessment, ongoing care coordination, and possible prescription of analgesics or anti-inflammatories as you deem appropriate',
    'Chiropractor': 'continuation of chiropractic care closer to the patient\'s residence',
    'Physiotherapist': 'rehabilitation and progressive strengthening protocol',
    'Biokineticist': 'biokinetic rehabilitation and graded return-to-activity programme',
    'Occupational Therapist': 'occupational therapy assessment and ergonomic intervention',
    'Neurologist': 'specialist neurological assessment and electrophysiological studies if indicated',
    'Neurosurgeon': 'specialist neurosurgical opinion regarding surgical candidacy',
    'Orthopaedic Surgeon': 'specialist orthopaedic assessment and surgical opinion',
    'Rheumatologist': 'rheumatological assessment and inflammatory work-up',
    'Sports Medicine': 'sports medicine assessment and return-to-sport guidance',
    'Pain Management': 'specialist pain management assessment and consideration of interventional options',
    'Psychologist': 'psychological assessment and supportive therapy',
    'Psychiatrist': 'psychiatric assessment',
    'Podiatrist': 'podiatric assessment and orthotic prescription',
    'Physician': 'specialist medical assessment and management',
    'Other': 'specialist assessment and management as you deem appropriate'
  };
  const reason = referralReasons[p.type] || referralReasons['Other'];

  // ----- Build practice contact block from profile -----
  const profile = ccEscObj(loadProfile());
  let practiceAddrLines = '', practicePhoneLine = '', practiceEmailLine = '';
  if (ccPracticeId(practice) === 'melkbos') {
    practiceAddrLines = (profile.melkbosAddr || '').trim();
    practicePhoneLine = (profile.melkbosPhone || '').trim();
    practiceEmailLine = (profile.melkbosEmail || '').trim();
  } else if (ccPracticeId(practice) === 'vred') {
    practiceAddrLines = (profile.vredAddr || '').trim();
    practicePhoneLine = (profile.vredPhone || '').trim();
    practiceEmailLine = (profile.vredEmail || '').trim();
  }

  // ----- Reference number + long-form date -----
  const refDate = localISODate();
  const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const tdy = new Date();
  const refDateLong = tdy.getDate() + ' ' + monthNames[tdy.getMonth()] + ' ' + tdy.getFullYear();
  const initials = ((fn[0] || '') + (ln[0] || '')).toUpperCase() || 'XX';
  const refNo = 'TJG-' + refDate.replace(/-/g, '') + '-' + initials;

  // ----- Logo (sourced from app header to avoid duplicating the base64 string) -----
  let logoSrc = '';
  try {
    const hdrImg = document.querySelector('.header-logo img');
    if (hdrImg && hdrImg.src) logoSrc = ccSafeImgSrc(hdrImg.src);
  } catch (e) { logoSrc = ''; }

  // ----- Pronouns -----
  const pronoun = gender === 'Female' ? 'her' : (gender === 'Male' ? 'him' : 'this patient');

  // ----- Body content (preserves existing logic) -----
  let bodyContent;
  if (aiReport) {
    let stripped = aiReport.replace(/^Dear[^\n]*\n+/i, '').replace(/\n+Yours sincerely[\s\S]*$/i, '').trim();
    bodyContent = '<div style="white-space:pre-wrap">' + stripped.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</div>';
  } else {
    bodyContent = '<div class="rl-section-title">Clinical History</div><div class="rl-clinical-block">' + (clinicalHx || '<em>No clinical history recorded</em>').replace(/\n/g, '<br>') + '</div>' +
                  '<div class="rl-section-title">Working Diagnosis</div>' + dxHTML;
  }

  // ----- Recipient lines (To block) -----
  let recipientLines = ['<strong style="color:#2a2a2a">' + p.name + '</strong>', p.type];
  if (p.address) {
    p.address.split('\n').forEach(line => { if (line.trim()) recipientLines.push(line); });
  } else if (p.area) {
    recipientLines.push(p.area);
  }
  if (p.phone) recipientLines.push('Tel: ' + p.phone);
  if (p.email) recipientLines.push(p.email);
  const recipientBlockHTML = recipientLines.join('<br>');

  // ----- Patient lines -----
  let patientLines = ['<strong style="color:#2a2a2a">' + fullName + '</strong>'];
  if (dob) patientLines.push('DOB: ' + dob + (age ? ' &middot; ' + age : ''));
  if (gender) patientLines.push('Gender: ' + gender);
  if (id) patientLines.push('ID: ' + id);
  if (phone) patientLines.push('Tel: ' + phone);
  if (medAid) patientLines.push('Med Aid: ' + medAid + (medAidNo ? ' / ' + medAidNo : ''));
  const patientBlockHTML = patientLines.join('<br>');

  // ----- Signature block (built inline, not via helper) -----
  const sigImgHTML = profile.signature ?
    '<div style="margin:6px 0"><img src="' + profile.signature + '" alt="" style="max-width:200px;max-height:60px;display:block"></div>' : '';

  const _js = v => JSON.stringify(String(v || '')).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026').replace(/'/g, '\\u0027');
  const _rawFull = ((document.getElementById('ptFirstName').value || '').trim() + ' ' + (document.getElementById('ptLastName').value || '').trim()).trim();
  const safeRecName = _js((pRaw && pRaw.name) || '').slice(1, -1);
  const safeFullName = _js(_rawFull).slice(1, -1);
  const safeProfileName = _js(loadProfile().name || 'Dr TJ Greyvensteyn').slice(1, -1);
  // v8 CSP: the popup's emailLetter() script is gone; the same mailto (same subject/body text) is built here and wired by CCEv.popup
  const _ccMailto = 'mailto:' + (p.email || '') + '?subject=' + encodeURIComponent('Referral: ' + _rawFull + ' ' + (dob ? '(DOB ' + dob + ')' : '')) + '&body=' + encodeURIComponent(
    'Dear ' + ((pRaw && pRaw.name) || '') + ',\n\n' +
    'Please find attached my referral letter for ' + _rawFull + (dob ? ' (DOB ' + dob + ')' : '') + '.\n\n' +
    'Print or save the open document as PDF and attach it to this email before sending.\n\n' +
    'Kind regards,\n' + (loadProfile().name || 'Dr TJ Greyvensteyn'));
  const _ccMailtoAttr = _ccMailto.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  return `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Referral Letter — ${fullName} → ${p.name}</title>
<style>
  @page { size: A4; margin: 0; }
  * { box-sizing: border-box; }
  body { font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif; font-size: 10.5pt; color: #2a2a2a; line-height: 1.5; margin: 0; background: #ffffff; -webkit-font-smoothing: antialiased; }

  .rl-band { background: #2B5F5C; color: #ffffff; padding: 11mm 16mm 9mm; display: flex; justify-content: space-between; align-items: flex-start; gap: 12mm; }
  .rl-band-id { display: flex; align-items: flex-start; gap: 5mm; flex: 1; min-width: 0; }
  .rl-band-logo { width: 18mm; height: 18mm; border-radius: 50%; background: #ffffff; padding: 2mm; box-sizing: border-box; flex-shrink: 0; box-shadow: 0 2px 6px rgba(0,0,0,0.15); display: flex; align-items: center; justify-content: center; }
  .rl-band-logo img { width: 100%; height: 100%; object-fit: contain; display: block; }
  .rl-band-left { flex: 1; min-width: 0; padding-top: 1mm; }
  .rl-band-name { font-size: 20pt; font-weight: 700; letter-spacing: 0.2px; margin: 0 0 3px 0; color: #ffffff; line-height: 1.15; }
  .rl-band-quals { font-size: 9.5pt; color: rgba(255,255,255,0.88); margin-bottom: 4px; font-weight: 400; letter-spacing: 0.3px; }
  .rl-band-meta { font-size: 8.5pt; color: rgba(255,255,255,0.78); letter-spacing: 0.4px; }
  .rl-band-right { text-align: right; font-size: 8.5pt; color: rgba(255,255,255,0.92); line-height: 1.5; min-width: 38%; padding-top: 3px; }
  .rl-band-right .rl-practice-name { font-weight: 700; font-size: 9.5pt; color: #ffffff; margin-bottom: 3px; letter-spacing: 0.4px; }

  .rl-doc-title { text-align: center; font-size: 10.5pt; font-weight: 700; color: #2B5F5C; letter-spacing: 6px; margin: 8mm 16mm 6mm; text-transform: uppercase; padding-bottom: 3mm; border-bottom: 1px solid #d8d4cc; }

  .rl-meta-row { display: flex; justify-content: space-between; margin: 0 16mm 6mm; font-size: 9pt; color: #6b6b6b; }
  .rl-meta-row strong { color: #2a2a2a; font-weight: 600; }

  .rl-blocks { display: flex; gap: 6mm; margin: 0 16mm 7mm; }
  .rl-block { flex: 1; background: #faf8f4; border-left: 3px solid #2B5F5C; padding: 8px 11px; font-size: 9.5pt; line-height: 1.5; min-width: 0; }
  .rl-block-label { font-size: 7.5pt; color: #2B5F5C; font-weight: 700; letter-spacing: 1.8px; text-transform: uppercase; margin-bottom: 4px; }

  .rl-body { padding: 0 16mm; }
  .rl-body p { margin: 4mm 0; }
  .rl-body p.rl-greeting { margin-top: 5mm; margin-bottom: 3mm; }

  .rl-section-title { font-size: 9pt; color: #2B5F5C; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; margin: 5mm 0 2mm; padding-bottom: 1.5mm; border-bottom: 1px solid #d8d4cc; }
  .rl-clinical-block { background: #faf8f4; border-left: 3px solid #2B5F5C; padding: 7px 11px; margin: 3mm 0; }

  .rl-signature { margin: 6mm 16mm 0; page-break-inside: avoid; }
  .rl-signature .rl-sign-name { font-weight: 700; color: #2a2a2a; font-size: 10.5pt; margin-top: 2mm; }
  .rl-signature .rl-sign-quals { font-size: 9pt; color: #6b6b6b; }

  .rl-footer { margin: 7mm 16mm 6mm; padding-top: 3mm; border-top: 1px solid #e8e4dc; font-size: 7.5pt; color: #999; text-align: center; letter-spacing: 0.4px; }

  @media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } .no-print { display: none !important; } }
  .no-print { position: fixed; top: 10px; right: 10px; background: #2B5F5C; color: white; border: none; padding: 10px 16px; border-radius: 6px; cursor: pointer; font-size: 11pt; z-index: 1000; box-shadow: 0 2px 8px rgba(0,0,0,0.2); }
  .no-print.email { right: 220px; background: #3A7D79; }
</style></head>
<body>
<button class="no-print" data-cc-click="window.print()">🖨 Print / Save as PDF</button>
${p.email ? '<button class="no-print email" data-cc-click="emailLetter()" data-cc-mailto="' + _ccMailtoAttr + '">✉️ Open Email Client</button>' : ''}

<!--CC-PRACTICE:${practice}-->
<!--LH-HEADER-START-->
<div class="rl-band">
  <div class="rl-band-id">
    ${logoSrc ? '<div class="rl-band-logo"><img src="' + logoSrc + '" alt=""></div>' : ''}
    <div class="rl-band-left">
      <div class="rl-band-name">${profile.name || 'Practitioner Name'}</div>
      <div class="rl-band-quals">${profile.quals || ''}</div>
      <div class="rl-band-meta">${[profile.prNo ? 'Pr No: ' + profile.prNo : '', profile.mobile].filter(Boolean).join(' &middot; ')}</div>
    </div>
  </div>
  <div class="rl-band-right">
    ${practice ? '<div class="rl-practice-name">' + practice + '</div>' : ''}
    ${practiceAddrLines ? practiceAddrLines.replace(/\n/g, '<br>') : ''}
    ${practicePhoneLine ? (practiceAddrLines ? '<br>' : '') + 'Tel: ' + practicePhoneLine : ''}
    ${practiceEmailLine ? '<br>' + practiceEmailLine : ''}
  </div>
</div>

<!--LH-HEADER-END-->
<!--LH-BODY-START-->
<div class="rl-doc-title">Referral Letter</div>

<div class="rl-meta-row">
  <div><strong>Date:</strong> ${refDateLong}</div>
  <div><strong>Ref:</strong> ${refNo}</div>
</div>

<div class="rl-blocks">
  <div class="rl-block">
    <div class="rl-block-label">To</div>
    ${recipientBlockHTML}
  </div>
  <div class="rl-block">
    <div class="rl-block-label">Re Patient</div>
    ${patientBlockHTML}
  </div>
</div>

<div class="rl-body">
  <p class="rl-greeting">Dear ${p.name},</p>
  <p>Thank you for seeing this patient. I am referring ${pronoun} for ${reason}.</p>

  ${complaint ? '<div class="rl-section-title">Presenting Complaint</div><p>' + complaint + (side ? ' (' + side + ')' : '') + (duration ? ', ' + duration + ' duration' : '') + (onset ? ', onset ' + onset : '') + '.</p>' : ''}

  ${bodyContent}

  ${p.notes ? '<p style="margin-top:6mm"><em style="color:#888;font-size:9pt">Note to recipient: ' + p.notes + '</em></p>' : ''}

  <p style="margin-top:6mm">Please do not hesitate to contact me should you require any further clinical information.</p>
</div>

<div class="rl-signature">
  <p style="margin:0 0 4mm">Yours sincerely,</p>
  ${sigImgHTML}
  <div class="rl-sign-name">${profile.name || ''}</div>
  <div class="rl-sign-quals">${profile.quals || ''}${profile.prNo ? ' &middot; Pr No: ' + profile.prNo : ''}</div>
</div>

<div class="rl-footer">
  Generated electronically on ${refDateLong}${profile.prNo ? ' &middot; Pr No ' + profile.prNo : ''}${refNo ? ' &middot; Ref ' + refNo : ''}
</div>

<!--LH-BODY-END-->
</body></html>`;
}

function generateReferralLetter() {
  const p = getSelectedReferralPractitioner();
  if (!p) { showToast('Select a practitioner first'); return; }
  if (!CCPractice.gate(document.getElementById('visitDate').value || localISODate(), 'Referral letter', generateReferralLetter)) return;
  const html = buildReferralLetterHtml(p);
  if (!html) { showToast('Patient name required'); return; }

  const w = window.open('', '_blank');
  if (!w) { showToast('Popup blocked — allow popups to print referral'); return; }
  w.document.write(lhApplyToHtml(html, { sideMm: 0, padMm: 16 }));
  w.document.close();
  CCEv.popup(w, { printAfter: 600 }); // v8 CSP: was an inline <script> in the popup
}

async function emailReferralLetterWithPdf() {
  const p = getSelectedReferralPractitioner();
  if (!p) { showToast('Select a practitioner first'); return; }
  if (!p.email) { showToast('No email on file for ' + p.name + '. Add via "Manage Network".'); return; }
  if (!CCPractice.gate(document.getElementById('visitDate').value || localISODate(), 'Referral letter', emailReferralLetterWithPdf)) return;
  const html = buildReferralLetterHtml(p);
  if (!html) { showToast('Patient name required'); return; }

  const fn = (document.getElementById('ptFirstName').value || '').trim();
  const ln = (document.getElementById('ptLastName').value || '').trim();
  const dob = document.getElementById('ptDOB').value || '';
  const fullName = (fn + ' ' + ln).trim();
  const filename = 'Referral_' + fullName.replace(/[^a-zA-Z0-9]/g, '_') + '_' + localISODate() + '.pdf';

  const cleanHtml = stripNoPrintFromHtml(html);
  const subject = 'Referral: ' + fullName + (dob ? ' (DOB ' + dob + ')' : '');
  const body = 'Dear ' + p.name + ',\n\nPlease find attached my referral letter for ' + fullName +
               (dob ? ' (DOB ' + dob + ')' : '') + '.\n\nKind regards,\n' + (loadProfile().name || 'Dr TJ Greyvensteyn');

  const btn = document.querySelector('button[data-email-btn="referral"]');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Generating PDF...'; }
  try {
    const pdfBlob = await renderHtmlToPdfBlob(cleanHtml, filename);
    if (btn) btn.textContent = '⏳ Opening share / email...';
    const result = await sharePdfBlob(pdfBlob, filename, p.email, subject, body);
    if (result.method === 'share') showToast('Referral shared via system share sheet');
    else if (result.method === 'download') showToast('PDF downloaded — attach to email & send');
    else if (result.method === 'aborted') showToast('Cancelled');
  } catch(e) {
    console.error(e);
    showToast('PDF generation failed: ' + e.message);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = '✉️📎 Email with PDF Attached'; }
  }
}

// ============================================
// AI REPORT
// ============================================
async function generateReport() {
  const btn = document.getElementById('genReportBtn');
  const spinner = document.getElementById('reportSpinner');
  btn.disabled = true; spinner.style.display = 'block';

  let summary = `Patient: ${document.getElementById('ptFirstName').value} ${document.getElementById('ptLastName').value}\n`;
  summary += `DOB: ${document.getElementById('ptDOB').value}\nVisit Date: ${document.getElementById('visitDate').value}\nVisit Type: ${APP.visitType}\n`;
  summary += `Primary Complaint: ${document.getElementById('pcRegion').value} (${document.getElementById('pcSide').value})\n`;
  summary += `Duration: ${document.getElementById('pcDuration').value}\nOnset: ${document.getElementById('pcOnset').value}\n`;
  const reportMedications = gatherMedications().filter(med => med.status !== 'Stopped / Previous');
  if (reportMedications.length) summary += `Current Medications: ${reportMedications.map(medicationDisplayText).join('; ')}\n`;
  const reportAllergies = document.getElementById('allergies').value.trim();
  if (reportAllergies) summary += `Allergies: ${reportAllergies}\n`;
  summary += '\n';

  APP.activeRegions.forEach(r => {
    const R = REGIONS[r], D = getExamData(r);
    summary += `=== ${R.name} (${D.side}) ===\nVAS: ${D.vas||'N/A'}/10\nQuality: ${(D.quality||[]).join(', ')}\nAggravating: ${(D.aggFactors||[]).join(', ')}\nRelieving: ${(D.relFactors||[]).join(', ')}\n`;
    ROMDATA.entries(r, D).forEach(e => { summary += (e.mode === 'A' ? 'Active ROM: ' : 'Passive ROM: ') + ROMDATA.text(e, true) + '\n'; });
    R.ortho.forEach(t => { if (D['ort_R_'+t] || D['ort_L_'+t]) summary += `${t}: R=${D['ort_R_'+t]||'—'} L=${D['ort_L_'+t]||'—'}\n`; });
    if (D.primaryDx) summary += `Dx: ${D.primaryDx} (${D.icd10||''})\n`;
    if (D.secondaryDx) summary += `Secondary Dx: ${D.secondaryDx} (${D.icd10_2||''})\n`;
    if (D.extCause) summary += `External Cause: ${D.extCause}\n`;
    if (D.clinicalImpression) summary += `Clinical Impression: ${D.clinicalImpression}\n`;
    if (D.txMods?.length) summary += `Modalities: ${D.txMods.join(', ')}\n`;
    if (D.biopunctureMeds?.length) summary += `Biopuncture: ${D.biopunctureMeds.join(', ')}${D.biopunctureNotes ? ' — ' + D.biopunctureNotes : ''}\n`;
    if (D.bioflexLevel) summary += `Bioflex Laser: ${D.bioflexLevel}${D.bioflexNotes ? ' — ' + D.bioflexNotes : ''}\n`;
    summary += `Post-Tx VAS: ${D.postVas||'N/A'}/10\n\n`;
  });

  // P1 v6 audit (POPIA s72 / s19): the report is built on this device only. No patient data is sent to any outside AI service.
  // Earlier builds POSTed this summary (name, DOB, medicines, allergies, exam) to an overseas AI API without a key or patient consent.
  // Turning AI drafting back on is a decision for the practitioner (operator agreement, patient consent, cross-border safeguards).
  document.getElementById('reportOutput').value = '[Draft summary made on this device — no data was sent outside the practice. Edit before use.]\n\n' + summary;
  btn.disabled = false; spinner.style.display = 'none';
}

// ============================================
// DATA GATHER / SAVE / LOAD
// ============================================
function gatherAllData() {
  return {
    version: '2.1', savedAt: new Date().toISOString(),
    practitioner: (function () { const p = loadProfile(); return [p.name, p.quals, p.prNo ? 'Pr ' + p.prNo : ''].filter(Boolean).join(', '); })(), // P1 latest v4: from the Profile
    patient: { firstName:v('ptFirstName'), lastName:v('ptLastName'), dob:v('ptDOB'), id:v('ptID'), gender:v('ptGender'), phone:v('ptPhone'), email:v('ptEmail'), medAid:v('ptMedAid'), medAidNo:v('ptMedAidNo'), fileNo:v('ptFileNo') },
    visit: { type:APP.visitType, date:v('visitDate'), caseNo:v('caseNo') },
    complaint: { region:v('pcRegion'), side:v('pcSide'), onset:v('pcOnset'), duration:v('pcDuration'), frequency:v('pcFrequency'), prevTx:v('pcPrevTx'), prevTxDate:v('pcPrevTxDate'), prevTxCount:v('pcPrevTxCount'), prevResponse:v('pcPrevResponse'), redFlags:[...document.querySelectorAll('#redFlags .chip.active')].map(c => c.dataset.val) },
    history: { conditions:[...document.querySelectorAll('#conditions .chip.active')].map(c => c.dataset.val || c.textContent.trim()), condOther:v('condOther'), allergies:v('allergies'), medications:gatherMedications(), medicationDbVersion:MEDICATION_DB_VERSION, surgHx:v('surgHx'), famHx:v('famHx'), social:{ smoking:v('shSmoking'), alcohol:v('shAlcohol'), exercise:v('shExercise'), occupation:v('shOccupation') } },
    activeRegions: APP.activeRegions, currentRegion: APP.currentRegion, examData: APP.examData, bodyMapData: APP.bodyMapData, photos: APP.photos,
    iceHeat: { modality:v('ihModality'), area:v('ihArea'), side:v('ihSide'), variant:v('ihVariant'), duration:v('ihDuration'), frequency:v('ihFreq'), custom:v('ihCustom') },
    imaging: {
      refDate: v('imgRefDate'), practice: v('imgPractice'), urgency: v('imgUrgency'), referredTo: v('imgReferredTo'),
      radPractice: v('imgRadPractice'),
      modality: v('imgModality'), region: v('imgRegion'), side: v('imgSide'), contrast: v('imgContrast'),
      views: imgGatherSelectedViews(), extCause: v('imgExtCause'),
      clinicalHx: v('imgClinicalHx'), clinicalQ: v('imgClinicalQ'), rationale: v('imgRationale'),
      pregnancy: v('imgPregnancy'), renal: v('imgRenal'), implants: v('imgImplants'), claustro: v('imgClaustro'),
      allergies: v('imgAllergies'), priorImaging: v('imgPriorImaging')
    },
    certificate: {
      consultDate: v('certConsultDate'), type: v('certType'),
      fromDate: v('certFromDate'), toDate: v('certToDate'),
      disclosure: v('certDisclosure'), diagnosis: v('certDiagnosis'),
      restrictions: v('certRestrictions'), notes: v('certNotes')
    },
    exercises: { custom:v('exCustomInstructions'), region:v('exRegion'), category:currentExCat, selected:getSelectedExercises() },
    report: v('reportOutput')
  };
}
function v(id) { return document.getElementById(id)?.value || ''; }

function saveJSON() {
  if (typeof ensureDxConfirmedForSave === 'function' && !ensureDxConfirmedForSave('saving')) return;
  const data = gatherAllData();
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = makeEzmedFilename(data, 'json');
  a.click(); URL.revokeObjectURL(a.href);
  // Also save to localStorage
  // P1 v6 audit: no 100-visit cap (it silently deleted the oldest visit); a full device keeps the downloaded file and says so.
  const visits = CCData.all(); // P1 v9: single data-access layer (same read/write as before)
  visits.push(data);
  try { CCData.writeAll(visits); showToast('Patient data saved!'); }
  catch (e) { showToast('Device storage is full — the downloaded file is the only copy of this visit. Make a practice backup.'); }
}

function loadJSON() { document.getElementById('jsonLoadInput').click(); }
function handleJSONLoad(e) {
  const file = e.target.files[0]; if (!file) return;
  const reader = new FileReader();
  reader.onload = ev => { try { restoreData(JSON.parse(ev.target.result)); showToast('Patient data loaded!'); } catch(err) { showToast('Error loading file'); } };
  reader.readAsText(file);
}

function restoreData(data) {
  if (data.patient) { ['ptFirstName','ptLastName','ptDOB','ptID','ptGender','ptPhone','ptEmail','ptMedAid','ptMedAidNo','ptFileNo'].forEach(id => { const key = id.replace('pt','').replace(/^([A-Z])/, (m,c) => c.toLowerCase()); const val = data.patient[key] || data.patient[id.replace('pt','')] || ''; if (document.getElementById(id)) document.getElementById(id).value = val; }); }
  // More direct restore
  if (data.patient) {
    const p = data.patient;
    document.getElementById('ptFirstName').value = p.firstName || '';
    document.getElementById('ptLastName').value = p.lastName || '';
    document.getElementById('ptDOB').value = p.dob || '';
    document.getElementById('ptID').value = p.id || '';
    document.getElementById('ptGender').value = p.gender || '';
    document.getElementById('ptPhone').value = p.phone || '';
    document.getElementById('ptEmail').value = p.email || '';
    document.getElementById('ptMedAid').value = p.medAid || '';
    document.getElementById('ptMedAidNo').value = p.medAidNo || '';
    document.getElementById('ptFileNo').value = p.fileNo || '';
  }
  if (data.visit) { document.getElementById('visitDate').value = data.visit.date || ''; document.getElementById('caseNo').value = data.visit.caseNo || ''; }
  if (data.complaint) {
    document.getElementById('pcRegion').value = data.complaint.region || '';
    document.getElementById('pcSide').value = data.complaint.side || '';
    document.getElementById('pcOnset').value = data.complaint.onset || '';
    document.getElementById('pcDuration').value = data.complaint.duration || '';
    document.getElementById('pcFrequency').value = data.complaint.frequency || '';
    document.getElementById('pcPrevTx').value = data.complaint.prevTx || '';
    if (data.complaint.prevTxDate) document.getElementById('pcPrevTxDate').value = data.complaint.prevTxDate;
    if (data.complaint.prevTxCount) document.getElementById('pcPrevTxCount').value = data.complaint.prevTxCount;
    if (data.complaint.prevResponse) document.getElementById('pcPrevResponse').value = data.complaint.prevResponse;
  }
  if (data.history) {
    const savedConditions = Array.isArray(data.history.conditions) ? data.history.conditions : [];
    document.querySelectorAll('#conditions .chip').forEach(chip => chip.classList.toggle('active', savedConditions.includes(chip.dataset.val || chip.textContent.trim())));
    document.getElementById('condOther').value = data.history.condOther || '';
    document.getElementById('allergies').value = data.history.allergies || '';
    restoreMedications(data.history.medications || data.history.currentMedications || []);
    document.getElementById('surgHx').value = data.history.surgHx || '';
    document.getElementById('famHx').value = data.history.famHx || '';
    if (data.history.social) {
      document.getElementById('shSmoking').value = data.history.social.smoking || 'Non-smoker';
      document.getElementById('shAlcohol').value = data.history.social.alcohol || 'None';
      document.getElementById('shExercise').value = data.history.social.exercise || 'Sedentary';
      document.getElementById('shOccupation').value = data.history.social.occupation || '';
    }
    syncMedicationSectionsFromConditions();
  }
  if (data.examData) APP.examData = data.examData;
  if (data.activeRegions) {
    APP.activeRegions = data.activeRegions.slice();
    // Focus the saved region if present, else the last region selected — never a neighbour.
    var savedFocus = (typeof resolveExamRegion === 'function') ? resolveExamRegion(data.currentRegion) : data.currentRegion;
    APP.currentRegion = (savedFocus && APP.activeRegions.indexOf(savedFocus) >= 0) ? savedFocus : (APP.activeRegions[APP.activeRegions.length - 1] || null);
    document.querySelectorAll('#examRegionSelect .chip').forEach(c => c.classList.toggle('active', APP.activeRegions.includes(c.dataset.region)));
    renderRegionTabs();
  }
  if (data.bodyMapData) APP.bodyMapData = data.bodyMapData;
  if (data.photos) { APP.photos = data.photos; renderPhotos(); }
  if (data.iceHeat) { document.getElementById('ihModality').value = data.iceHeat.modality || 'Ice'; document.getElementById('ihArea').value = data.iceHeat.area || 'Cervical'; if(document.getElementById('ihSide')) document.getElementById('ihSide').value = data.iceHeat.side || 'Left'; if(document.getElementById('ihVariant')) document.getElementById('ihVariant').value = data.iceHeat.variant || 'Posterior'; document.getElementById('ihDuration').value = data.iceHeat.duration || '15 minutes'; document.getElementById('ihFreq').value = data.iceHeat.frequency || '3x daily'; document.getElementById('ihCustom').value = data.iceHeat.custom || ''; if(typeof onIceHeatAreaChange==='function') onIceHeatAreaChange(); }
  if (data.imaging) {
    const I = data.imaging;
    document.getElementById('imgRefDate').value = I.refDate || '';
    document.getElementById('imgPractice').value = ccPracticeName(I.practice || ''); // v5: old saved label maps to the same practice
    document.getElementById('imgUrgency').value = I.urgency || 'Routine';
    document.getElementById('imgReferredTo').value = I.referredTo || '';
    if (I.radPractice) document.getElementById('imgRadPractice').value = I.radPractice;
    document.getElementById('imgModality').value = I.modality || '';
    document.getElementById('imgRegion').value = I.region || '';
    document.getElementById('imgSide').value = I.side || '';
    document.getElementById('imgContrast').value = I.contrast || 'Not required';
    document.getElementById('imgClinicalHx').value = I.clinicalHx || '';
    document.getElementById('imgClinicalQ').value = I.clinicalQ || '';
    document.getElementById('imgRationale').value = I.rationale || '';
    document.getElementById('imgPregnancy').value = I.pregnancy || 'N/A';
    document.getElementById('imgRenal').value = I.renal || '';
    document.getElementById('imgImplants').value = I.implants || '';
    document.getElementById('imgClaustro').value = I.claustro || 'No';
    document.getElementById('imgAllergies').value = I.allergies || '';
    document.getElementById('imgPriorImaging').value = I.priorImaging || '';
    if (I.extCause) {
      document.getElementById('imgExtCause').value = I.extCause;
      document.getElementById('imgExtCauseRow').style.display = 'block';
    }
    if (I.views && I.views.length) renderImgViews(I.views, true);
  }
  if (data.certificate) {
    const C = data.certificate;
    document.getElementById('certConsultDate').value = C.consultDate || '';
    document.getElementById('certType').value = C.type || 'Booked off work — full duty unfit';
    document.getElementById('certFromDate').value = C.fromDate || '';
    document.getElementById('certToDate').value = C.toDate || '';
    document.getElementById('certDisclosure').value = C.disclosure || 'generic';
    document.getElementById('certDiagnosis').value = C.diagnosis || '';
    document.getElementById('certRestrictions').value = C.restrictions || '';
    document.getElementById('certNotes').value = C.notes || '';
    certCalcDuration();
  }
  if (data.exercises) {
    document.getElementById('exCustomInstructions').value = data.exercises.custom || '';
    if (data.exercises.region) document.getElementById('exRegion').value = data.exercises.region;
    if (data.exercises.category) {
      currentExCat = data.exercises.category;
      var tabs = document.querySelectorAll('#sec-exercises .soap-tab');
      tabs.forEach(function(t) { t.classList.toggle('active', t.textContent.trim().toLowerCase().indexOf(data.exercises.category) === 0); });
    }
    renderExercises();
    if (data.exercises.selected && data.exercises.selected.length > 0) {
      var savedNames = {};
      data.exercises.selected.forEach(function(ex) { savedNames[ex.name] = ex.rx || ''; });
      var cards = document.querySelectorAll('#exerciseList .exercise-card');
      cards.forEach(function(card) {
        var cb = card.querySelector('input[type="checkbox"]');
        if (!cb) return;
        var label = cb.parentElement ? cb.parentElement.textContent.trim() : '';
        if (savedNames.hasOwnProperty(label)) {
          cb.checked = true;
          var rxInput = card.querySelector('input[placeholder]');
          if (rxInput && savedNames[label]) rxInput.value = savedNames[label];
        }
      });
    }
  }
  if (data.report) document.getElementById('reportOutput').value = data.report;
}

function loadSavedVisits() {
  const sel = document.getElementById('prevVisitSelect');
  // P1 item 8 v2: only the current patient's earlier visits (never another patient's record)
  const pid = (window.EHR && EHR.currentPatientId) || null, cur = window.EHR && EHR.currentVisitId;
  if (!pid) { sel.innerHTML = '<option value="">— Open or save a patient first —</option>'; return; }
  sel.innerHTML = '<option value="">— Select previous visit —</option>';
  (CCData.forPatientIndexed(pid) || CCData.all().map((v, i) => [v, i])) // P1 v9: this patient's candidates, with their list positions
   .filter(([v]) => v && v.patientId === pid && (v.visitId || v.id) !== cur)
    .sort((a, b) => String((b[0].visit||{}).date||'').localeCompare(String((a[0].visit||{}).date||'')))
    .forEach(([v, i]) => { sel.innerHTML += `<option value="${i}">${v.patient?.lastName||''}, ${v.patient?.firstName||''} — ${v.visit?.date||'undated'}</option>`; });
}

function loadPreviousVisit() {
  const idx = document.getElementById('prevVisitSelect').value;
  if (idx === '') { APP.previousVisit = null; return; }
  const at = CCData.at(idx); // P1 v9: read just that visit (same position as visits[idx])
  APP.previousVisit = at ? at.v : CCData.all()[idx];
  if (APP.previousVisit && (!window.EHR || APP.previousVisit.patientId !== EHR.currentPatientId)) { APP.previousVisit = null; showToast('That visit belongs to another patient'); return; }
  if (APP.p8 && APP.p8.signed) { APP.previousVisit = null; showToast('This visit is signed — use an addendum'); return; }
  if (APP.previousVisit) {
    restoreData(APP.previousVisit);
    document.getElementById('visitDate').value = localISODate();
    APP.visitType = 'followup';
    showToast('Previous visit loaded — previous values shown in blue');
  }
}

// ============================================
// FIREBASE INTEGRATION (Dynamic — loaded on demand)
// ============================================
const FIREBASE_VERSION = '9.23.0';
const FIREBASE_CDNS = [
  { name: 'gstatic',  base: 'https://www.gstatic.com/firebasejs/' + FIREBASE_VERSION },
  { name: 'jsDelivr', base: 'https://cdn.jsdelivr.net/npm/firebase@' + FIREBASE_VERSION },
  { name: 'unpkg',    base: 'https://unpkg.com/firebase@' + FIREBASE_VERSION }
];
const FIREBASE_LOAD_TIMEOUT_MS = 10000;

let firebaseReady = false;
let db = null;
let firebaseLoading = false;

// v8 CSP: true when this page carries the P1 Content-Security-Policy (only the clinic's own server may supply scripts / be contacted)
function ccCspBlocksExternal() { return !!document.querySelector('meta[http-equiv="Content-Security-Policy"]'); }

function loadScriptWithTimeout(url, timeoutMs) {
  return new Promise((resolve, reject) => {
    // v8 CSP: a script from another origin is refused by the policy; fail like an unreachable CDN without asking the browser
    try { if (ccCspBlocksExternal() && new URL(url, location.href).origin !== location.origin) { reject(new Error('Blocked by the security policy (only this clinic server may supply scripts; Firebase is off in P1): ' + url)); return; } } catch (_) {}
    const s = document.createElement('script');
    s.src = url;
    let settled = false;
    const finish = (fn, arg) => { if (settled) return; settled = true; clearTimeout(timer); fn(arg); };
    const timer = setTimeout(function() {
      finish(reject, new Error('Timeout (' + (timeoutMs/1000) + 's): ' + url));
    }, timeoutMs);
    s.onload  = () => finish(resolve);
    s.onerror = () => finish(reject, new Error('Network/load error: ' + url));
    document.head.appendChild(s);
  });
}

function loadFirebaseSDK() {
  return new Promise(async (resolve, reject) => {
    if (typeof firebase !== 'undefined' && firebase.apps) { resolve(); return; }
    if (firebaseLoading) {
      // Wait for an in-progress load (max 30s)
      let waited = 0;
      const check = setInterval(() => {
        waited += 200;
        if (typeof firebase !== 'undefined' && firebase.apps) { clearInterval(check); resolve(); }
        else if (waited > 30000) { clearInterval(check); reject(new Error('Timed out waiting for in-progress Firebase load')); }
      }, 200);
      return;
    }
    firebaseLoading = true;

    const errors = [];
    for (const cdn of FIREBASE_CDNS) {
      try {
        console.log('[Firebase] Trying CDN: ' + cdn.name + ' (' + cdn.base + ')');
        await loadScriptWithTimeout(cdn.base + '/firebase-app-compat.js',      FIREBASE_LOAD_TIMEOUT_MS);
        await loadScriptWithTimeout(cdn.base + '/firebase-database-compat.js', FIREBASE_LOAD_TIMEOUT_MS);
        await loadScriptWithTimeout(cdn.base + '/firebase-auth-compat.js',     FIREBASE_LOAD_TIMEOUT_MS);
        console.log('[Firebase] SDK loaded from ' + cdn.name);
        firebaseLoading = false;
        resolve();
        return;
      } catch (e) {
        console.warn('[Firebase] CDN ' + cdn.name + ' failed: ' + e.message);
        errors.push(cdn.name + ' \u2192 ' + e.message);
      }
    }

    firebaseLoading = false;
    reject(new Error('Firebase SDK unreachable from all CDNs:\n  ' + errors.join('\n  ')));
  });
}

async function initFirebase() {
  const configStr = localStorage.getItem('chiroclinic_fb_config');
  if (!configStr) return;

  // Fast-fail if browser reports offline — avoids the noisy SDK-load error
  if (typeof navigator !== 'undefined' && navigator.onLine === false) {
    console.log('[Firebase] Browser reports offline \u2014 cloud sync paused');
    updateCloudStatus(false);
    return;
  }

  try {
    await loadFirebaseSDK();
    const config = JSON.parse(configStr);
    if (!firebase.apps.length) firebase.initializeApp(config);
    // Anonymous sign-in — required because security rules need auth != null
    if (firebase.auth) {
      try {
        await firebase.auth().signInAnonymously();
      } catch(authErr) {
        console.error('[Firebase] Anonymous auth failed:', authErr);
        let msg;
        switch (authErr && authErr.code) {
          case 'auth/network-request-failed':
            msg = 'Auth API blocked \u2014 disable content blocker for *.googleapis.com';
            break;
          case 'auth/operation-not-allowed':
            msg = 'Enable Anonymous auth in Firebase console';
            break;
          case 'auth/invalid-api-key':
          case 'auth/app-deleted':
            msg = 'Invalid Firebase config \u2014 re-paste from console';
            break;
          default:
            msg = 'Auth failed: ' + (authErr.code || authErr.message || 'unknown');
        }
        showToast(msg);
        updateCloudStatus(false);
        return;
      }
    }
    db = firebase.database();
    firebaseReady = true;
    updateCloudStatus(true);
    listenForIntake();
    refreshPatientIndex();
    startAutoSave();
    showToast('Cloud connected!');
  } catch(e) {
    console.error('[Firebase] Init failed:', e.message || e);
    showToast('Cloud unavailable \u2014 see console (\u2699\ufe0f Cloud setup has Retry button)');
    updateCloudStatus(false);
  }
}

async function retryFirebase() {
  const status = document.getElementById('fbStatus');
  if (status) status.innerHTML = '<span style="color:var(--text2)">Retrying\u2026</span>';
  // Reset state so loadFirebaseSDK re-attempts cleanly
  firebaseReady = false;
  firebaseLoading = false;
  db = null;
  await initFirebase();
  if (status) {
    status.innerHTML = firebaseReady
      ? '<span style="color:var(--green)">\u2713 Connected</span>'
      : '<span style="color:var(--red)">Still unreachable \u2014 check browser console for details</span>';
  }
}

async function diagnoseFirebaseNetwork() {
  const status = document.getElementById('fbStatus');
  // v8 CSP: the policy only allows this clinic server, so every external probe would fail and mislead the diagnosis
  if (ccCspBlocksExternal()) { status.innerHTML = '<div style="font-size:12px;text-align:left;background:var(--surface3);padding:10px;border-radius:6px;margin-top:4px"><b>Diagnosis:</b> cloud sync (Firebase) is switched off in this build. Its security policy only lets the app talk to this clinic\u2019s own server, so Google/Firebase endpoints are not contacted. Records stay on this device and the clinic Mac.</div>'; return; }
  status.innerHTML = '<span style="color:var(--text2)">Probing endpoints\u2026</span>';

  const tests = [
    { name: 'jsDelivr CDN (control)', url: 'https://cdn.jsdelivr.net/npm/firebase@9.23.0/package.json', critical: false },
    { name: 'Google CDN (gstatic)',   url: 'https://www.gstatic.com/firebasejs/9.23.0/firebase-app-compat.js', critical: false },
    { name: 'Auth API (googleapis)',  url: 'https://identitytoolkit.googleapis.com/', critical: true }
  ];

  // Add the user's specific Realtime Database host if config is saved
  try {
    const cfg = JSON.parse(localStorage.getItem('chiroclinic_fb_config') || '{}');
    if (cfg.databaseURL) {
      tests.push({ name: 'Realtime Database', url: cfg.databaseURL.replace(/\/$/, '') + '/.json?shallow=true', critical: true });
    }
  } catch(_) {}

  async function probe(t) {
    return new Promise(function(resolve) {
      var settled = false;
      var tmr = setTimeout(function() {
        if (settled) return;
        settled = true;
        resolve(Object.assign({}, t, { ok: false, error: 'timeout (8s)' }));
      }, 8000);
      fetch(t.url, { mode: 'no-cors', cache: 'no-store' })
        .then(function() {
          if (settled) return;
          settled = true; clearTimeout(tmr);
          resolve(Object.assign({}, t, { ok: true }));
        })
        .catch(function(e) {
          if (settled) return;
          settled = true; clearTimeout(tmr);
          resolve(Object.assign({}, t, { ok: false, error: (e && e.message) || 'blocked' }));
        });
    });
  }

  const results = await Promise.all(tests.map(probe));
  console.log('[Firebase] Diagnostic results:', results);

  let html = '<div style="font-size:12px;text-align:left;background:var(--surface3);padding:10px;border-radius:6px;margin-top:4px">';
  html += '<div style="font-weight:600;margin-bottom:6px">Endpoint reachability</div>';
  results.forEach(r => {
    const icon = r.ok ? '\u2713' : '\u2717';
    const color = r.ok ? 'var(--green)' : 'var(--red)';
    html += '<div style="margin:4px 0;line-height:1.4"><span style="color:' + color + ';font-weight:700;display:inline-block;width:14px">' + icon + '</span> ' + r.name;
    if (!r.ok) html += ' <span style="color:var(--text3);font-size:11px">(' + r.error + ')</span>';
    html += '</div>';
  });

  // Smart summary
  const criticalBlocked = results.filter(r => r.critical && !r.ok);
  const controlOk = results.find(r => r.name.indexOf('control') !== -1 && r.ok);
  html += '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border);font-size:11px">';
  if (controlOk && criticalBlocked.length === results.filter(r => r.critical).length) {
    html += '<b>Diagnosis:</b> internet works (control passed) but every Google/Firebase endpoint is blocked. This is your ad blocker or privacy extension. Whitelist <code>*.googleapis.com</code> and your database host, then click Retry.';
  } else if (controlOk && criticalBlocked.length > 0) {
    html += '<b>Diagnosis:</b> partial blocking. Whitelist the failed endpoint(s) above in your ad blocker.';
  } else if (!controlOk) {
    html += '<b>Diagnosis:</b> general network issue \u2014 even the control failed. Check WiFi / VPN / system firewall.';
  } else {
    html += '<b>Diagnosis:</b> all endpoints reachable. Click Retry Connection \u2014 should work now.';
  }
  html += '</div></div>';
  status.innerHTML = html;
}

async function saveFirebaseConfig() {
  const raw = document.getElementById('firebaseConfigInput').value.trim();
  try {
    const config = JSON.parse(raw);
    if (!config.databaseURL) {
      document.getElementById('fbStatus').innerHTML = '<span style="color:var(--red)">Missing databaseURL in config</span>';
      return;
    }
    localStorage.setItem('chiroclinic_fb_config', JSON.stringify(config));
    document.getElementById('fbStatus').innerHTML = '<span style="color:var(--yellow)">Connecting...</span>';
    await initFirebase();
    document.getElementById('fbStatus').innerHTML = '<span style="color:var(--green)">✓ Config saved & connected!</span>';
  } catch(e) {
    document.getElementById('fbStatus').innerHTML = '<span style="color:var(--red)">Invalid JSON — paste the full config object from Firebase Console</span>';
  }
}

async function testFirebase() {
  if (!firebaseReady) {
    document.getElementById('fbStatus').innerHTML = '<span style="color:var(--red)">Save config first</span>';
    return;
  }
  try {
    const snap = await db.ref('.info/connected').once('value');
    document.getElementById('fbStatus').innerHTML = snap.val()
      ? '<span style="color:var(--green)">✓ Connected to Firebase!</span>'
      : '<span style="color:var(--yellow)">⚠ Saved but not yet connected — check config</span>';
  } catch(e) {
    document.getElementById('fbStatus').innerHTML = '<span style="color:var(--red)">Connection error: ' + e.message + '</span>';
  }
}

function updateCloudStatus(connected) {
  const el = document.getElementById('cloudStatus');
  if (connected) { el.className = 'cloud-status synced'; el.innerHTML = '<span class="dot"></span> Cloud'; }
  else { el.className = 'cloud-status local'; el.innerHTML = '<span class="dot"></span> Local'; }
}

function showCloudModal() {
  document.getElementById('cloudModal').classList.add('show');
  if (firebaseReady) loadPendingIntakeForms();
}

// ============================================
// INTAKE FORM INTEGRATION
// ============================================
function listenForIntake() {
  if (!firebaseReady || !db) return;
  db.ref('intakeForms').orderByChild('status').equalTo('pending').on('child_added', snap => {
    const data = snap.val();
    if (data) {
      // Show notification
      const notif = document.getElementById('intakeNotification');
      notif.style.display = 'block';
      notif.textContent = '📥 New intake: ' + (data.patient?.lastName || 'Unknown') + ', ' + (data.patient?.firstName || '');
      setTimeout(() => { notif.style.display = 'none'; }, 8000);
      // Refresh intake list if modal is open
      if (document.getElementById('cloudModal').classList.contains('show')) {
        loadPendingIntakeForms();
      }
    }
  });
}

async function loadPendingIntakeForms() {
  if (!firebaseReady || !db) {
    document.getElementById('intakeList').innerHTML = '<p style="font-size:11px;color:var(--text3)">Connect to Firebase first</p>';
    return;
  }
  try {
    const snap = await db.ref('intakeForms').orderByChild('status').equalTo('pending').once('value');
    const container = document.getElementById('intakeList');
    container.innerHTML = '';
    if (!snap.exists()) {
      container.innerHTML = '<p style="font-size:11px;color:var(--text3)">No pending intake forms</p>';
      return;
    }
    snap.forEach(child => {
      const d = child.val();
      const key = child.key;
      const name = (d.patient?.lastName || '?') + ', ' + (d.patient?.firstName || '?');
      const date = d.submittedAt ? new Date(d.submittedAt).toLocaleDateString() : 'Unknown date';
      const div = document.createElement('div');
      div.style.cssText = 'display:flex;justify-content:space-between;align-items:center;padding:8px;background:var(--surface2);border-radius:8px;margin-bottom:6px';
      div.innerHTML = `
        <div>
          <div style="font-weight:600;font-size:13px">${name}</div>
          <div style="font-size:11px;color:var(--text3)">${date}</div>
        </div>
        <div style="display:flex;gap:4px">
          <button data-cc-click="importIntakeForm('${key}')" style="background:var(--accent);color:#fff;padding:6px 12px;border-radius:6px;font-size:11px">Import</button>
          <button data-cc-click="dismissIntakeForm('${key}')" style="background:var(--red-dim);color:var(--red);padding:6px 8px;border-radius:6px;font-size:11px">✕</button>
        </div>
      `;
      container.appendChild(div);
    });
  } catch(e) {
    document.getElementById('intakeList').innerHTML = '<p style="font-size:11px;color:var(--red)">Error loading intakes: ' + e.message + '</p>';
  }
}

async function importIntakeForm(key) {
  if (!firebaseReady || !db) return;
  try {
    const snap = await db.ref('intakeForms/' + key).once('value');
    const intakeData = snap.val();
    if (!intakeData) { showToast('Intake form not found'); return; }

    // Map intake data to ChiroClinic format and restore
    const mapped = mapIntakeToExam(intakeData);
    restoreData(mapped);

    // Mark as imported in Firebase
    await db.ref('intakeForms/' + key).update({ status: 'imported', importedAt: new Date().toISOString() });

    // Close modal and show toast
    document.getElementById('cloudModal').classList.remove('show');
    showToast('Patient intake imported — ' + (intakeData.patient?.firstName || '') + ' ' + (intakeData.patient?.lastName || ''));

    // Refresh intake list
    loadPendingIntakeForms();
  } catch(e) {
    showToast('Import failed: ' + e.message);
  }
}

async function dismissIntakeForm(key) {
  if (!firebaseReady || !db) return;
  if (!confirm('Dismiss this intake form?')) return;
  try {
    await db.ref('intakeForms/' + key).update({ status: 'dismissed', dismissedAt: new Date().toISOString() });
    showToast('Intake dismissed');
    loadPendingIntakeForms();
  } catch(e) {
    showToast('Error: ' + e.message);
  }
}

function mapIntakeToExam(intake) {
  // Map from intake form format to ChiroClinic exam format
  const result = {
    patient: intake.patient || {},
    visit: { type: 'new', date: localISODate(), caseNo: '' },
    complaint: intake.complaint || {},
    history: intake.history || {},
    activeRegions: [],
    examData: {},
    bodyMapData: intake.bodyMapData || null,
    photos: intake.documents || [],
    iceHeat: {},
    exercises: {},
    report: ''
  };

  // Auto-activate exam regions based on complaint
  if (intake.complaint?.region) {
    const regionMap = {
      'Cervical Spine': 'cs', 'Thoracic Spine': 'ts', 'Lumbar Spine': 'ls',
      'Pelvis/SI': 'pelvis', 'Hip': 'hip', 'Shoulder': 'shoulder', 'Elbow': 'elbow',
      'Wrist/Fingers': 'wrist', 'Knee': 'knee', 'Ankle/Foot': 'ankle'
    };
    const r = regionMap[intake.complaint.region];
    if (r) result.activeRegions.push(r);
  }

  // Map affected regions from intake
  if (intake.complaint?.affectedRegions && Array.isArray(intake.complaint.affectedRegions)) {
    const regionMap = {
      'cervical': 'cs', 'thoracic': 'ts', 'lumbar': 'ls',
      'pelvis': 'pelvis', 'hip': 'hip', 'shoulder': 'shoulder', 'elbow': 'elbow',
      'wrist': 'wrist', 'knee': 'knee', 'ankle': 'ankle'
    };
    intake.complaint.affectedRegions.forEach(ar => {
      const r = regionMap[ar];
      if (r && !result.activeRegions.includes(r)) result.activeRegions.push(r);
    });
  }

  return result;
}

// ============================================
// PATIENT-KEYED CLOUD STORAGE
// ============================================
function getPatientKey(data) {
  // Prefer SA ID number, fall back to file number. This is THE key that must match ezmed.
  var id = (data.patient && (data.patient.id || data.patient.fileNo)) || '';
  return String(id).replace(/[^a-zA-Z0-9_-]/g, '').trim();
}

function getVisitId(data) {
  var d = (data.visit && data.visit.date) || localISODate();
  var type = (data.visit && data.visit.type) || 'new';
  // include seconds so same-day multiple visits don't collide
  var stamp = new Date().toISOString().replace(/[:.]/g, '-').substring(0, 19);
  return d + '_' + type + '_' + stamp;
}

// In-memory index of known patients for search autocomplete
var PATIENT_INDEX = {};

async function refreshPatientIndex() {
  if (!firebaseReady || !db) return;
  try {
    var snap = await db.ref('patients').once('value');
    PATIENT_INDEX = snap.val() || {};
  } catch(e) {
    console.error('Patient index refresh failed:', e);
  }
}

async function savePatientToCloud(data) {
  if (!firebaseReady || !db) return false;
  var key = getPatientKey(data);
  if (!key) return false;
  var visitId = getVisitId(data);
  try {
    // Save/update profile (demographics only — keep light)
    await db.ref('patients/' + key + '/profile').set({
      firstName: data.patient.firstName || '',
      lastName: data.patient.lastName || '',
      id: data.patient.id || '',
      fileNo: data.patient.fileNo || '',
      dob: data.patient.dob || '',
      gender: data.patient.gender || '',
      phone: data.patient.phone || '',
      email: data.patient.email || '',
      medAid: data.patient.medAid || '',
      medAidNo: data.patient.medAidNo || '',
      medications: (data.history && data.history.medications) || [],
      medicationDbVersion: (data.history && data.history.medicationDbVersion) || MEDICATION_DB_VERSION,
      lastSeen: data.visit.date || localISODate(),
      lastUpdated: new Date().toISOString()
    });
    // Save full visit under that patient
    await db.ref('patients/' + key + '/visits/' + visitId.replace(/[^a-zA-Z0-9_-]/g,'_')).set(data);
    // Update the in-memory index silently
    PATIENT_INDEX[key] = PATIENT_INDEX[key] || { profile: {}, visits: {} };
    PATIENT_INDEX[key].profile = { firstName: data.patient.firstName, lastName: data.patient.lastName, id: data.patient.id, fileNo: data.patient.fileNo, lastSeen: data.visit.date };
    return true;
  } catch(e) {
    console.error('Cloud save failed:', e);
    return false;
  }
}

async function loadPatientFromCloud(key) {
  if (!firebaseReady || !db) return null;
  try {
    var snap = await db.ref('patients/' + key).once('value');
    return snap.val();
  } catch(e) {
    console.error('Cloud load failed:', e);
    return null;
  }
}

// ============================================
// PATIENT SEARCH
// ============================================
function patientSearchInput() {
  var q = (document.getElementById('patientSearch').value || '').trim().toLowerCase();
  var resultsEl = document.getElementById('patientSearchResults');
  if (!q || q.length < 2) { resultsEl.style.display = 'none'; return; }
  if (!firebaseReady) {
    resultsEl.innerHTML = '<div style="padding:10px;font-size:12px;color:var(--text3)">Cloud not connected. Use ☁️ button to configure.</div>';
    resultsEl.style.display = 'block';
    return;
  }
  var matches = [];
  Object.keys(PATIENT_INDEX).forEach(function(key) {
    var p = (PATIENT_INDEX[key] && PATIENT_INDEX[key].profile) || {};
    var hay = ((p.firstName || '') + ' ' + (p.lastName || '') + ' ' + (p.id || '') + ' ' + (p.fileNo || '')).toLowerCase();
    if (hay.indexOf(q) >= 0) matches.push({ key: key, profile: p });
  });
  matches.sort(function(a,b) { return (a.profile.lastName || '').localeCompare(b.profile.lastName || ''); });
  if (matches.length === 0) {
    resultsEl.innerHTML = '<div style="padding:10px;font-size:12px;color:var(--text3)">No match. Complete the form below to add as new patient.</div>';
  } else {
    resultsEl.innerHTML = matches.slice(0, 20).map(function(m) {
      var p = ccEscObj(m.profile); // P1 v6 audit: cloud profile text escaped
      var name = ((p.lastName || '?') + ', ' + (p.firstName || '?'));
      var sub = 'ID ' + (p.id || '-') + (p.fileNo ? ' | File ' + p.fileNo : '') + (p.lastSeen ? ' | Last: ' + p.lastSeen : '');
      return "<div style=\"padding:10px;border-bottom:1px solid var(--border);cursor:pointer\" data-cc-click=\"loadPatientByKey(" + ccH(JSON.stringify(String(m.key))) + ")\" data-cc-mouseover=\"this.style.background='#F3F4F6'\" data-cc-mouseout=\"this.style.background='#fff'\"><div style=\"font-weight:600;color:var(--text)\">" + name + '</div><div style="font-size:10px;color:var(--text3);margin-top:2px">' + sub + '</div></div>';
    }).join('');
  }
  resultsEl.style.display = 'block';
}

async function loadPatientByKey(key) {
  document.getElementById('patientSearchResults').style.display = 'none';
  document.getElementById('patientSearch').value = '';
  var record = await loadPatientFromCloud(key);
  if (!record) { showToast('Could not load patient'); return; }
  // Populate patient fields from profile
  var p = record.profile || {};
  document.getElementById('ptFirstName').value = p.firstName || '';
  document.getElementById('ptLastName').value = p.lastName || '';
  document.getElementById('ptDOB').value = p.dob || '';
  document.getElementById('ptID').value = p.id || '';
  document.getElementById('ptGender').value = p.gender || '';
  document.getElementById('ptPhone').value = p.phone || '';
  document.getElementById('ptEmail').value = p.email || '';
  document.getElementById('ptMedAid').value = p.medAid || '';
  document.getElementById('ptMedAidNo').value = p.medAidNo || '';
  document.getElementById('ptFileNo').value = p.fileNo || '';
  // Render visit summary — last 5 visits sorted most recent first
  var visits = record.visits ? Object.keys(record.visits).map(function(k){ return record.visits[k]; }) : [];
  visits.sort(function(a,b){ return String(b.visit?.date || '').localeCompare(String(a.visit?.date || '')); });
  var latestVisitMeds = visits.length && visits[0].history ? (visits[0].history.medications || []) : [];
  restoreMedications(p.medications || latestVisitMeds);
  renderPrevVisitSummary(visits);
  // Auto-flip to follow-up if there are previous visits
  if (visits.length > 0) {
    var followupChip = document.querySelectorAll('.chip-group .chip')[1];
    if (followupChip) setVisitType('followup', followupChip);
  }
  // Set today's date
  document.getElementById('visitDate').value = localISODate();
  APP.previousVisit = visits[0] || null;
  showToast('Loaded ' + (p.firstName || '') + ' ' + (p.lastName || '') + ' - ' + visits.length + ' previous visit(s)');
}

function renderPrevVisitSummary(visits) {
  var card = document.getElementById('prevVisitSummary');
  var content = document.getElementById('prevVisitSummaryContent');
  if (!visits || visits.length === 0) { card.style.display = 'none'; return; }
  var rows = visits.slice(0, 5).map(function(v, i) {
    var d = v.visit?.date || '-';
    var t = v.visit?.type === 'followup' ? 'Follow-up' : 'New';
    var region = v.complaint?.region || '-';
    var side = v.complaint?.side ? ' (' + v.complaint.side + ')' : '';
    var vas = '-';
    if (v.activeRegions && v.activeRegions.length && v.examData) {
      var r0 = v.activeRegions[0];
      if (v.examData[r0] && v.examData[r0].vas != null) vas = v.examData[r0].vas + '/10';
    }
    var dx = '-';
    if (v.activeRegions && v.activeRegions.length && v.examData) {
      var r0 = v.activeRegions[0];
      if (v.examData[r0] && v.examData[r0].primaryDx) dx = v.examData[r0].primaryDx;
      if (dx.length > 50) dx = dx.substring(0, 48) + '...';
    }
    return '<div style="padding:8px;border-bottom:1px solid #BFDBFE' + (i === visits.length - 1 ? ';border-bottom:none' : '') + '">'
      + '<div style="display:flex;justify-content:space-between;font-weight:600;color:#1E3A8A">'
      + '<span>' + d + ' - ' + t + '</span><span>VAS ' + vas + '</span></div>'
      + '<div style="color:#1E40AF;margin-top:2px">' + region + side + '</div>'
      + '<div style="color:#3B82F6;font-size:11px;margin-top:2px">' + dx + '</div>'
      + '</div>';
  }).join('');
  content.innerHTML = rows + (visits.length > 5 ? '<div style="padding:6px;font-size:11px;color:var(--text3);text-align:center">+ ' + (visits.length - 5) + ' older visit(s) on record</div>' : '');
  card.style.display = 'block';
}

// Close search results when clicking elsewhere
document.addEventListener('click', function(e) {
  var card = document.getElementById('patientSearchCard');
  if (card && !card.contains(e.target)) {
    var results = document.getElementById('patientSearchResults');
    if (results) results.style.display = 'none';
  }
});

// Cloud save — also push to Firebase when saving (now per-patient)
const _originalSaveJSON = saveJSON;
saveJSON = function() {
  _originalSaveJSON();
  if (firebaseReady && db) {
    const data = gatherAllData();
    savePatientToCloud(data).then(function(ok) {
      if (ok) showToast('Also saved to cloud!');
    });
  }
};

// ============================================
// AUTO-SAVE (every 30 seconds while editing)
// ============================================
var autoSaveTimer = null;
var lastAutoSaveHash = '';
function simpleHash(s) { var h = 0; for (var i = 0; i < s.length; i++) h = ((h << 5) - h) + s.charCodeAt(i) | 0; return h; }
async function autoSave() {
  if (!firebaseReady || !db) return;
  try {
    var data = gatherAllData();
    var key = getPatientKey(data);
    if (!key) return; // no identifier yet — don't save
    if (!data.patient.firstName && !data.patient.lastName) return;
    var snapshot = JSON.stringify({ p: data.patient, v: data.visit, c: data.complaint, h: data.history, e: data.examData });
    var h = simpleHash(snapshot);
    if (h === lastAutoSaveHash) return; // no changes
    lastAutoSaveHash = h;
    await savePatientToCloud(data);
    // Silent — no toast for auto-saves to avoid noise
    var statusEl = document.getElementById('cloudStatus');
    if (statusEl) {
      var orig = statusEl.innerHTML;
      statusEl.innerHTML = '<span class="dot"></span> Saved ' + new Date().toLocaleTimeString('en-ZA', {hour:'2-digit',minute:'2-digit'});
      setTimeout(function(){ statusEl.innerHTML = orig; }, 3000);
    }
  } catch(e) { console.error('Auto-save error:', e); }
}
function startAutoSave() {
  if (autoSaveTimer) clearInterval(autoSaveTimer);
  autoSaveTimer = setInterval(autoSave, 30000);
}


// ============================================
// PDF EXPORT
// ============================================
// ============================================
// EZMED FILENAME + PDF HELPERS
// ============================================
function sanitizeFilenamePart(s) {
  return String(s || '')
    .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9-]+/g, '_').replace(/^_+|_+$/g, '').replace(/_+/g, '_');
}
function makeEzmedFilename(data, ext) {
  var surname = sanitizeFilenamePart(data.patient.lastName) || 'NoSurname';
  var firstName = sanitizeFilenamePart(data.patient.firstName) || 'NoFirstName';
  var idNr = sanitizeFilenamePart(data.patient.id) || sanitizeFilenamePart(data.patient.fileNo) || 'NoID';
  var type = data.visit.type === 'followup' ? 'Followup' : 'New';
  var date = sanitizeFilenamePart(data.visit.date) || localISODate();
  return [surname, firstName, idNr, type, date].join('_') + (ext ? '.' + ext : '');
}
function validatePatientForExport(data) {
  var errs = [];
  if (!data.patient.firstName && !data.patient.lastName) errs.push('patient name');
  if (!data.patient.id && !data.patient.fileNo) errs.push('ID number or file number');
  return errs;
}
// Transliterate UTF-8 to WinAnsi-safe latin-1 for PDF text
function toLatin1(s) {
  return String(s == null ? '' : s)
    .replace(/[\u2010-\u2015]/g, '-')
    .replace(/[\u2018\u2019\u201A\u201B]/g, "'")
    .replace(/[\u201C\u201D\u201E\u201F]/g, '"')
    .replace(/\u2026/g, '...').replace(/\u2022/g, '-').replace(/\u00A0/g, ' ')
    .replace(/[^\x00-\xFF]/g, '?');
}

// ============================================
// BUILD EXAM PDF (byte-level, no print dialog)
// ============================================
function buildExamPDF(data) {
  var PP = ccPdfProf(); // P1 latest v4: Profile values, not hard-coded
  var pw = 595.28, ph = 841.89;
  var ml = 40, mr = 40, mb = 40;
  var tw = pw - ml - mr;
  var headerH = 80;
  var footerYDefault = ph - 25;
  var streams = [], s = '', y = 0, pageNum = 1;
  var LHP = lhRawPdf(pw, ph);

  function rgb(r,g,b) { return (r/255).toFixed(3)+' '+(g/255).toFixed(3)+' '+(b/255).toFixed(3); }
  function esc(t) { return toLatin1(t).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)'); }
  function rect(x,yTop,w,h,r,g,b) { s += rgb(r,g,b)+' rg '+x.toFixed(2)+' '+(ph-yTop-h).toFixed(2)+' '+w.toFixed(2)+' '+h.toFixed(2)+' re f\n'; }
  function strokeRect(x,yTop,w,h,r,g,b,lw) { lw = lw || 0.5; s += rgb(r,g,b)+' RG '+lw+' w '+x.toFixed(2)+' '+(ph-yTop-h).toFixed(2)+' '+w.toFixed(2)+' '+h.toFixed(2)+' re S\n'; }
  function line(x1,y1,x2,y2,r,g,b,lw) { lw = lw || 0.5; s += rgb(r,g,b)+' RG '+lw+' w '+x1.toFixed(2)+' '+(ph-y1).toFixed(2)+' m '+x2.toFixed(2)+' '+(ph-y2).toFixed(2)+' l S\n'; }
  function txt(str,x,yTop,size,r,g,b,font) {
    font = font || 'F1';
    s += 'BT\n/'+font+' '+size+' Tf\n'+rgb(r,g,b)+' rg\n'+x.toFixed(2)+' '+(ph-yTop).toFixed(2)+' Td\n('+esc(str)+') Tj\nET\n';
  }
  function wrapLines(text, maxW, size) {
    var charW = size * 0.50;
    var maxChars = Math.max(10, Math.floor(maxW / charW));
    var result = [], paragraphs = String(text == null ? '' : text).split('\n');
    for (var p = 0; p < paragraphs.length; p++) {
      var para = paragraphs[p];
      if (para.length === 0) { result.push(''); continue; }
      while (para.length > 0) {
        if (para.length <= maxChars) { result.push(para); break; }
        var cut = para.lastIndexOf(' ', maxChars);
        if (cut <= 0) cut = maxChars;
        result.push(para.substring(0, cut));
        para = para.substring(cut).replace(/^\s/,'');
      }
    }
    return result;
  }
  function drawHeader() {
    if (LHP.custom) { s += LHP.pageOps(pageNum === 1); return; }
    rect(0, 0, pw, headerH, 43, 95, 92);
    rect(0, headerH, pw, 3, 201, 149, 107);
    txt(PP.name, ml, 24, 13, 255, 255, 255, 'F2');
    txt(PP.quals + '  |  Practice Nr: ' + PP.prNo, ml, 39, 8, 220, 235, 235, 'F1');
    txt([PP.m, PP.v].map(function (x) { return x.name + (x.phone ? ' ' + x.phone : ''); }).join('   |   '), ml, 54, 8, 210, 225, 225, 'F1');
    txt('Patient Clinical Record', pw - mr - 120, 28, 11, 255, 255, 255, 'F2');
  }
  function drawFooter(pn) {
    var footerY = LHP.custom ? LHP.footTextY : footerYDefault;
    line(ml, footerY - 8, pw - mr, footerY - 8, 224, 220, 215, 0.5);
    var pLine = (data.patient.lastName || '') + ', ' + (data.patient.firstName || '') + '  |  ID: ' + (data.patient.id || data.patient.fileNo || '-');
    txt(pLine, ml, footerY, 7, 138, 138, 138, 'F3');
    txt('Page ' + pn, pw/2 - 12, footerY, 7, 138, 138, 138, 'F3');
    txt('Generated ' + new Date().toLocaleDateString('en-ZA'), pw - mr - 95, footerY, 7, 138, 138, 138, 'F3');
  }
  function newPage() { drawFooter(pageNum); streams.push(s); s = ''; pageNum++; drawHeader(); y = LHP.custom ? (pageNum === 1 ? LHP.top : LHP.contTop) : headerH + 20; }
  function ensureSpace(n) { if (y + n > LHP.limit(ph - mb - 20)) newPage(); }
  function heading(text) {
    ensureSpace(24); y += 6;
    txt(text, ml, y, 11, 43, 95, 92, 'F2'); y += 3;
    line(ml, y, pw - mr, y, 43, 95, 92, 0.8); y += 11;
  }
  function subheading(text) { ensureSpace(15); y += 4; txt(text, ml, y, 9, 90, 90, 90, 'F2'); y += 12; }
  function kvRow(pairs) {
    var colW = tw / 2;
    for (var i = 0; i < pairs.length; i += 2) {
      ensureSpace(14);
      var left = pairs[i], right = pairs[i+1];
      txt(left[0] + ':', ml, y, 8, 90, 90, 90, 'F2');
      txt(String(left[1] || '-'), ml + 72, y, 9, 45, 45, 45, 'F1');
      if (right) {
        txt(right[0] + ':', ml + colW, y, 8, 90, 90, 90, 'F2');
        txt(String(right[1] || '-'), ml + colW + 72, y, 9, 45, 45, 45, 'F1');
      }
      y += 13;
    }
  }
  function kvBlock(pairs) {
    for (var i = 0; i < pairs.length; i++) {
      var label = pairs[i][0], val = pairs[i][1];
      if (val === '' || val == null) continue;
      ensureSpace(14);
      txt(label + ':', ml, y, 8, 90, 90, 90, 'F2');
      var lines = wrapLines(val, tw - 90, 9);
      for (var j = 0; j < lines.length; j++) {
        if (j > 0) ensureSpace(12);
        txt(lines[j], j === 0 ? ml + 90 : ml, y, 9, 45, 45, 45, 'F1');
        y += 12;
      }
      y += 2;
    }
  }
  function paragraph(text) {
    var lines = wrapLines(text, tw, 9);
    for (var i = 0; i < lines.length; i++) {
      ensureSpace(12);
      txt(lines[i], ml, y, 9, 45, 45, 45, 'F1');
      y += 12;
    }
    y += 4;
  }
  function table(headers, rows, colWidths) {
    var rowH = 14, headH = 14;
    ensureSpace(headH + rowH);
    rect(ml, y, tw, headH, 240, 240, 240);
    var cx = ml;
    for (var c = 0; c < headers.length; c++) {
      txt(headers[c], cx + 4, y + 9, 8, 43, 95, 92, 'F2');
      cx += colWidths[c];
    }
    strokeRect(ml, y, tw, headH, 180, 180, 180, 0.5);
    y += headH;
    for (var r = 0; r < rows.length; r++) {
      ensureSpace(rowH);
      if (r % 2 === 1) rect(ml, y, tw, rowH, 249, 249, 249);
      cx = ml;
      for (var c2 = 0; c2 < headers.length; c2++) {
        var val = rows[r][c2];
        val = (val === undefined || val === null || val === '') ? '-' : String(val);
        var maxCh = Math.max(6, Math.floor((colWidths[c2] - 8) / 4.5));
        if (val.length > maxCh) val = val.substring(0, maxCh - 1) + '.';
        txt(val, cx + 4, y + 9, 8, 45, 45, 45, 'F1');
        cx += colWidths[c2];
      }
      strokeRect(ml, y, tw, rowH, 220, 220, 220, 0.3);
      y += rowH;
    }
    y += 4;
  }

  // ============ CONTENT ============
  drawHeader();
  y = LHP.custom ? (pageNum === 1 ? LHP.top : LHP.contTop) : headerH + 20;

  // Patient Information
  heading('Patient Information');
  var fullName = ((data.patient.firstName || '') + ' ' + (data.patient.lastName || '')).trim() || '-';
  kvRow([
    ['Name', fullName], ['DOB', data.patient.dob],
    ['ID Number', data.patient.id], ['File Number', data.patient.fileNo],
    ['Phone', data.patient.phone], ['Gender', data.patient.gender]
  ]);
  if (data.patient.email) kvBlock([['Email', data.patient.email]]);
  if (data.patient.medAid || data.patient.medAidNo) {
    kvBlock([['Medical Aid', (data.patient.medAid || '-') + (data.patient.medAidNo ? '  #' + data.patient.medAidNo : '')]]);
  }

  // Visit Details
  heading('Visit Details');
  var typeLabel = data.visit.type === 'followup' ? 'Follow-up' : 'New Visit';
  kvRow([
    ['Visit Date', data.visit.date], ['Visit Type', typeLabel],
    ['Case #', data.visit.caseNo], ['Region', (data.complaint.region || '') + (data.complaint.side ? ' (' + data.complaint.side + ')' : '')],
    ['Onset', data.complaint.onset], ['Duration', data.complaint.duration]
  ]);
  if (data.complaint.redFlags && data.complaint.redFlags.length) kvBlock([['Red Flags', data.complaint.redFlags.join(', ')]]);

  // Relevant History
  if (data.history) {
    var histPairs = [];
    if (data.history.conditions && data.history.conditions.length) histPairs.push(['Conditions', data.history.conditions.join(', ')]);
    if (data.history.medications && data.history.medications.length) histPairs.push(['Medications', data.history.medications.map(medicationDisplayText).join('; ')]);
    if (data.history.allergies) histPairs.push(['Allergies', data.history.allergies]);
    if (data.history.surgHx) histPairs.push(['Surgical Hx', data.history.surgHx]);
    if (data.history.famHx) histPairs.push(['Family Hx', data.history.famHx]);
    if (histPairs.length) { heading('Relevant History'); kvBlock(histPairs); }
  }

  // Each active region
  (data.activeRegions || []).forEach(function(r) {
    var R = (typeof REGIONS !== 'undefined') ? REGIONS[r] : null;
    var D = (data.examData && data.examData[r]) || {};
    heading((R ? R.name : r) + ' Examination' + (D.side ? ' (' + D.side + ')' : ''));

    subheading('Subjective');
    kvRow([['VAS', (D.vas != null && D.vas !== '' ? D.vas : 'N/A') + '/10'], ['Quality', (D.quality || []).join(', ')]]);
    if ((D.aggFactors || []).length) kvBlock([['Aggravating', (D.aggFactors || []).join(', ') + (D.aggOther ? '; ' + D.aggOther : '')]]);
    if ((D.relFactors || []).length) kvBlock([['Relieving', (D.relFactors || []).join(', ') + (D.relOther ? '; ' + D.relOther : '')]]);

    if (R && R.rom && R.rom.length) {
      var romRows = [];
      var romMap = {}, romOrder = [];
      ROMDATA.entries(r, D).forEach(function (e) { var k2 = e.i + '|' + e.side; if (!romMap[k2]) { romMap[k2] = { e: e }; romOrder.push(k2); } romMap[k2][e.mode] = e; });
      romOrder.forEach(function (k2) { var m = romMap[k2], A = m.A || {}, Pp = m.P || {}, nn = ROMDATA.norm(r, m.e.i).deg;
        romRows.push([ROMDATA.label(m.e) + (nn != null ? ' (' + nn + '\u00B0)' : ''), (A.deg || '-') + (A.grade && A.grade !== 'Full' ? ' ' + A.grade.split(' ')[0].toLowerCase() : ''), A.pain || '-', Pp.deg || '-', Pp.ef || '-']); });
      if (romRows.length) { subheading('Range of Motion'); table(['Movement', 'Act.', 'Pain', 'Pas.', 'End Feel'], romRows, [tw*0.36, tw*0.14, tw*0.14, tw*0.14, tw*0.22]); }
    }

    if (R && R.ortho && R.ortho.length) {
      var orthoRows = [];
      for (var j = 0; j < R.ortho.length; j++) {
        var t = R.ortho[j];
        if (D['ort_R_'+t] || D['ort_L_'+t] || D['ort_note_'+t]) {
          orthoRows.push([t, D['ort_R_'+t] || '-', D['ort_L_'+t] || '-', D['ort_note_'+t] || '']);
        }
      }
      if (orthoRows.length) { subheading('Orthopedic Tests'); table(['Test', 'Right', 'Left', 'Notes'], orthoRows, [tw*0.30, tw*0.15, tw*0.15, tw*0.40]); }
    }

    if (D.primaryDx || D.secondaryDx || D.clinicalImpression || D.ddx || D.prognosis) {
      subheading('Assessment');
      var aPairs = [];
      if (D.primaryDx) aPairs.push(['Primary Dx', D.primaryDx + (D.icd10 ? '  (' + D.icd10 + ')' : '')]);
      if (D.secondaryDx) aPairs.push(['Secondary Dx', D.secondaryDx + (D.icd10_2 ? '  (' + D.icd10_2 + ')' : '')]);
      if (D.extCause) aPairs.push(['External Cause', D.extCause]);
      if (D.ddx) aPairs.push(['Differential', D.ddx]);
      if (D.clinicalImpression) aPairs.push(['Clinical Impression', D.clinicalImpression]);
      if (D.prognosis) aPairs.push(['Prognosis', D.prognosis]);
      kvBlock(aPairs);
    }

    var planPairs = [];
    if (D.txMods && D.txMods.length) planPairs.push(['Modalities', D.txMods.join(', ')]);
    if (D.biopunctureMeds && D.biopunctureMeds.length) planPairs.push(['Biopuncture', D.biopunctureMeds.join(', ') + (D.biopunctureNotes ? ' - ' + D.biopunctureNotes : '')]);
    if (D.bioflexLevel) planPairs.push(['Bioflex Laser', D.bioflexLevel + (D.bioflexNotes ? ' - ' + D.bioflexNotes : '')]);
    if (planPairs.length || D.postVas || D.compliance) {
      subheading('Plan / Treatment');
      if (planPairs.length) kvBlock(planPairs);
      if (D.postVas || D.compliance) {
        kvRow([['Post-Tx VAS', (D.postVas != null && D.postVas !== '' ? D.postVas : 'N/A') + '/10'], ['Compliance', (D.compliance != null && D.compliance !== '' ? D.compliance : 'N/A') + '/5']]);
      }
    }
  });

  if (data.report) { heading('Report of Findings'); paragraph(data.report); }

  if (data.exercises && ((data.exercises.selected && data.exercises.selected.length) || data.exercises.custom)) {
    heading('Exercise Prescription');
    if (data.exercises.region) kvRow([['Target Region', data.exercises.region], ['', '']]);
    if (data.exercises.selected && data.exercises.selected.length) {
      var exRows = [];
      for (var k = 0; k < data.exercises.selected.length; k++) {
        var ex = data.exercises.selected[k];
        exRows.push([String(k+1), ex.name || '-', ex.rx || '-']);
      }
      table(['#', 'Exercise', 'Prescription'], exRows, [tw*0.08, tw*0.52, tw*0.40]);
    }
    if (data.exercises.custom) kvBlock([['Custom Instructions', data.exercises.custom]]);
  }

  if (data.iceHeat && (data.iceHeat.modality || data.iceHeat.custom)) {
    heading('Home Care - Ice / Heat');
    kvRow([
      ['Modality', data.iceHeat.modality], ['Area', data.iceHeat.area],
      ['Duration', data.iceHeat.duration], ['Frequency', data.iceHeat.frequency]
    ]);
    if (data.iceHeat.custom) kvBlock([['Additional', data.iceHeat.custom]]);
  }

  drawFooter(pageNum);
  streams.push(s);

  // ============ BUILD PDF BYTES ============
  var objs = [];
  function obj(content) { objs.push(content); return objs.length; }
  obj('<< /Type /Catalog /Pages 2 0 R >>');
  obj('PAGES_PLACEHOLDER');
  obj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
  obj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  obj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Oblique /Encoding /WinAnsiEncoding >>');
  var lhRes = LHP.emit(obj);
  var pageRefs = [];
  for (var p = 0; p < streams.length; p++) {
    var streamBytes = streams[p];
    var streamObjNum = obj('<< /Length ' + streamBytes.length + ' >>\nstream\n' + streamBytes + 'endstream');
    var pageObjNum = obj('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+pw.toFixed(2)+' '+ph.toFixed(2)+'] /Contents '+streamObjNum+' 0 R /Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R >>' + (lhRes ? ' /XObject <<' + lhRes + ' >>' : '') + ' >> >>');
    pageRefs.push(pageObjNum + ' 0 R');
  }
  objs[1] = '<< /Type /Pages /Kids [' + pageRefs.join(' ') + '] /Count ' + streams.length + ' >>';
  var pdf = '%PDF-1.4\n', offsets = [];
  for (var i = 0; i < objs.length; i++) {
    offsets.push(pdf.length);
    pdf += (i+1) + ' 0 obj\n' + objs[i] + '\nendobj\n';
  }
  var xrefOffset = pdf.length;
  pdf += 'xref\n0 ' + (objs.length+1) + '\n0000000000 65535 f \n';
  for (var i = 0; i < offsets.length; i++) pdf += String(offsets[i]).padStart(10,'0') + ' 00000 n \n';
  pdf += 'trailer\n<< /Size '+(objs.length+1)+' /Root 1 0 R >>\nstartxref\n'+xrefOffset+'\n%%EOF';
  return pdf;
}

function exportPDF() {
  if (typeof ensureDxConfirmedForSave === 'function' && !ensureDxConfirmedForSave('export')) return;
  var data = gatherAllData();
  var errs = validatePatientForExport(data);
  if (errs.length) { showToast('Please enter ' + errs.join(' and ') + ' before exporting'); return; }
  if (window.CCPractice && !CCPractice.requireAll('Exam record PDF', false)) return; // P1 latest v4: practitioner fields come from the Profile
  try {
    showToast('Generating PDF...');
    var pdfStr = buildExamPDF(data);
    var bytes = new Uint8Array(pdfStr.length);
    for (var i = 0; i < pdfStr.length; i++) bytes[i] = pdfStr.charCodeAt(i) & 0xFF;
    var blob = new Blob([bytes], { type: 'application/pdf' });
    var fileName = makeEzmedFilename(data, 'pdf');
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(function(){ URL.revokeObjectURL(a.href); }, 1500);
    var pname = (data.patient.firstName + ' ' + data.patient.lastName).trim() || 'patient';
    setTimeout(function(){ showToast('PDF saved. Upload to ezmed patient file for ' + pname); }, 400);
  } catch(err) {
    console.error(err);
    showToast('PDF error: ' + (err.message || err));
  }
}

// ============================================
// .EZMED FILE IMPORT (Offline)
// ============================================
function loadEzmedIntake() { document.getElementById('ezmedLoadInput').click(); }

function handleEzmedLoad(e) {
  var file = e.target.files[0]; if (!file) return;
  var reader = new FileReader();
  reader.onload = function(ev) {
    try {
      var ezmed = JSON.parse(ev.target.result);
      if (ezmed._format !== 'ezmed' || ezmed._type !== 'patient_intake') {
        showToast('Not a valid intake .ezmed file'); return;
      }
      var mapped = mapEzmedToChiroClinic(ezmed);
      restoreData(mapped);
      showToast('Intake imported — ' + (ezmed.patientInformation && ezmed.patientInformation.name ? ezmed.patientInformation.name.firstName || '' : '') + ' ' + (ezmed.patientInformation && ezmed.patientInformation.name ? ezmed.patientInformation.name.lastName || '' : ''));
    } catch(err) { console.error(err); showToast('Error loading intake file'); }
  };
  reader.readAsText(file);
  e.target.value = '';
}

function mapEzmedToChiroClinic(ez) {
  var pi = ez.patientInformation || {};
  var pc = ez.primaryComplaint || {};
  var subj = ez.subjective || {};
  var mh = ez.medicalHistory || {};
  var sh = ez.socialHistory || {};
  var regionMap = {
    'Cervical / Thoracic Spine': ['cs','ts'], 'Cervical Spine': ['cs'], 'Thoracic Spine': ['ts'],
    'Lumbar spine and Pelvis': ['ls','pelvis'], 'Lumbar Spine': ['ls'], 'Pelvis/SI': ['pelvis'],
    'Shoulder': ['shoulder'], 'Elbow': ['elbow'], 'Wrist': ['wrist'], 'Wrist/Fingers': ['wrist'],
    'Hip': ['hip'], 'Knee': ['knee'], 'Ankle / Foot': ['ankle'], 'Ankle/Foot': ['ankle']
  };
  var activeRegions = [];
  if (pc.affectedRegions && Array.isArray(pc.affectedRegions)) {
    pc.affectedRegions.forEach(function(ar) {
      var keys = regionMap[ar] || [];
      keys.forEach(function(k) { if (activeRegions.indexOf(k) === -1) activeRegions.push(k); });
    });
  }
  var examData = {};
  activeRegions.forEach(function(r) {
    examData[r] = { side:'Both', vas: subj.vasPainScale ? subj.vasPainScale.current || 0 : 0,
      quality: subj.quality || [], aggFactors: subj.aggravatingFactors || [],
      aggOther: subj.aggravatingOther || '', relFactors: subj.relievingFactors || [],
      relOther: subj.relievingOther || '', assocSymptoms: subj.associatedSymptoms || [] };
  });
  var complaintRegion = '';
  if (activeRegions.indexOf('cs') >= 0) complaintRegion = 'Cervical Spine';
  else if (activeRegions.indexOf('ls') >= 0) complaintRegion = 'Lumbar Spine';
  else if (activeRegions.indexOf('ts') >= 0) complaintRegion = 'Thoracic Spine';
  else if (activeRegions.indexOf('hip') >= 0) complaintRegion = 'Hip';
  else if (activeRegions.indexOf('pelvis') >= 0) complaintRegion = 'Pelvis/SI';
  else if (activeRegions.indexOf('shoulder') >= 0) complaintRegion = 'Shoulder';
  else if (activeRegions.indexOf('elbow') >= 0) complaintRegion = 'Elbow';
  else if (activeRegions.indexOf('wrist') >= 0) complaintRegion = 'Wrist/Fingers';
  else if (activeRegions.indexOf('knee') >= 0) complaintRegion = 'Knee';
  else if (activeRegions.indexOf('ankle') >= 0) complaintRegion = 'Ankle/Foot';
  var smoking = 'Non-smoker';
  if (sh.smoking === 'Yes') smoking = 'Current smoker';
  else if (sh.smoking === 'Previously') smoking = 'Ex-smoker';
  var alcohol = 'None';
  if (sh.alcohol === 'Social') alcohol = 'Social';
  else if (sh.alcohol === 'Moderate') alcohol = 'Moderate';
  else if (sh.alcohol === 'Heavy') alcohol = 'Heavy';
  var exercise = 'Sedentary';
  if (sh.exercise === 'Light') exercise = 'Light';
  else if (sh.exercise === 'Moderate') exercise = 'Moderate';
  else if (sh.exercise === 'Regular' || sh.exercise === 'Intense') exercise = 'Active';
  return {
    patient: { firstName: pi.name ? pi.name.firstName || '' : '', lastName: pi.name ? pi.name.lastName || '' : '',
      dob: pi.dateOfBirth || '', id: pi.patientIdNumber || '', gender: pi.gender || '',
      phone: pi.phone || '', email: pi.email || '', medAid: pi.medicalAid ? pi.medicalAid.provider || '' : '',
      medAidNo: pi.medicalAid ? pi.medicalAid.number || '' : '', fileNo: pi.fileNumber || '' },
    visit: { type:'new', date: localISODate(), caseNo:'' },
    complaint: { region: complaintRegion, side:'', onset: pc.onset || '', duration: pc.duration || '',
      frequency: subj.painFrequency || pc.frequency || '', prevTx: pc.previousTreatment || '',
      prevTxDate: pc.dateOfPreviousTreatment || '', prevTxCount: pc.numberOfPreviousTreatments || '',
      prevResponse: pc.responseToPreviousTreatment || '', redFlags: [] },
    history: { conditions: mh.conditions || [], condOther:'', allergies: mh.allergies || '',
      medications: mh.medications || mh.currentMedications || [], medicationDbVersion: MEDICATION_DB_VERSION,
      surgHx: mh.previousSurgeries || '', famHx: mh.familyHistory || '',
      social: { smoking: smoking, alcohol: alcohol, exercise: exercise, occupation: pi.occupation || '' } },
    activeRegions: activeRegions, examData: examData, bodyMapData: pc.bodyMap || null,
    photos: [], iceHeat: {}, exercises: {}, report: ''
  };
}




// ============================================
// V4.5.4 FREE NOTES — isolated top-level section
// ============================================
let FREE_NOTE_REC = null;
let FREE_CANVAS_READY = false;
let FREE_CANVAS_DRAWING = false;
function freeNoteStatus(msg, bad) { const el = document.getElementById('freeNotesStatus'); if (el) { el.textContent = msg; el.style.color = bad ? '#C0392B' : 'var(--text3)'; } }
function initFreeNotesCanvas() {
  const canvas = document.getElementById('freeNoteCanvas');
  if (!canvas || FREE_CANVAS_READY) { loadFreeNotes(); return; }
  FREE_CANVAS_READY = true;
  const ctx = canvas.getContext('2d'); ctx.lineWidth = 2.5; ctx.lineCap = 'round'; ctx.strokeStyle = '#2D2D2D';
  function pos(ev) { const r = canvas.getBoundingClientRect(); const t = ev.touches && ev.touches[0] ? ev.touches[0] : ev; return { x: (t.clientX - r.left) * (canvas.width / r.width), y: (t.clientY - r.top) * (canvas.height / r.height) }; }
  function down(ev){ ev.preventDefault(); FREE_CANVAS_DRAWING = true; const p = pos(ev); ctx.beginPath(); ctx.moveTo(p.x,p.y); }
  function move(ev){ if(!FREE_CANVAS_DRAWING) return; ev.preventDefault(); const p = pos(ev); ctx.lineTo(p.x,p.y); ctx.stroke(); }
  function up(ev){ if(!FREE_CANVAS_DRAWING) return; ev.preventDefault(); FREE_CANVAS_DRAWING = false; saveFreeNotes(); }
  canvas.addEventListener('mousedown', down); canvas.addEventListener('mousemove', move); window.addEventListener('mouseup', up);
  canvas.addEventListener('touchstart', down, {passive:false}); canvas.addEventListener('touchmove', move, {passive:false}); canvas.addEventListener('touchend', up, {passive:false});
  loadFreeNotes();
}
function saveFreeNotes() {
  try { const box = document.getElementById('freeNotesText'); const canvas = document.getElementById('freeNoteCanvas'); const payload = { text: box ? box.value : '', canvas: canvas ? canvas.toDataURL('image/png') : '' }; localStorage.setItem('chiroclinic_free_notes_v454', JSON.stringify(payload)); APP.freeNotes = payload; freeNoteStatus('Free notes saved.'); } catch(e) { freeNoteStatus('Could not save free notes: ' + e.message, true); }
}
function loadFreeNotes() {
  try { const raw = localStorage.getItem('chiroclinic_free_notes_v454'); if (!raw) return; const payload = JSON.parse(raw); const box = document.getElementById('freeNotesText'); if (box && payload.text && !box.value) box.value = payload.text; const canvas = document.getElementById('freeNoteCanvas'); if (canvas && payload.canvas) { const img = new Image(); img.onload = function(){ canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height); }; img.src = payload.canvas; } APP.freeNotes = payload; } catch(e) {}
}
function clearFreeNoteCanvas() { const canvas = document.getElementById('freeNoteCanvas'); if (!canvas) return; canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height); saveFreeNotes(); }
function startFreeNotesDictation() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) { freeNoteStatus('Browser dictation unavailable. Use the iPad keyboard microphone inside the text box.', true); return; }
  stopFreeNotesDictation(); const rec = new SpeechRecognition(); FREE_NOTE_REC = rec; rec.continuous = true; rec.interimResults = false; rec.lang = 'en-ZA';
  rec.onstart = function(){ freeNoteStatus('Listening for free note dictation…'); };
  rec.onerror = function(ev){ freeNoteStatus('Dictation error: ' + (ev.error || 'unknown'), true); };
  rec.onresult = function(ev){ const box = document.getElementById('freeNotesText'); if (!box) return; for (let i=ev.resultIndex; i<ev.results.length; i++) { if (!ev.results[i].isFinal) continue; const t = (ev.results[i][0].transcript || '').trim(); if (t) box.value += (box.value ? '\n' : '') + t; } saveFreeNotes(); };
  try { rec.start(); } catch(e) { freeNoteStatus('Could not start dictation: ' + e.message, true); }
}
function stopFreeNotesDictation() { if (FREE_NOTE_REC) { try { FREE_NOTE_REC.stop(); } catch(e) {} FREE_NOTE_REC = null; } freeNoteStatus('Free-note dictation stopped / ready.'); }
function extractFreeNoteValue(label, text) { const re = new RegExp('(?:^|\\n|;|\\.)\\s*(?:' + label + ')\\s*[:\\-]\\s*([^\\n;.]+)', 'i'); const m = text.match(re); return m ? m[1].trim() : ''; }
function populateFieldsFromFreeNotes() {
  const box = document.getElementById('freeNotesText'); const text = box ? box.value : ''; let count = 0;
  function setIf(id, val) { const el = document.getElementById(id); if (el && val) { el.value = val; count++; } }
  setIf('allergies', extractFreeNoteValue('allergies?', text)); setIf('shOccupation', extractFreeNoteValue('occupation|work', text)); setIf('pcDuration', extractFreeNoteValue('duration', text)); setIf('pcFrequency', extractFreeNoteValue('frequency', text)); setIf('pcPrevTx', extractFreeNoteValue('previous treatment|prior treatment', text)); setIf('condOther', extractFreeNoteValue('other conditions?|conditions?', text));
  const red = extractFreeNoteValue('red flags?', text); if (red) { document.querySelectorAll('#redFlags .chip').forEach(function(c){ if (red.toLowerCase().includes((c.dataset.val || c.textContent).toLowerCase())) { c.classList.add('active'); count++; } }); }
  saveFreeNotes(); freeNoteStatus(count ? ('Populated ' + count + ' matching field(s). Review before finalising.') : 'No labelled matching fields found. Use labels such as Allergies:, Occupation:, Duration:, Frequency:, Previous treatment:, Red flags:.', !count);
}
function appendFreeNotesToReport() { const box = document.getElementById('freeNotesText'); const text = box ? box.value.trim() : ''; if (!text) { freeNoteStatus('No free note text to add.', true); return; } const target = document.getElementById('reportExtraNotes') || document.getElementById('aiExtraNotes') || document.querySelector('#sec-report textarea'); if (target) { target.value += (target.value ? '\n\n' : '') + 'Additional free clinical notes:\n' + text; freeNoteStatus('Added free notes to report notes.'); } else { try { navigator.clipboard && navigator.clipboard.writeText(text); } catch(e) {} freeNoteStatus('Could not find report-notes box. Free notes copied to clipboard if browser allowed it.'); } }

// ============================================
// V4.5.4 FLOATING DICTATION — isolated from original exam rendering
// ============================================
let FLOAT_DICT = { recognition:null, listening:false, lastText:'', lastAt:0, continuous:false };

function toggleFloatingDictation(force) {
  const panel = document.getElementById('dictFloatPanel');
  if (!panel) return;
  const open = typeof force === 'boolean' ? force : !panel.classList.contains('open');
  panel.classList.toggle('open', open);
  const toggle = document.getElementById('dictFloatToggle');
  if (toggle) {
    toggle.classList.toggle('dictation-active', open);
    toggle.setAttribute('aria-expanded', String(open));
  }
  if (open) positionFloatingDictationPanel();
}

function positionFloatingDictationPanel() {
  const panel = document.getElementById('dictFloatPanel');
  const header = document.querySelector('.header');
  if (!panel || !header) return;
  const top = Math.max(8, Math.ceil(header.getBoundingClientRect().bottom) + 8);
  panel.style.top = top + 'px';
  panel.style.maxHeight = 'calc(100vh - ' + (top + 10) + 'px)';
}

window.addEventListener('resize', function(){
  if (document.getElementById('dictFloatPanel')?.classList.contains('open')) positionFloatingDictationPanel();
});

function dictStatus(msg, ok) {
  const s = document.getElementById('dictFloatStatus');
  if (s) { s.textContent = msg; s.style.color = ok === false ? '#C0392B' : 'var(--text2)'; }
  const log = document.getElementById('dictFloatLog');
  if (log) {
    const line = document.createElement('div');
    line.textContent = new Date().toLocaleTimeString() + ' — ' + msg;
    log.prepend(line);
  }
}

function dictBeep(ok) {
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.value = ok ? 880 : 220;
    gain.gain.value = 0.06;
    osc.connect(gain); gain.connect(ctx.destination);
    osc.start();
    setTimeout(function(){ osc.stop(); ctx.close(); }, ok ? 110 : 180);
  } catch(e) {}
}

function currentDictRegion() {
  const sel = document.getElementById('dictRegion');
  let r = sel ? sel.value : 'current';
  if (r === 'current') r = APP.currentRegion || (APP.activeRegions && APP.activeRegions[APP.activeRegions.length - 1]) || 'cs';
  r = (typeof resolveExamRegion === 'function' && resolveExamRegion(r)) || null;
  if (!r) return null;
  if (!APP.activeRegions.includes(r)) APP.activeRegions.push(r);
  APP.currentRegion = r;
  return r;
}

function startFloatingDictation(continuous) {
  toggleFloatingDictation(true);
  stopFloatingDictation(true);
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) {
    dictStatus('Speech recognition not available in this browser. Use iPad keyboard microphone in the manual box.', false);
    dictBeep(false);
    return;
  }
  const rec = new SpeechRecognition();
  FLOAT_DICT.recognition = rec;
  FLOAT_DICT.continuous = !!continuous;
  rec.continuous = !!continuous;
  rec.interimResults = false;
  rec.lang = 'en-ZA';
  rec.onstart = function(){ FLOAT_DICT.listening = true; dictStatus(continuous ? 'Continuous dictation listening…' : 'Listening for one command…'); };
  rec.onerror = function(ev){ FLOAT_DICT.listening = false; dictStatus('Dictation error: ' + (ev.error || 'unknown'), false); dictBeep(false); };
  rec.onend = function(){ FLOAT_DICT.listening = false; if (FLOAT_DICT.continuous) dictStatus('Continuous dictation stopped.'); };
  rec.onresult = function(ev) {
    for (let i = ev.resultIndex; i < ev.results.length; i++) {
      if (!ev.results[i].isFinal) continue;
      const text = (ev.results[i][0].transcript || '').trim();
      if (!text) continue;
      const now = Date.now();
      const key = text.toLowerCase().replace(/\s+/g,' ');
      if (FLOAT_DICT.lastText === key && now - FLOAT_DICT.lastAt < 2500) {
        dictStatus('Duplicate ignored: ' + text);
        continue;
      }
      FLOAT_DICT.lastText = key; FLOAT_DICT.lastAt = now;
      applyFloatingDictationCommand(text);
    }
  };
  try { rec.start(); } catch(e) { dictStatus('Could not start dictation: ' + e.message, false); dictBeep(false); }
}

function stopFloatingDictation(silent) {
  FLOAT_DICT.continuous = false;
  if (FLOAT_DICT.recognition) {
    try { FLOAT_DICT.recognition.stop(); } catch(e) {}
    FLOAT_DICT.recognition = null;
  }
  FLOAT_DICT.listening = false;
  if (!silent) dictStatus('Dictation stopped.');
}

function applyFloatingDictationManual() {
  const box = document.getElementById('dictManualText');
  const text = box ? box.value.trim() : '';
  if (!text) { dictStatus('No typed/dictated text to apply.', false); dictBeep(false); return; }
  const parts = text.split(/\n+|;+/).map(x => x.trim()).filter(Boolean);
  let okCount = 0;
  parts.forEach(function(cmd){ if (applyFloatingDictationCommand(cmd, true)) okCount++; });
  if (okCount) { dictStatus('Applied ' + okCount + ' command(s).'); dictBeep(true); }
}

function normalizeDictText(t) {
  let x = String(t || '').toLowerCase();
  const nums = { zero:'0', one:'1', two:'2', three:'3', four:'4', five:'5', six:'6', seven:'7', eight:'8', nine:'9', ten:'10', twenty:'20', thirty:'30', forty:'40', fourty:'40', fifty:'50', sixty:'60', seventy:'70', eighty:'80', ninety:'90' };
  Object.keys(nums).forEach(function(w){ x = x.replace(new RegExp('\b'+w+'\b','g'), nums[w]); });
  return x
    .replace(/degrees?|degree/g,'')
    .replace(/positive/g,'+')
    .replace(/negative/g,'-')
    .replace(/not painful|no pain|pain free|pain-free|without pain/g,'pain no')
    .replace(/painful|hurts|sore|with pain|pain present/g,'pain yes')
    .replace(/unrestricted|full range|full movement|not restricted/g,'restriction no')
    .replace(/restricted|limited|reduced range|decreased range|stiff|tight/g,'restriction yes')
    .replace(/orthopedic/g,'orthopaedic')
    .replace(/spurlings/g,'spurling')
    .replace(/slr/g,'straight leg raise')
    .replace(/\s+/g,' ').trim();
}

function applyFloatingDictationCommand(raw, manualMode) {
  const region = currentDictRegion();
  if (!region) { dictStatus('Choose an exam region first. Dictation will not fall back to a neighbouring region.', false); dictBeep(false); return false; }
  const R = REGIONS[region];
  const D = getExamData(region);
  const targetSel = document.getElementById('dictTarget');
  const target = targetSel ? targetSel.value : 'auto';
  const text = normalizeDictText(raw);
  let ok = false;
  if (!text) return false;

  // P1 v13: pelvis ROM is no longer recorded (hip range of motion lives under the Hip tab). ROM dictated while the Pelvis tab is open goes to Hip.
  const romRegion = region === 'pelvis' && REGIONS.hip ? 'hip' : region, romR = REGIONS[romRegion], romD = romRegion === region ? D : getExamData(romRegion);
  let romRouted = false;
  if (target === 'activeRom' || target === 'auto') ok = applyDictRom(romRegion, romR, romD, text, 'A') || ok;
  if (!ok && (target === 'passiveRom' || target === 'auto')) ok = applyDictRom(romRegion, romR, romD, text, 'P') || ok;
  if (ok && romRegion !== region) { romRouted = true; if (!APP.activeRegions) APP.activeRegions = []; if (APP.activeRegions.indexOf(romRegion) < 0) APP.activeRegions.push(romRegion); }
  if (!ok && (target === 'ortho' || target === 'auto')) ok = applyDictOrtho(region, R, D, text) || ok;
  if (!ok && (target === 'derm' || target === 'auto')) ok = applyDictDerm(region, R, D, text) || ok;
  if (!ok && (target === 'myo' || target === 'auto')) ok = applyDictMyo(region, R, D, text) || ok;
  if (!ok && (target === 'reflex' || target === 'auto')) ok = applyDictReflex(region, R, D, text) || ok;
  if (!ok && (target === 'palp' || target === 'auto')) ok = applyDictNote(region, D, raw) || ok;

  if (ok) {
    try { renderRegionTabs(); showSoapTab('obj', document.querySelector('#sec-exam .soap-tab:nth-child(2)') || document.querySelector('.soap-tab')); } catch(e) { try { renderRegionTabs(); } catch(_) {} }
    dictStatus('Accepted: ' + raw + ' → ' + (romRouted ? (REGIONS.hip.abbr || 'Hip') + ' (hip range of motion is recorded under Hip)' : R.abbr));
    dictBeep(true);
  } else {
    dictStatus('Not understood: ' + raw, false);
    dictBeep(false);
  }
  return ok;
}

function movementIndex(R, text) {
  let best = -1, bestScore = 0;
  const tx = text.replace(/flex/g,'flexion').replace(/extend/g,'extension').replace(/rotate/g,'rotation').replace(/abduct/g,'abduction').replace(/adduct/g,'adduction');
  R.rom.forEach(function(m, i){
    const name = m.name.toLowerCase();
    let score = 0;
    name.split(/\s+/).forEach(function(w){ if (w.length > 2 && tx.includes(w)) score++; });
    if (name.includes('right') && tx.includes('right')) score += 2;
    if (name.includes('left') && tx.includes('left')) score += 2;
    if (tx.includes(name)) score += 4;
    if (score > bestScore) { bestScore = score; best = i; }
  });
  return bestScore ? best : -1;
}

function applyDictRom(region, R, D, text, mode) {
  if (mode === 'A' && text.includes('passive')) return false;
  if (mode === 'P' && text.includes('active')) return false;
  if (mode === 'A' && !(text.includes('active') || ['flexion','extension','rotation','abduction','adduction','pronation','supination','deviation'].some(w => text.includes(w)))) return false;
  if (mode === 'P' && !(text.includes('passive') || text.includes('end feel'))) return false;
  const idx0 = movementIndex(R, text);
  if (idx0 < 0) return false;
  // P1 item 10: limb regions store R and L separately. Side from the dictation ("right"/"left"), else the region side; if neither, the unsided (side not recorded) key.
  const dSide = ROMDATA.sided(region) ? (/\bleft\b/.test(text) ? 'L' : /\bright\b/.test(text) ? 'R' : ROMDATA.legacySide(D)) : '';
  const idx = idx0 + (dSide ? '_' + dSide : '');
  const num = text.match(/\b(\d{1,3})\b/);
  if (num) D['rom' + mode + '_deg_' + idx] = num[1];
  if (text.includes('pain yes')) D['rom' + mode + '_pain_' + idx] = 'Yes';
  if (text.includes('pain no')) D['rom' + mode + '_pain_' + idx] = 'No';
  if (mode === 'A') {
    if (text.includes('restriction yes')) D['romA_rest_' + idx] = 'Yes';
    if (text.includes('restriction no')) D['romA_rest_' + idx] = 'No';
  } else {
    ['bony','capsular','springy','spasm','empty'].forEach(function(ef){ if (text.includes(ef)) D['romP_ef_' + idx] = ef.charAt(0).toUpperCase()+ef.slice(1); });
  }
  return !!(num || text.includes('pain') || text.includes('restriction') || text.includes('end feel'));
}

function sideFromText(text) {
  if (text.includes('right')) return 'R';
  if (text.includes('left')) return 'L';
  return '';
}
function resultFromText(text) {
  if (text.includes('+') || text.includes('positive')) return '+';
  if (text.includes('-') || text.includes('negative')) return '-';
  if (text.includes('normal')) return 'Normal';
  if (text.includes('reduced') || text.includes('decreased')) return 'Reduced';
  if (text.includes('absent')) return 'Absent';
  if (text.includes('increased')) return 'Increased';
  return '';
}

function applyDictOrtho(region, R, D, text) {
  let hit = R.ortho.find(function(t){
    const simple = t.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
    return simple.split(/\s+/).filter(w => w.length > 2).some(w => text.includes(w));
  });
  if (!hit) return false;
  const side = sideFromText(text) || 'R';
  const res = resultFromText(text) || (text.includes('+') ? '+' : '');
  if (!res) return false;
  D['ort_' + side + '_' + hit] = res === 'Normal' ? '-' : res;
  return true;
}

function applyDictDerm(region, R, D, text) {
  if (!text.includes('dermatome') && !/^c\d|^t\d|^l\d|^s\d/.test(text)) return false;
  const level = (R.dermatomes || []).find(d => text.includes(d.toLowerCase()));
  if (!level) return false;
  const side = sideFromText(text); if (!side) return false;
  const res = resultFromText(text) || 'Reduced';
  D['derm_' + side + '_' + level] = res === '+' || res === '-' ? 'Reduced' : res;
  return true;
}

function applyDictMyo(region, R, D, text) {
  if (!text.includes('myotome')) return false;
  const item = (R.myotomes || []).find(m => text.includes(m.level.toLowerCase()) || m.name.toLowerCase().split(/[^a-z0-9]+/).some(w => w.length > 3 && text.includes(w)));
  if (!item) return false;
  const side = sideFromText(text); if (!side) return false;
  const val = (text.match(/\b([0-5])\b/) || [,'4'])[1];
  D['myo_' + side + '_' + item.level] = val;
  return true;
}

function applyDictReflex(region, R, D, text) {
  if (!text.includes('reflex')) return false;
  const item = (R.reflexes || []).find(r => r.name.toLowerCase().split(/[^a-z0-9]+/).some(w => w.length > 3 && text.includes(w)) || text.includes(r.level.toLowerCase()));
  if (!item) return false;
  const side = sideFromText(text); if (!side) return false;
  let val = '+2';
  if (text.includes('absent') || text.includes('zero')) val = '0';
  else if (text.includes('reduced') || text.includes('decreased')) val = '+1';
  else if (text.includes('increased') || text.includes('brisk')) val = '+3';
  else if (text.includes('clonus') || text.includes('hyper')) val = '+4';
  const n = text.match(/\b([0-4])\b/); if (n) val = n[1] === '0' ? '0' : '+' + n[1];
  D['ref_' + side + '_' + item.level] = val;
  return true;
}

function applyDictNote(region, D, raw) {
  const t = String(raw || '').trim();
  if (!t) return false;
  if (!/^note\b|palpation|observation|tender|spasm|trigger|guarding/i.test(t)) return false;
  const clean = t.replace(/^note\s*/i,'');
  D.palpNotes = (D.palpNotes ? D.palpNotes + '\n' : '') + clean;
  return true;
}

